APP_NAME = "NetPulse"
APP_VERSION = "1.24.0"
# JSON 结果 Schema 版本 (对应 schema/netpulse-result-v{主.次}.json 文件)。
# 唯一来源 — build_report / --json-schema / debug-bundle 三处统一消费。
SCHEMA_VERSION = "1.2.0"
SCHEMA_FILENAME = f"netpulse-result-v{SCHEMA_VERSION.rsplit('.', 1)[0]}.json"

# ------------------------------------------------------------
# 更新检查 (v1.12.0): 启动时后台查最新 Release, 有新版本时在交互菜单
# 标题下提示一行 (含 gh-proxy 加速下载链接)。设计约束:
#   - daemon 线程 + 短超时, 失败完全静默 — 离线/被墙用户零感知,
#     绝不拖慢启动 (v1.9.7 性能红线), 不污染 --json 输出 (只在菜单显示)
#   - 双源: GitHub Releases API 官方 → jsDelivr CDN 回落 (国内可达;
#     读仓库根 version.json, 发版时须同步更新。v1.14.2 实测 @master 快照
#     可滞后数周 — 回落源说"没有新版本"不写频控缓存, 不锁死提示)
#   - 频控: %LOCALAPPDATA%\NetPulse\update_check.json 记录上次成功检查,
#     24h 内直接用缓存版本号不发请求; 失败不写缓存 (下次启动重试)
#     (v1.14.6: 启动路径改 force=True 每次真检查 — 频控曾让检查"看起来
#     没生效"; 频控机制仅保留给 force=False 调用方。NP_UPDATE_DEBUG=1
#     时 worker 在 stderr 打印源/耗时/结论, 便于现场排查)
GH_REPO = "silentcrow09/netpulse"
# 主源: GitHub Releases API (撞 quota 时走回落)
UPDATE_CHECK_API = f"https://api.github.com/repos/{GH_REPO}/releases/latest"
# 回落 1: gh-proxy 反代 GitHub API (不撞 60/h quota, 国内可达)
UPDATE_CHECK_API_PROXY = (f"https://gh-proxy.com/{UPDATE_CHECK_API}")
# 回落 2: gh-proxy 反代 raw.githubusercontent.com (拉到 master version.json)
UPDATE_CHECK_RAW_PROXY = (f"https://gh-proxy.com/"
                           f"https://raw.githubusercontent.com/{GH_REPO}/master/version.json")
# 回落 3: jsDelivr @master version.json (传统 CDN 镜像, 部分网络不稳,
# 作为最后一个兑底, 同时删其"无新版"可写缓存策略 — v1.14.2 规则继续适用)
UPDATE_CHECK_FALLBACK = (f"https://cdn.jsdelivr.net/gh/{GH_REPO}@master/"
                         "version.json")
UPDATE_DL_PROXY = "https://gh-proxy.com/"    # 国内加速前缀
UPDATE_CHECK_INTERVAL_S = 24 * 3600          # 自动检查最小间隔
UPDATE_CHECK_TIMEOUT_S = 5.0                 # 单源超时 (daemon 线程内, 不阻塞主流程)

_UPDATE_LOCK = threading.Lock()
# 后台检查结果 (菜单渲染时读取; 线程只写, 菜单只读, 锁保护元组更新)
_UPDATE_STATE = {"latest": None, "checked_at": 0.0, "is_new": False}


def _parse_version(text):
    """'v1.12.0' / '1.12.0' / '1.12' -> (1, 12, 0) / (1, 12); 无法解析 None。"""
    m = re.match(r"^[vV]?(\d+(?:\.\d+)+)", str(text or "").strip())
    if not m:
        return None
    return tuple(int(x) for x in m.group(1).split("."))


def _version_str(ver):
    return ".".join(map(str, ver))


def _version_newer(remote, local):
    """remote 是否严格大于 local (逐段数字比较, 缺段补 0; 解析失败 False)。"""
    r, l = _parse_version(remote), _parse_version(local)
    if not r or not l:
        return False
    n = max(len(r), len(l))
    return r + (0,) * (n - len(r)) > l + (0,) * (n - len(l))


def _fetch_latest_version(timeout=UPDATE_CHECK_TIMEOUT_S):
    """依次尝试 4 个源: 主源 -> gh-proxy API -> gh-proxy raw -> jsDelivr。

    返回 (版本号, 源标识), 全失败 (None, None)。
    源标识: 'primary' / 'gh-proxy-api' / 'gh-proxy-raw' / 'jsdelivr' / None。
    v1.14.11 加两个 gh-proxy 回落源: 解决国内 jsDelivr 不达 (实测 curl -35 超时)
    + GitHub API quota 撞 (公司 NAT 共享 IP 常见) 的问题。
    """
    sources = (
        (UPDATE_CHECK_API, "primary"),
        (UPDATE_CHECK_API_PROXY, "gh-proxy-api"),
        (UPDATE_CHECK_RAW_PROXY, "gh-proxy-raw"),
        (UPDATE_CHECK_FALLBACK, "jsdelivr"),
    )
    for url, src in sources:
        try:
            with _urlopen_with_proxy(url, timeout=timeout) as resp:
                data = json.loads(resp.read(1 << 20).decode("utf-8", "replace"))
            # 主源 / gh-proxy API 返回 {tag_name: ...}, raw 反代/version.json
            # 返回 {version: ...} — 统一吃
            ver = _parse_version(data.get("tag_name") or data.get("version"))
            if ver:
                return _version_str(ver), src
        except Exception:
            continue    # 单源失败静默, 落到下一源
    return None, None


def _update_cache_path():
    base = os.environ.get("LOCALAPPDATA") or tempfile.gettempdir()
    return os.path.join(base, "NetPulse", "update_check.json")


def _load_update_cache(now):
    """读频控缓存; 新鲜 (24h 内) 返回 (ts, 版本号), 过期/损坏返回 (0.0, None)。"""
    try:
        with open(_update_cache_path(), encoding="utf-8") as f:
            data = json.load(f)
        ts = float(data.get("checked_at") or 0)
        ver = _parse_version(data.get("latest"))
        if not ver or now - ts > UPDATE_CHECK_INTERVAL_S:
            return 0.0, None
        return ts, _version_str(ver)
    except Exception:
        return 0.0, None


def _save_update_cache(now, latest):
    """写频控缓存 (只在检查成功时调用; 失败静默 — 缓存不是关键数据)。"""
    try:
        p = _update_cache_path()
        os.makedirs(os.path.dirname(p), exist_ok=True)
        with open(p, "w", encoding="utf-8") as f:
            json.dump({"checked_at": now, "latest": latest}, f)
    except Exception:
        pass


def _check_update(force=False):
    """执行一次检查 (测试可直接调用)。返回最新版本号; 失败静默返回 None。

    force=True 跳过频控缓存强制联网; False 时 24h 内命中缓存不发请求。
    成功后更新 _UPDATE_STATE (菜单经 _update_notice_line 消费)。
    v1.14.11: from_primary 改为 from_source (str 标识: primary/gh-proxy-api/
    gh-proxy-raw/jsdelivr); 主源以外的所有源都视为"回落", 都会触发"新版本
    写缓存" — 因为现在回落源基本都是 gh-proxy, 同步性已足够。
    """
    now = time.time()
    if not force:
        ts, cached = _load_update_cache(now)
        if cached is not None:
            with _UPDATE_LOCK:
                _UPDATE_STATE.update(latest=cached, checked_at=ts,
                                     from_source=None,
                                     is_new=_version_newer(cached, APP_VERSION))
            return cached
    latest, from_source = _fetch_latest_version()
    if latest:
        # v1.14.2 修复: 回落源说"无新版"不可信 — 不写缓存 (下次重试).
        # v1.14.11 微调: gh-proxy 反代同步性接近主源, 故 "主源成功" 或
        # "任一源报确有新版" 才写缓存。
        # v1.14.14 订正注释: 原注释写"其他回落源也认定为足够可信写缓存",
        # 与下面这行条件相反 —— gh-proxy 回答"已是最新"同样不写。代码对、
        # 注释错, 已改。
        if from_source == "primary" or _version_newer(latest, APP_VERSION):
            _save_update_cache(now, latest)
        with _UPDATE_LOCK:
            _UPDATE_STATE.update(latest=latest, checked_at=now,
                                 from_source=from_source,
                                 is_new=_version_newer(latest, APP_VERSION))
    return latest


def _start_update_check(force=False):
    """启动后台更新检查线程 (daemon; 异常兜底静默, 永不影响主流程)。"""
    def _worker():
        try:
            t0 = time.monotonic()
            latest = _check_update(force=force)
            # NP_UPDATE_DEBUG=1: stderr 打印检查结果, 排查"更新检测是否生效"
            # (默认静默; 走 stderr 不污染 stdout, --json 输出保持纯净)
            if os.environ.get("NP_UPDATE_DEBUG"):
                with _UPDATE_LOCK:
                    st = dict(_UPDATE_STATE)
                if st.get("latest"):
                    src = {"primary": "GitHub API", "gh-proxy-api": "gh-proxy反代API",
                           "gh-proxy-raw": "gh-proxy拉raw", "jsdelivr": "jsDelivr",
                           "cache": "本地缓存"}.get(st.get("from_source"), "?")
                    print(f"[NetPulse] 更新检查 {time.monotonic() - t0:.1f}s: "
                          f"源={src}, 最新=v{st['latest']}, "
                          f"当前=v{APP_VERSION}, "
                          f"{'有新版!' if st.get('is_new') else '已是最新'}",
                          file=sys.stderr)
                else:
                    print(f"[NetPulse] 更新检查 {time.monotonic() - t0:.1f}s: "
                          f"四源全部失败 (被墙/quota/超时), 本次静默", file=sys.stderr)
        except Exception as e:
            # v1.17.0: 原先 `except Exception: pass` —— 四源全失败时连
            # NP_UPDATE_DEBUG 的输出都没有, 完全静默。
            _emit_thread_failure(e, "线程:update-check",
                                 detail="更新检查线程异常")
    t = threading.Thread(target=_worker, name="update-check", daemon=True)
    t.start()
    return t


def _prime_update_state_from_cache():
    """启动时用频控缓存预填显示状态 (线程结果稍后覆盖; v1.14.8)。

    force=True 的后台检查不读缓存 — 不预填的话, 新版本提示只能等线程
    完成后下一次菜单重绘才出现 (首帧必 miss, 用户以为没生效)。
    """
    ts, cached = _load_update_cache(time.time())
    if cached:
        with _UPDATE_LOCK:
            if not _UPDATE_STATE.get("latest"):
                # v1.14.14: 键名原写成 from_primary, 与其余处的 from_source
                # (primary/gh-proxy-api/gh-proxy-raw/jsdelivr) 不一致 ——
                # 四源全失败时状态里根本没有 from_source, debug 打印靠
                # {None: "本地缓存"} 巧合兜对。统一键名, 缓存来源如实标为本地缓存。
                _UPDATE_STATE.update(latest=cached, checked_at=ts,
                                     from_source="cache",
                                     is_new=_version_newer(cached, APP_VERSION))


def _update_notice_line():
    """有新版本时返回提示行 (gh-proxy 加速下载链接); 无/未检查 None。"""
    with _UPDATE_LOCK:
        if not _UPDATE_STATE.get("is_new") or not _UPDATE_STATE.get("latest"):
            return None
        latest = _UPDATE_STATE["latest"]
    url = (f"{UPDATE_DL_PROXY}https://github.com/{GH_REPO}/releases/"
           f"download/v{latest}/NetPulse.exe")
    return (f"⬆ 有新版本 v{latest} (当前 v{APP_VERSION}), 下载: {url}")


