def render_report_html_brief(report):
    """渲染一页客户报告 (A4 单页, 现场检测模式出口, v1.13.0)。

    只消费 build_report() 的 report dict (与完整版同源, 数字必然一致),
    不读 LAST_RUN (收口规则)。版式见 reports/onepage_customer_report_design.html。
    单页高度靠截断锁死 (见 _BRIEF_CLIP 注释), 内容超出按规则降级:
      问题卡最多 3 张 / 机房待整改行最多 4 条 / 文本按 _BRIEF_CLIP 截断。
    """
    if not report:
        return "<p>尚无诊断数据，请先运行诊断</p>"

    g = (report["generated_at"].strftime("%Y-%m-%d %H:%M")
         if hasattr(report["generated_at"], "strftime") else str(report["generated_at"] or ""))
    health = report.get("health") or {}
    counts = report.get("counts") or {}
    modules = report.get("modules") or []
    by_key = {m.get("key"): m for m in modules}
    mm = report.get("meta_manual") or {}
    sc = report.get("site_check") or {}
    site_note = report.get("site_note") or ""
    rcs = (report.get("diagnosis") or {}).get("root_causes") or []
    all_counts = {}
    for st in (report.get("summary") or {}).values():
        all_counts[st] = all_counts.get(st, 0) + 1
    exempt_count = report.get("exempt_count", 0) or 0

    def _raw(key):
        return (by_key.get(key) or {}).get("raw") or {}

    # ── 手输元信息 (全部过 _brief_clip; 客户名绝不进属性) ──
    customer = _brief_clip(mm.get("customer") or "客户",
                           _BRIEF_CLIP["customer"])
    tested_at = _brief_clip(mm.get("tested_at") or g, 20)
    plan_mbps = None
    m_plan = re.search(r"(\d+(?:\.\d+)?)\s*M(?:BPS)?", str(mm.get("plan") or ""),
                       re.IGNORECASE)
    if m_plan:
        plan_mbps = float(m_plan.group(1))

    # ── 关键实测 4 格 ──
    speed, _spd_label = _resolve_speed_chart_src(_raw("speedtest"))
    dl, ul = speed.get("download_mbps"), speed.get("upload_mbps")

    def _fmt_mbps(v):
        try:
            v = float(v)
        except (TypeError, ValueError):
            return None
        return f"{v:.0f}" if v >= 100 else f"{v:.1f}"

    ping = _raw("gateway").get("ping") or {}
    rtts = ping.get("rtts") or []
    g_avg = ping.get("avg_ms")
    g_peak = max(rtts) if rtts else None
    g_loss = ping.get("loss_pct")
    wifi = _raw("wifi")
    w_ch, w_n = wifi.get("current_channel"), wifi.get("network_count")
    w_inter = wifi.get("overall_interference") or "正常"

    def _met(cls, lab, val_html, note):
        return (f'<div class="bmet {cls}"><div class="lab">{lab}</div>'
                f'<div class="val">{val_html}</div>'
                f'<div class="note">{note}</div></div>')

    metrics = []
    if _fmt_mbps(dl):
        metrics.append(_met(
            "good", "⬇ 宽带实测速率",
            f'{_fmt_mbps(dl)}<small>Mbps</small>',
            f'上传 {_fmt_mbps(ul)} Mbps' if _fmt_mbps(ul) else "来源 " + _html_esc(_spd_label)))
    if plan_mbps and _fmt_mbps(dl):
        try:
            pct = float(dl) / plan_mbps * 100.0
        except ZeroDivisionError:
            pct = 0.0
        ok = pct >= 90.0
        metrics.append(_met(
            "pact" + ("" if ok else " bad"), "🎯 签约带宽达标",
            f'{pct:.1f}<small>%</small>',
            f'签约 {plan_mbps:g}M · {"达标" if ok else "未达标"}'))
    if isinstance(g_avg, (int, float)):
        # Windows ping 对局域网 (<1ms) 输出整数粒度 0, 直写 "0ms" 会被误读
        # (与完整版 v1.9.3 同一口径): 0 或 <1 一律表达为 "<1"
        def _ms(v):
            return "<1" if v < 1 else f"{v:g}"
        note_bits = []
        if isinstance(g_peak, (int, float)):
            note_bits.append(f"峰值 {_ms(g_peak)} ms")
        if isinstance(g_loss, (int, float)) and g_loss > 0:
            note_bits.append(f"丢包 {g_loss:g}%")
        metrics.append(_met(
            "mid" if (g_peak or 0) > 30 else "", "⏱ 网关延迟",
            f'{_ms(g_avg)}<small>ms</small>',
            " · ".join(note_bits) or "局域网 <1ms 视为正常"))
    if w_ch or w_n:
        cls = "bad" if ("严重" in w_inter or (isinstance(w_n, int) and w_n >= 15)) else "mid"
        note = (f"邻居 {w_n} 个 · {w_inter}" if w_n else _html_esc(w_inter))
        metrics.append(_met(cls, "📶 无线环境",
                            f'{_html_esc(str(w_ch)) if w_ch else "—"}<small>信道</small>',
                            note))
    if not metrics:
        metrics.append(_met("", "关键指标", "—", "本次无可用测速数据"))

    # ── 结论区文案 (数据驱动, 与完整版 health 同源) ──
    score = health.get("score", 0)
    grade_key = str(health.get("grade") or "").strip()[:1].upper()
    lbl_fg, lbl_bg = GRADE_BADGE.get(grade_key, GRADE_BADGE["C"])
    n_site_bad = sum(1 for it in SITE_CHECK_ITEMS if sc.get(it["key"]) in it["bad"])

    # 模块级问题收集 (与完整版待办同源: 异常/错误/警告, severity+text 去重)。
    # v1.13.1: 此前问题区只看 root_causes, 评分豁免模块 (ipv6/proxy 等) 的
    # 异常/警告不触发根因规则 → 前文"未发现故障"、检测覆盖却有红黄徽章,
    # 自相矛盾 (真实现场首跑暴露)。回退: 无根因时逐条列出模块级问题。
    todo = []
    _seen = {}
    for m in modules:
        for iss in m.get("issues") or []:
            sev = iss.get("severity", "信息")
            text = (iss.get("text") or "").strip()
            if sev not in ("异常", "错误", "警告") or not text:
                continue
            k = (sev, text)
            nm = m.get("name", "")
            hit = _seen.get(k)
            if hit is not None:
                # 同一文案在多个模块出现 (如 23 个模块全超时) → 记下波及模块,
                # 否则标题的「1 项」会被读成「只有 1 个模块有问题」
                # (v1.15.0 审查 P1-15)
                if nm and nm not in hit["_mods"]:
                    hit["_mods"].append(nm)
                continue
            entry = {"severity": sev, "text": text, "module": nm,
                     "_mods": [nm] if nm else []}
            _seen[k] = entry
            todo.append(entry)
    todo.sort(key=lambda i: 0 if i["severity"] in ("异常", "错误") else 1)
    # 波及模块数 (去重后): 标题要说明这几项问题一共涉及几个模块
    _inv = []
    for i in todo:
        for nm in i.get("_mods") or []:
            if nm and nm not in _inv:
                _inv.append(nm)
    todo_scope = (f"（涉及 {len(_inv)} 个模块）"
                  if len(_inv) > len(todo) else "")

    verdict_txt = str(health.get("verdict") or "").strip()
    if rcs:
        vline = (f'实测发现 <span class="em">{len(rcs)} 个主要问题</span>'
                 f'（{_html_esc(health.get("label", ""))}）')
        vsub = _brief_clip(rcs[0].get("description") or rcs[0].get("title", ""),
                           _BRIEF_CLIP["desc"])
    elif todo:
        vline = _html_esc(verdict_txt) or '实测存在需关注模块'
        vsub = "模块级问题逐条列出如下；评分口径说明见「检测覆盖」。"
    else:
        vline = '实测<span class="em">未发现明确故障</span>'
        vsub = "各项核心检测均通过，详细指标见随附完整报告。"
    if n_site_bad:
        vline += f'，机房环境另有 <span class="em">{n_site_bad} 项待整改</span>'

    sysinfo = report.get("system") or {}
    chips = []
    for lab, val in (("本机", sysinfo.get("local_ip")),
                     ("网关", sysinfo.get("gateway")),
                     ("公网", sysinfo.get("public_ip")),
                     ("DNS", sysinfo.get("dns"))):
        if val:
            chips.append(f"<span>{_html_esc(lab)} <b>{_html_esc(str(val))}</b></span>")

    # ── 一、网络实测问题 (severity 降序, 最多 3 张) ──
    sev_rank = {"critical": 0, "high": 1, "medium": 2, "low": 3}
    sev_label = {"critical": "严重", "high": "高", "medium": "中", "low": "低"}
    rcs_sorted = sorted(rcs, key=lambda r: sev_rank.get(r.get("severity", "low"), 3))
    shown, hidden = rcs_sorted[:3], rcs_sorted[3:]
    rc_blocks = []
    for rc in shown:
        sev = rc.get("severity", "low")
        cls = "crit" if sev == "critical" else "high" if sev == "high" else "med"
        recs = rc.get("recommendations") or []
        conf_band = _conf_band(rc.get("confidence", 0))
        rc_blocks.append(
            f'<div class="brc {cls}"><div class="h">'
            f'<span class="badge">{_html_esc(sev_label.get(sev, sev))}</span>'
            f'<span class="t">{_html_esc(_brief_clip(rc.get("title", ""), _BRIEF_CLIP["title"]))}</span>'
            f'<span class="cf">置信度 {_html_esc(conf_band)}</span></div>'
            f'<div class="d">{_html_esc(_brief_clip(rc.get("description", ""), _BRIEF_CLIP["desc"]))}</div>'
            f'<div class="a">💡 <b>建议：</b>'
            f'{_html_esc(_brief_clip(recs[0] if recs else "详见完整报告", _BRIEF_CLIP["advice"]))}</div></div>')
    extra_cnt = (counts.get("警告", 0) + counts.get("超时", 0)
                 + counts.get("未检测", 0) + len(hidden))
    more_html = ""
    if extra_cnt > 0:
        more_html = (f'<div class="bmore">另有 {extra_cnt} 项提示级 / 未完成检测信息，'
                     f'详见随附完整报告。</div>')
    if rcs:
        sec_head = ('<div class="bsec">一、网络实测问题 '
                    f'<span class="cnt">{len(rcs)} 项</span>'
                    '<span class="rd">由 NetPulse 自动检测判定</span></div>')
        problems_html = sec_head + "".join(rc_blocks) + more_html
    elif todo:
        # v1.13.1: 无根因回退 — 模块级 issue 行 (最多 4 条, 溢出折叠)
        shown_t, hidden_t = todo[:4], todo[4:]

        def _brief_src(i):
            """来源列: 同一文案涉及多个模块时标明总数, 别只报第一个模块 ——
            只写「链路速率」会被读成"链路速率有问题", 实际是 23 个模块全超时
            (v1.15.0 审查 P1-15)。"""
            mods = i.get("_mods") or []
            base = _brief_clip(i.get("module", ""), 12)
            if len(mods) > 1:
                return f"{base} 等 {len(mods)} 个模块"
            return base

        rows = "".join(
            f'<div class="irow"><span class="sev">{_html_esc(i["severity"])}</span>'
            f'<span class="tx">{_html_esc(_brief_clip(i["text"], _BRIEF_CLIP["desc"]))}</span>'
            f'<span class="src">{_html_esc(_brief_src(i))}</span></div>'
            for i in shown_t)
        if hidden_t:
            rows += (f'<div class="irow"><span class="sev">…</span>'
                     f'<span class="tx">另有 {len(hidden_t)} 项，详见随附完整报告</span>'
                     f'<span class="src"></span></div>')
        sec_head = ('<div class="bsec">一、网络实测问题 '
                    f'<span class="cnt">{len(todo)} 项{todo_scope}</span>'
                    '<span class="rd">由 NetPulse 自动检测判定</span></div>')
        problems_html = (sec_head
                         + f'<div class="bissues">{rows}</div>')
    else:
        clean_more = more_html.replace('class="bmore"', 'class="bmore" style="margin-top:6px"')
        problems_html = ('<div class="bsec">一、网络实测问题 '
                         '<span class="cnt">0 项</span></div>'
                         '<div class="bclean">✓ 本次实测未发现明确故障，网络状态良好。</div>'
                         + clean_more)

    # ── 二、机房环境检查 (只列待整改, 正常项折一行) ──
    n_checked = sum(1 for it in SITE_CHECK_ITEMS if sc.get(it["key"]))
    if not sc:
        site_html = ('<div class="bsec">二、机房环境检查</div>'
                     '<div class="bsite"><div class="skip">本次未进行机房环境检查'
                     '（现场模式跳过或未逐项确认）。</div></div>')
    else:
        cat_stats = {}
        for it in SITE_CHECK_ITEMS:
            v = sc.get(it["key"])
            if not v:
                continue
            tot, bad = cat_stats.get(it["cat"], (0, 0))
            cat_stats[it["cat"]] = (tot + 1,
                                    bad + (1 if v in it["bad"] else 0))
        cat_order = []
        for it in SITE_CHECK_ITEMS:
            if it["cat"] not in cat_order and it["cat"] in cat_stats:
                cat_order.append(it["cat"])
        chips_html = "".join(
            (f'<span class="cat bad">{_html_esc(c)} <b>{cat_stats[c][1]}/{cat_stats[c][0]}</b></span>'
             if cat_stats[c][1] else
             f'<span class="cat">{_html_esc(c)} <b>{cat_stats[c][0]}/{cat_stats[c][0]}</b> ✓</span>')
            for c in cat_order)
        bad_rows, ok_labels = [], []
        for it in SITE_CHECK_ITEMS:
            v = sc.get(it["key"])
            if not v:
                continue
            if v in it["bad"]:
                bad_rows.append(
                    f'<div class="row"><span class="kn">{_html_esc(it["label"])}</span>'
                    f'<span class="st">⚠ {_html_esc(v)}</span>'
                    f'<span class="ad"><b>建议：</b>{_html_esc(it["advice"])}</span></div>')
            else:
                ok_labels.append(_html_esc(it["label"]))
        shown_rows, hidden_rows = bad_rows[:4], bad_rows[4:]
        ok_line = ""
        if ok_labels or hidden_rows:
            bits = []
            if ok_labels:
                bits.append(f'<b>其余 {len(ok_labels)} 项检查正常：</b>'
                            + " · ".join(ok_labels))
            if hidden_rows:
                bits.append(f'另有 {len(hidden_rows)} 项待整改详见完整报告')
            ok_line = f'<div class="okline">{"".join(bits)}</div>'
        note_html = (f'<div class="noterow"><b>📝 现场备注（装维手输）：</b>'
                     f'{_html_esc(_brief_clip(site_note, 90))}</div>'
                     if site_note else "")
        sec_head = ('<div class="bsec">二、机房环境检查 '
                    f'<span class="cnt">{n_checked} 项 · {n_site_bad} 项待整改</span>'
                    '<span class="rd">由装维终端逐项确认</span></div>')
        if not bad_rows:
            body = ('<div class="bclean" style="margin-top:2px">'
                    f'✓ 机房环境 {n_checked} 项检查全部正常。</div>')
        else:
            body = (f'<div class="cats">{chips_html}</div>'
                    + "".join(shown_rows) + ok_line)
        site_html = sec_head + f'<div class="bsite">{body}{note_html}</div>'

    # ── 检测覆盖 ──
    status_bar = _svg_status_bar(all_counts)
    # v1.14.9: 豁免说明改为按实跑集合动态生成 — 旧文案三处数字互相打架
    # (真实现场报告反馈): 硬编码 4 个模块名 vs "共 3 项豁免" (现场 iperf3
    # 不跑) vs "其中 2 项属豁免" (只数非完成态)。现在实检/计分/豁免三个数
    # 同源 (summary), 名单随实跑变, 数字必然自洽。
    _exm = _exempt_names(report)
    cap = (f'健康分 {score} 分：实检 {sum(all_counts.values())} 项，'
           f'{sum(counts.values())} 项参与计分')
    if _exm:
        cap += (f'，{len(_exm)} 项评分豁免（{_html_esc("、".join(_exm))}；'
                f'可选/环境类检查，不扣分）')
    cap += '。'
    # v1.13.1: 豁免模块的非完成状态照常显示徽章但不扣分 — 必须点破,
    # 否则"检测覆盖有红黄徽章 + 健康分满分"看起来像算错 (真实现场首跑反馈)
    exempt_bad = sorted(
        MODULE_MAP.get(k, (k, k))[0]
        for k, st in (report.get("summary") or {}).items()
        if st not in ("完成", "未检测") and k in SCORE_EXEMPT_MODULES)
    if exempt_bad:
        cap += (f'其中 {_html_esc("、".join(exempt_bad))} '
                f'本次有异常/警告显示，按豁免规则不计分。')
    cap += '整改项建议下次上门免费复核。'
    lg_bits = "".join(
        f'<span><i style="background:{_html_status_color(st)}"></i>{_html_esc(st)} '
        f'{all_counts.get(st, 0)}</span>'
        for st in STATUS_BAR_ORDER if all_counts.get(st))
    cov_html = (f'<div class="bcov"><div class="row">'
                f'<span class="k">检测覆盖</span>'
                # v1.14.3: 用与右侧徽章/状态条同源的实际计数 (summary 口径)。
                # 旧版用 total_modules (全量 23 宇宙口径): 现场模式剔除
                # tcpcc/port/iperf3 后实跑 20 项, 右侧 18+1+1=20 对不上 23
                f'<span>网络自动检测 {sum(all_counts.values()) or len(modules)} 项'
                f' · 机房现场检查 {n_checked} 项</span>'
                f'<span class="lg">{lg_bits}</span></div>'
                f'<div class="bar">{status_bar}</div>'
                f'<div class="cap">{_html_esc(cap)}</div></div>')

    return f"""<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<title>{_html_esc(customer)} 网络检测报告</title>
<style>{_BRIEF_CSS}</style>
</head>
<body>
<div class="bsheet">

  <div class="bhead">
   <div class="btop">
    <!-- 官方 logo: China_Telecom-Logo.wine.png 反白内嵌 (形状官方原样) -->
    <div class="ct-logo" style="flex:none;display:flex;align-items:center"><img src="data:image/png;base64,{_CT_LOGO_BRIEF_B64}" alt="中国电信 CHINA TELECOM"></div>
      <span class="bsub">现场实测 · 网络质量 + 机房环境 双项检查</span>
   </div>
    <div class="bmain">
      <div class="bttl"><span class="bcname">{_html_esc(customer)}</span> 网络检测报告</div>
    </div>
  </div>

  <div class="bverdict">
    <div class="bring">
      {_svg_health_ring(score, grade_key)}
      <div class="in"><div class="num">{score}</div>
        <div class="gd" style="color:{lbl_fg};background:{lbl_bg}">{_html_esc(health.get("label", ""))}</div></div>
    </div>
    <div class="bvtext">
      <div class="bvline">{vline}</div>
      <div class="bvsub">{_html_esc(vsub)}</div>
      <div class="bchips">{"".join(chips)}</div>
    </div>
  </div>

  <div class="bmetrics">{"".join(metrics)}</div>

  {problems_html}

  {site_html}

  {cov_html}

  <div class="bgap"></div>
  <div class="bfoot">
    <div class="bslogan">中国电信<span class="dot">·</span>用心服务每一次上门</div>
    <div class="bfine">检测时间 {_html_esc(tested_at)} · 数据为本次实测结果，完整原始数据另附 · 第 1 / 1 页</div>
  </div>

</div>
</body>
</html>
"""
# ══════════════════════════════════════════════════════════════════════════
# 模板D 极简报款 (v2, 与 design_ref 同源) — A4 2 页, 选项 6 现场检测模式专用 (本地工作区)
# ══════════════════════════════════════════════════════════════════════════
# 设计稿: design_ref/report_templates/模板D_现代仪表盘风.html
# - 报头藏蓝实色 + 电信 logo (复用现网 _CT_LOGO_BRIEF_B64)
# - 评分主区 (donut + verdict + 签约) / KPI 4 列 / 主要发现
# - 机房 6 项 grid (待整改独立红框) / 现场备注
# - 续报头 + 检测明细 20 行全表 + 页脚
# 收口: 与现网 brief 一样从 build_report() 输出读取 (不读 LAST_RUN)。
# 安全: 文本节点 _html_esc (quote=False), 属性一律 _html_attr (quote=True, v1.5.0 P0)。
# 现场模式不走 _PRESENT_.. 文案抽离 (现场仅选项 6 用, 第三方不需要抽)。

def render_report_html_brief_v2(report):
    """模板D 极简报款 渲染 (A4 2 页, 选项 6 现场检测模式出口)。

    不修改现网 render_report_html_brief; 通过 export_report(layout='brief_v2') 接入。
    """
    if not report:
        return "<p>尚无诊断数据，请先运行诊断</p>"

    g = (report["generated_at"].strftime("%Y-%m-%d %H:%M")
         if hasattr(report["generated_at"], "strftime") else str(report["generated_at"] or ""))
    health = report.get("health") or {}
    counts = report.get("counts") or {}
    modules = report.get("modules") or []
    by_key = {m.get("key"): m for m in modules}
    mm = report.get("meta_manual") or {}
    sc = report.get("site_check") or {}
    site_note = report.get("site_note") or ""
    rcs = (report.get("diagnosis") or {}).get("root_causes") or []
    all_counts = {}
    for st in (report.get("summary") or {}).values():
        all_counts[st] = all_counts.get(st, 0) + 1
    score = health.get("score") or 0
    grade = health.get("grade") or "—"
    label = health.get("label") or "—"
    exempt_count = report.get("exempt_count", 0) or 0

    def _raw(key):
        return (by_key.get(key) or {}).get("raw") or {}

    customer = _brief_clip(mm.get("customer") or "客户", _BRIEF_CLIP["customer"])
    tested_at = _brief_clip(mm.get("tested_at") or g, 20)
    plan_str = str(mm.get("plan") or "").strip()
    m_plan = re.search(r"(\d+(?:\.\d+)?)\s*M(?:BPS)?", plan_str, re.IGNORECASE)
    plan_mbps = float(m_plan.group(1)) if m_plan else None
    total_mods = sum(all_counts.values()) or len(by_key)
    scored_mods = sum(counts.values())
    n_checked = len(sc)
    n_site_bad = sum(1 for k, v in sc.items()
                     if v in SITE_CHECK_BY_KEY.get(k, {}).get("bad", []))

    speed_raw = _raw("speedtest")
    spd_download = speed_raw.get("download_mbps")
    spd_upload = speed_raw.get("upload_mbps")
    spd_method = speed_raw.get("method", "—")
    ping = _raw("gateway").get("ping") or {}
    g_avg = ping.get("avg_ms")
    g_loss = ping.get("loss_pct")
    tcpstats_raw = _raw("tcpstats")
    retrans_rate = tcpstats_raw.get("retrans_rate_pct") or tcpstats_raw.get("retransmits_pct")

    def _fmt_mbps(v):
        try: v = float(v)
        except (TypeError, ValueError): return None
        return f"{v:.0f}" if v >= 100 else f"{v:.1f}"

    def _fmt_pct(v):
        try: return f"{float(v):.1f}"
        except (TypeError, ValueError): return None

    # Windows ping 对局域网 (<1ms) 输出整数粒度 0, 直写 "0ms" 会被误读
    # (与 brief v1 / 完整版 v1.9.3 同一口径): 0 或 <1 一律表达为 "<1"
    def _ms(v):
        try: v = float(v)
        except (TypeError, ValueError): return None
        return "<1" if v < 1 else f"{v:g}"

    # v1.15.0 (审查 P1-9): 网关延迟档位按**实测值**分档, 不再硬编码。
    # 原写法无论实测多少都写「优秀(<10ms)」—— 真实产物里同一格是
    # 「0.0 ms / 优秀(<10ms) · 丢包 5.0%」, 自相矛盾, 客户一眼看穿不可信。
    # 档位阈值取 THRESHOLDS["gateway"]["ping.avg_ms"] (warn 10 / err 30),
    # 与完整版报告「判定标准」表同源 (不另立阈值)。
    _gw_th = THRESHOLDS["gateway"]["ping.avg_ms"]
    _gw_warn, _gw_err = _gw_th["warn"], _gw_th["err"]
    if not isinstance(g_avg, (int, float)):
        gw_band = "未测"
    elif g_avg < _gw_warn:
        gw_band = f"优秀(<{_gw_warn}ms)"
    elif g_avg < _gw_err:
        gw_band = f"一般({_gw_warn}-{_gw_err}ms)"
    else:
        gw_band = f"偏高(≥{_gw_err}ms)"
    gw_lat_val = _ms(g_avg)
    gw_lat_delta = _html_esc(gw_band)
    if isinstance(g_loss, (int, float)) and g_loss > 0:
        gw_lat_delta += f" · 丢包 {_html_esc(_fmt_pct(g_loss))}%"

    dl = _fmt_mbps(spd_download)
    ul = _fmt_mbps(spd_upload)
    plan_ok = (plan_mbps and spd_download and spd_download / plan_mbps >= 0.9)
    plan_ratio = (spd_download / plan_mbps * 100) if (plan_mbps and spd_download) else None

    _exm = _exempt_names(report)
    exempt_bad = sorted(
        MODULE_MAP.get(k, (k, k))[0]
        for k, st in (report.get("summary") or {}).items()
        if st not in ("完成", "未检测") and k in SCORE_EXEMPT_MODULES)

    cap = (f'健康分 {score} 分: 实检 {total_mods} 项, {scored_mods} 项参与计分')
    if _exm:
        cap += (f', {len(_exm)} 项评分豁免 ({_html_esc("、".join(_exm))}; '
                f'可选/环境类检查, 不扣分)')
    cap += '。'
    if exempt_bad:
        cap += (f'其中 {_html_esc("、".join(exempt_bad))} '
                f'本次有异常/警告显示, 按豁免规则不计分。')

    # v1.15.2 (审查 P1-15c): 无根因时「主要发现」区不得空着 ——
    # 23 个模块全超时时根因列表为空, 该区只留一个空标题, 与「健康分 0 分 F 级」
    # 直接打架 (完整版早有「⚠ 未定位到根因」, 旧 brief v1 早有模块级问题回退,
    # 只有 brief_v2 缺)。口径与完整版/brief v1 对齐:
    #   ① 有根因           → 列根因 (维持现状)
    #   ② 无根因但有模块级问题 → 逐条列问题 (最多 2 条 + 1 行溢出提示, A4 高度预算)
    #   ③ 两者皆无但有未完成模块 → 「未定位到根因」提示
    #   ④ 全都没有         → 「未发现明确故障」
    _todo = []
    _seen = {}
    for m in modules:
        for iss in m.get("issues") or []:
            sev = iss.get("severity", "信息")
            text = (iss.get("text") or "").strip()
            if sev not in ("异常", "错误", "警告") or not text:
                continue
            k = (sev, text)
            nm = m.get("name", "")
            hit = _seen.get(k)
            if hit is not None:
                # 同一文案在多个模块出现 (如 23 个模块全超时) → 记下波及模块,
                # 否则会被读成「只有 1 个模块有问题」 (v1.15.0 审查 P1-15)
                if nm and nm not in hit["_mods"]:
                    hit["_mods"].append(nm)
                continue
            entry = {"severity": sev, "text": text, "module": nm,
                     "_mods": [nm] if nm else []}
            _seen[k] = entry
            _todo.append(entry)
    _todo.sort(key=lambda i: 0 if i["severity"] in ("异常", "错误") else 1)
    _inv = []
    for i in _todo:
        for nm in i.get("_mods") or []:
            if nm and nm not in _inv:
                _inv.append(nm)
    _todo_scope = (f"（涉及 {len(_inv)} 个模块）"
                   if len(_inv) > len(_todo) else "")
    # 未完成检测的模块数 (与完整版「⚠ 未定位到根因」同口径: summary 全量状态)
    _unfinished = sum(1 for st in (report.get("summary") or {}).values()
                       if st in ("超时", "错误"))

    findings = []
    _fallback = False
    if rcs:
        for rc in rcs[:4]:
            title = _brief_clip(rc.get("title", ""), _BRIEF_CLIP["title"])
            sev = (rc.get("severity") or "low").lower()
            desc = _brief_clip(rc.get("description", ""), _BRIEF_CLIP["desc"])
            # v1.15.0 (审查 P0-3): 建议键是 recommendations (列表), 见 _first_rootcause_advice
            act = _brief_clip(_first_rootcause_advice(rc), _BRIEF_CLIP["advice"])
            findings.append({"sev": sev, "title": title, "desc": desc, "act": act})
    elif _todo:
        for i in _todo[:2]:
            mods = i.get("_mods") or []
            src = i.get("module", "") or ""
            if len(mods) > 1:
                src = f"{src} 等 {len(mods)} 个模块"
            findings.append({
                "sev": "high" if i["severity"] in ("异常", "错误") else "medium",
                "title": _brief_clip(i["text"], _BRIEF_CLIP["title"]),
                "desc": _brief_clip(f"来源: {src}{_todo_scope}",
                                    _BRIEF_CLIP["desc"]),
                "act": "详见随附完整报告的待办清单",
            })
        if len(_todo) > 2:
            findings.append({
                "sev": "low",
                "title": f"另有 {len(_todo) - 2} 项模块级问题",
                "desc": "详见随附完整报告",
                "act": "",
            })
        _fallback = True
    elif _unfinished:
        findings.append({
            "sev": "medium",
            "title": "未定位到根因",
            "desc": _brief_clip(
                f"{_unfinished} 个模块未完成检测, 现有结论仅供参考。",
                _BRIEF_CLIP["desc"]),
            "act": "请先让未完成模块跑完再判断",
        })
        _fallback = True
    else:
        findings.append({
            "sev": "low",
            "title": "未发现明确故障",
            "desc": "本次实测未发现明确故障, 网络状态良好。",
            "act": "",
        })
    # 豁免卡: 根因存在时或真健康时照常显示; 有回退卡时**让位** ——
    # 否则 23 模块全超时时, 客户在「主要发现」区唯一看到的是
    # 「豁免项显示异常(不计分)」, 极易被读成「本次只发现豁免项有问题」。
    if _exm and exempt_bad and not _fallback:
        findings.append({
            "sev": "exempt",
            "title": _brief_clip("豁免项显示异常(不计分)", _BRIEF_CLIP["title"]),
            "desc": "评分豁免项: 可选/环境类检查, 本次有状态显示但按规则不扣分。",
            "act": "",
        })

    site_rows = []
    bad_row = None
    for it in SITE_CHECK_ITEMS:
        key = it["key"]; sel = sc.get(key); nm = it["label"]
        if not sel: status, klass = "未检查", "muted"
        elif sel in it["bad"]: status, klass = "待整改", "bad"
        else: status, klass = "正常", "ok"
        if klass == "bad":
            bad_row = {"key": key, "nm": nm, "sel": sel,
                       "issue": sel, "advice": it["advice"]}
        else:
            site_rows.append({"nm": nm, "status": status, "klass": klass})

    stat_color = {"异常": "high", "错误": "high", "警告": "mid",
                  "完成": "ok", "未检测": "na"}
    detail_rows = []
    for m in modules:
        key = m.get("key"); st = m.get("status", "未检测")
        detail_rows.append({
            "nm": m.get("name", key),
            "verdict": m.get("verdict", "") or "—",
            "metric": _fmt_kpi_for_detail(key, _raw(key)),
            "stat": st,
            "stat_class": stat_color.get(st, "ok"),
        })

    # v1.15.0 (审查 P0-4): `Severity` 枚举值是 info/low/medium/high/critical,
    # 此前只认 high/mid/exempt —— **critical 根因** (网关丢包>=20% / WAN 中断 /
    # F 级 bufferbloat) 落到默认值 → 空徽章 + low 样式, 即"最严重的根因在交
    # 客户的一页版里看起来最不严重"。改为按 Severity 全量映射:
    #   critical 复用 high 的红色样式 (不新增 CSS 规则, 不影响 A4 高度锁)
    #   low/info 用 mute 灰底 (配 .f.low .badge 规则), 不再出现透明空徽章
    _SEV_PILL = {
        "critical": ("严重", "high"),
        "high":     ("异常", "high"),
        "medium":   ("警告", "mid"),
        "low":      ("提示", "low"),
        "info":     ("提示", "low"),
        "exempt":   ("豁免", "exempt"),
    }

    def sev_class(s): return _SEV_PILL.get(s, ("提示", "low"))[1]
    def sev_pill(s): return _SEV_PILL.get(s, ("提示", "low"))

    # v1.18.3: 网口摘要 (端口定位) —— 一页版只给一行, 不占版面 (A4 双页有硬锁):
    # 哪个口承载默认路由 + 几口速率档位偏低 + 几个虚拟网卡。
    # 完整对照表在完整版报告的「网口对照」章节。
    portline_html = ""
    _pm = report.get("port_map") or []
    if _pm:
        _eg = next((r for r in _pm if r.get("role") == "出口口"), None)
        # 只统计**已连接物理口** (有线 + WiFi) 的档位: 未连接口没有速率可判,
        # 虚拟口档位是 n/a 也不参与。漏掉前者的后果是"物理口一根没插, 摘要
        # 却说各口速率正常" —— 交到客户手上的假绿。
        _bad = [r for r in _pm if r.get("level") in ("warn", "err")]
        _phys_up = [r for r in _pm if r.get("kind") in ("有线", "WiFi")
                    and r.get("status") in ("Up", "已启用")]
        # 口数一律按**对照表的列**统计, 摘要里的数字与表里的行数不会打架:
        # 「N 口未连接」= 表里状态列为「未连接」的行数 (已禁用不算未连接);
        # 「N 个虚拟网卡」= 表里类型列为「虚拟」的行数。
        # 用角色列统计会漏掉两处: 未连接但承载默认路由的那块口 (角色是「出口口」),
        # 以及未连接的虚拟网卡 (角色是「未插口」)。
        _ndown = sum(1 for r in _pm
                     if r.get("status") not in ("Up", "已启用", "Disabled"))
        _nvirt = sum(1 for r in _pm if r.get("kind") == "虚拟")
        _bits = []
        if _eg:
            _egname = _html_esc(_short_iface(str(_eg.get("name") or ""), 24))
            if _eg.get("kind") == "虚拟":
                # 隧道/桥接速率不代表物理链路 —— 摘要里不报这个数, 否则装维
                # 会把「10000 Mbps」当成物理链路带宽 (对照表里有完整说明)
                _egtxt = _egname
            elif _eg.get("status") in ("Up", "已启用"):
                # 速率文本与完整版对照表共用 _fmt_port_speed (两处精度必须一致)
                _egsp = _fmt_port_speed(_eg.get("speed_mbps"))
                _egtxt = f"{_egname} · {_egsp}" if _egsp != "—" else _egname
            else:
                _egtxt = f"{_egname} (未连接)"
            _bits.append(f"出口口 {_egtxt}")
        else:
            _bits.append("出口口未判定")
        if _bad:
            _bits.append(f"{len(_bad)} 口速率档位偏低")
        elif _phys_up:
            _bits.append("已连接网口速率正常")
        else:
            _bits.append("无在线物理口")
        if _ndown:
            _bits.append(f"{_ndown} 口未连接")
        if _nvirt:
            _bits.append(f"{_nvirt} 个虚拟网卡")
        portline_html = (f'<div class="portline"><span class="k">网口</span>'
                         f'{" · ".join(_bits)}</div>')

    # v1.19.0: 环回测速摘要行 —— 接入侧 (终端→网关) 与使用侧 (走公网) 一句话对照。
    # 与完整版「环回测速」章节同口径同精度 (都走 %.1f Mbps), 只占一行不占版面。
    loopline_html = ""
    _lb = _raw("loopback")
    if _lb:
        if "error" in _lb:
            loopline_html = ('<div class="loopline"><span class="k">环回</span>'
                             '未检测 · 本次未能测出终端→网关这一段的速率</div>')
        else:
            try:
                _lbm = float(_lb.get("mbps") or 0)
            except (TypeError, ValueError):
                _lbm = 0.0
            _lbbits = [f"终端→网关 {_lbm:.1f} Mbps"]
            _spd_dl = None
            try:
                _spd_src, _ = _resolve_speed_chart_src(_raw("speedtest"))
                if _spd_src.get("download_mbps") is not None:
                    _spd_dl = float(_spd_src.get("download_mbps"))
            except (TypeError, ValueError):
                _spd_dl = None
            if _spd_dl:
                # 接入侧数字不可判读时不做大小对照 (无线 / 没跑满 / 撞工具上限的
                # 数字是参考值或下限, 拿来比大小会得出反向结论)
                _lb_judgeable = (bool(_lb.get("saturated"))
                                 and not _lb.get("is_wireless")
                                 and not _lb.get("load_limited")
                                 and not _lb.get("at_ceiling"))
                if _lb_judgeable and _lbm >= _spd_dl * 1.5:
                    _lbbits.append(f"接入侧高于使用侧 {_spd_dl:.1f} Mbps")
                else:
                    _lbbits.append(f"使用侧 {_spd_dl:.1f} Mbps")
            if _lb.get("scope") != "access":
                _lbbits.append("测的是终端→默认网关这一段")
            # 数字不可判读时必须在一页版就说明: 否则客户只看到「环回 0.8 Mbps」,
            # 会以为线路坏了 (完整版里才有注解就晚了)。与完整版章节同口径。
            if _lb.get("is_wireless"):
                _lbbits.append("无线接入仅供参考")
            elif _lb.get("load_limited") or _lb.get("at_ceiling"):
                _lbbits.append("已达本工具测量上限")
            loopline_html = ('<div class="loopline"><span class="k">环回</span>'
                             f'{" · ".join(_lbbits)}</div>')

    findings_html = ""
    for i, f in enumerate(findings, 1):
        sev = sev_class(f["sev"])
        pill_text, pill_class = sev_pill(f["sev"])
        title = _html_esc(f["title"])
        desc = _html_esc(f["desc"])
        act_html = ""
        if f["act"]:
            act_html = (f'<div class="act"><span class="lbl">整改建议</span>  '
                        f'{_html_esc(f["act"])}</div>')
        findings_html += (
            f'<div class="f {sev}"><div class="num">{i:02d}</div><div>'
            f'<div class="row"><span class="ttl">{title}</span>'
            f'<span class="badge {pill_class}">{_html_esc(pill_text)}</span></div>'
            f'<div class="obs">{desc}</div>{act_html}</div></div>')

    site_grid_html = ""
    for r in site_rows:
        site_grid_html += (
            f'<div class="it"><span class="st {r["klass"]}">'
            f'{_html_esc(r["status"])}</span>'
            f'<div class="nm">{_html_esc(r["nm"])}</div></div>')
    bad_row_html = ""
    if bad_row:
        bad_row_html = (
            f'<div class="bad-row">'
            f'<span class="lab">[待整改]</span>'
            f'<b>{_html_esc(bad_row["nm"])}</b> '
            f'<span class="lab">问题</span>{_html_esc(bad_row["issue"])} '
            # v1.14.14: 机房建议此前只 _html_esc 不截断, 而 _BRIEF_CLIP 里
            # 专门留了 site_advice=24 却被全仓 0 引用 —— 建议文案一超 24 字
            # 就静默破掉"恒单行"的一页高度锁 (现有测试只挡常量, 挡不住渲染)。
            f'<span class="lab">建议</span>'
            f'{_html_esc(_brief_clip(bad_row["advice"], _BRIEF_CLIP["site_advice"]))}'
            f'</div>')
    site_note_html = ""
    if site_note:
        site_note_html = (
            f'<div class="note"><b>现场备注(装维手输):</b>'
            f'{_html_esc(_brief_clip(site_note, 90))}</div>')

    detail_html = ""
    for d in detail_rows:
        st_text = d["stat"] if d["stat"] != "未检测" else "—"
        detail_html += (
            f'<tr><td class="mod">{_html_esc(d["nm"])}</td>'
            f'<td>{_html_esc(d["verdict"])}</td>'
            f'<td class="num">{_html_esc(d["metric"])}</td>'
            f'<td style="text-align:right">'
            f'<span class="stat {d["stat_class"]}">{_html_esc(st_text)}</span>'
            f'</td></tr>')

    score_color = {"A": "#1e6e44", "B": "#5d80a6", "C": "#ad6e10",
                   "D": "#b8730f", "F": "#b3261e"}.get(grade, "#5b6472")
    circumference = 263.89
    dasharray = f"{circumference * score / 100:.1f} {circumference:.1f}"

    if plan_mbps is None or spd_download is None:
        plan_html = (f'<div class="plan">'
                     f'<div class="head">签约带宽</div>'
                     f'<div class="big num">—</div>'
                     f'<div class="desc">未填写签约带宽</div></div>')
    else:
        plan_class = "" if plan_ok else "fail"
        plan_html = (f'<div class="plan {plan_class}">'
                    f'<div class="head">签约带宽</div>'
                    f'<div class="big num">{_html_esc(plan_str or f"{int(plan_mbps)}M")}</div>'
                    f'<div class="desc">实测下行 {_html_esc(dl or "?")} Mbps'
                    f'<br>阈值 ≥90% → {"达标" if plan_ok else "未达标"}</div></div>')

    logo = _CT_LOGO_BRIEF_B64
    # v1.14.11: plan_ratio 为 None (签约带宽未填或测速无数据) 时不能进 :.0f —
    # 曾在此抛 TypeError 使 export_report 截断后留下 0 字节 HTML/PDF
    headline = ("网络检测完成" if plan_ratio is None else
                f'网络可用、测速<span class="ok">达标 {plan_ratio:.0f}%</span>'
                if plan_ok else f'测速不达标 {plan_ratio:.0f}%')

    html = f'''<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="utf-8">
<title>现场检测报告 · {_html_attr(customer)}</title>
<style>
{CSS_BRIEF_V2}
</style>
</head>
<body>
<div class="page">
  <div class="mast">
    <div class="brand">
      <img src="data:image/png;base64,{logo}" alt="中国电信">
      <div><div class="org">CHINA TELECOM</div>
      <div class="sub">NETPULSE · 现场检测</div></div>
    </div>
    <div class="doc">
      <div class="no">报告编号 {_html_esc((g[:10].replace("-","") if g else "现场") + "-现场")}</div>
      检测日期 {_html_esc(tested_at)}<br>
      现场检测 {total_mods} 项 · 实检 {total_mods} 项
    </div>
  </div>
  <div class="title">
    <h1>{_html_esc(customer)}</h1>
    <div class="strip">
      <div class="l"><span>网络现场检测报告</span>
        <span>{_html_esc(tested_at)}</span>
        {f'<span>签约带宽 {int(plan_mbps)}M</span>' if plan_mbps else ''}
      </div>
      <div class="r">选项 6 · 现场检测报告</div>
    </div>
  </div>
  <div class="score">
    <div class="donut">
      <svg width="100" height="100" viewBox="0 0 100 100">
        <circle cx="50" cy="50" r="42" fill="none" stroke="#eef0f4" stroke-width="9"/>
        <circle cx="50" cy="50" r="42" fill="none" stroke="{score_color}" stroke-width="9"
                stroke-dasharray="{dasharray}" stroke-linecap="butt"
                transform="rotate(-90 50 50)"/>
      </svg>
      <div class="v num"><b>{score}</b><span>SCORE</span></div>
    </div>
    <div class="verdict">
      <div class="grade">{_html_esc(grade)} 级 · {_html_esc(label)}</div>
      <div class="head">{headline}</div>
      <div class="note">{_html_esc(cap)}</div>
    </div>
    {plan_html}
  </div>
  <div class="kpi">
    <div><div class="label">下行实测</div>
      <div class="value num">{_html_esc(dl or "—")}<small>Mbps</small></div>
      <div class="delta">签约 {int(plan_mbps) if plan_mbps else "—"}M</div></div>
    <div><div class="label">上行实测</div>
      <div class="value num">{_html_esc(ul or "—")}<small>Mbps</small></div>
      <div class="delta">{_html_esc(spd_method)}</div></div>
    <div><div class="label">网关延迟</div>
      <div class="value num">{_html_esc(gw_lat_val) if gw_lat_val else "—"}<small>ms</small></div>
      <div class="delta">{gw_lat_delta}</div></div>
    <div><div class="label">出口重传率</div>
      <div class="value num">{_fmt_pct(retrans_rate) or "—"}<small>%</small></div>
      <div class="delta">{'偏高(&lt;2% 优)' if (retrans_rate and retrans_rate > 2) else '正常'}</div></div>
  </div>
  {portline_html}
  {loopline_html}
  <div class="sec-h"><div class="n">§</div><div class="t">主要发现</div>
    <div class="r">按优先级 · 完整根因链见随单完整版报告</div></div>
  <div class="findings">{findings_html}</div>
  <div class="sec-h"><div class="n">§</div><div class="t">机房环境检查</div>
    <div class="r">{n_checked} 项 · {n_checked - n_site_bad} 正常 / {n_site_bad} 待整改</div></div>
  <div class="site">
    <div class="grid6">{site_grid_html}</div>
    {bad_row_html}
    {site_note_html}
  </div>
</div>
<div class="page">
  <div class="mast mast-2">
    <div class="brand">
      <img src="data:image/png;base64,{logo}" alt="中国电信">
      <div><div class="org">CHINA TELECOM</div>
      <div class="sub">现场检测报告 · 检测明细</div></div>
    </div>
    <div class="doc">
      <div class="no">客户:{_html_esc(customer)}</div>
      测试时间:{_html_esc(tested_at)}
    </div>
  </div>
  <div class="sec-h" style="margin-top:6mm"><div class="n">§</div><div class="t">检测明细</div>
    <div class="r">{total_mods} 项 · 技术细节见完整版</div></div>
  <div class="detail" style="padding-top:2mm">
    <table>
      <tr><th style="width:22%">模块</th><th>关键结果</th>
          <th style="width:18%">重点指标</th>
          <th style="width:12%;text-align:right">状态</th></tr>
      {detail_html}
    </table>
  </div>
  <div class="foot">
    <div class="l">随单交付:<b>一页客户报告</b> · 完整版报告 · JSON 原始数据 · PDF(Chrome/Edge)<br>
      整改项建议<b>下次上门免费复核</b></div>
    <div class="r">数据仅反映检测时点<br><b>NetPulse {_html_esc(report.get("version","v1"))}</b></div>
  </div>
</div>
</body>
</html>'''
    return html


def _fmt_kpi_for_detail(key, raw):
    """检测明细表“重点指标”列: 按模块 key 取一个紧凑指标串。

    仅取有意义的标量, 拼不出就空字符串 — 不为追求统一字段名造空值。
    """
    if not isinstance(raw, dict):
        return ""
    if key == "speedtest":
        dl = raw.get("download_mbps"); ul = raw.get("upload_mbps")
        if dl is not None and ul is not None:
            return f"↓ {dl:.0f} · ↑ {ul:.0f} Mbps"
    if key == "gateway":
        p = raw.get("ping") or {}
        if p.get("avg_ms") is not None:
            return f"{p['avg_ms']:.1f} ms"
    if key == "tcpstats":
        r = raw.get("retrans_rate_pct")
        if r is not None: return f"{r:.1f} %"
    if key == "dns":
        items = raw.get("items") or raw.get("results") or []
        if items and isinstance(items, list):
            ms = [it.get("avg_ms") for it in items
                  if isinstance(it, dict) and it.get("avg_ms") is not None]
            if ms: return f"{min(ms):.0f} ms"
    if key == "wifi":
        ch = raw.get("current_channel"); n = raw.get("network_count")
        if ch and n: return f"信道 {ch} · {n} AP"
    if key == "dhcp":
        avail = raw.get("available"); tot = raw.get("total")
        if avail is not None and tot: return f"{avail}/{tot}"
    if key == "lan":
        n = raw.get("device_count") or raw.get("online_count")
        if n is not None: return f"{n} 台"
    if key == "arp":
        bad = raw.get("anomaly_count")
        if bad is not None: return f"{bad} 异常"
    if key == "loop":
        bad = raw.get("loop_count")
        if bad is not None: return f"{bad} 环路"
    if key == "route":
        n = raw.get("route_count")
        if n is not None: return f"{n} 条"
    if key == "mtu":
        m = raw.get("path_mtu") or raw.get("mtu")
        if m is not None: return f"{int(m)}"
    if key == "multiwan":
        n = raw.get("wan_count")
        if n is not None: return f"{n}"
    if key == "ipv6":
        reachable = raw.get("reachable_count"); total = raw.get("total_count")
        if reachable is not None and total: return f"{reachable}/{total}"
    if key == "proxy":
        return (raw.get("detected") and "检测到") or "无"
    if key == "nattype":
        return raw.get("type") or "—"
    if key == "bufferbloat":
        b = raw.get("bloat_ms") or raw.get("added_ms")
        if b is not None: return f"+{b:.0f} ms"
    if key == "web":
        ttfb = raw.get("ttfb_ms") or raw.get("l7_ttfb")
        if ttfb is not None: return f"TTFB {ttfb:.0f} ms"
    if key == "external":
        n = raw.get("reachable_count"); t = raw.get("total_count")
        if n is not None and t: return f"{n}/{t} 目标"
    return ""


