def export_report(path, rule_filter=None, report=None, layout="full"):
    """按扩展名导出客户版报告: .html / .json。

    rule_filter: 场景 profile id (可选, v1.6.1), 透传 build_report() —
                 场景导出与完成屏保持同一规则集。
    report:      预构建的报告 dict (可选, v1.6.1) — 场景路径传入以复用
                 同一份构建结果, 避免重复跑诊断 (审查 #8)。
    layout:      "full" = 客户完整版 (默认, 向后兼容); "brief" = 一页客户
                 报告 (v1.13.0, A4 单页, 现场检测模式出口)。仅对 .html 生效。

    客户版设计:
      - .html → 客户版 HTML (健康分 + 问题清单 + 关键指标 + 折叠技术细节)
      - .json → 技术员/脚本用 (含 raw 原始数据 + 阈值定义)

    PDF 直接导出已移除; 需要纸质留档时, 用浏览器打开 HTML 后 Ctrl+P
    打印或另存为 PDF (打印样式已内置: 技术细节全部展开、去阴影配色)。

    老的 .txt 报告 (拍平所有数据) 已废弃, 导出 .txt 现在会返回错误提示。
    旧的 render_report_text / render_report_html 已删除, 没有可手工调用的
    旧格式入口 —— 需要数据请用 .json, 需要纸质留档用浏览器打印 HTML。
    """
    path = _normalize_report_path(path)
    if report is None:
        report = build_report(rule_filter=rule_filter)
    if not report:
        return "尚无诊断数据，无法生成报告（请先运行诊断）"
    ext = os.path.splitext(path)[1].lower()
    try:
        # v1.14.11: 先渲染后写盘 — 渲染异常时不留 0 字节半成品文件
        if ext in (".html", ".htm"):
            content = (render_report_html_brief(report) if layout == "brief"
                       else render_report_html_brief_v2(report) if layout == "brief_v2"
                       else render_report_html_customer(report))
        elif ext == ".json":
            content = render_report_json(report)
        else:
            content = None
        if content is not None:
            with open(path, "w", encoding="utf-8") as f:
                f.write(content)
            return None
        elif ext == ".pdf":
            return ("PDF 直接导出已移除。请导出 .html 后用浏览器打开, "
                    "Ctrl+P 打印或另存为 PDF。")
        elif ext == ".txt":
            return "TXT 客户版未提供, 改用 --export report.html / .json。"
        else:
            return f"不支持的扩展名: {ext} (支持: .html / .json)"
    except Exception as e:
        return f"导出失败: {e}"


def prompt_export_report():
    """交互菜单跑完后, 询问是否将本次诊断导出为报告文件。

    默认直接生成 HTML (最常用格式), 一次回车即可;
    输入 t 改 TXT(会提示不支持), 其他输入均按默认 HTML 处理。
    """
    if not LAST_RUN:
        return
    try:
        ans = input(_c("  生成诊断报告? [Enter=HTML / t=TXT / N=不导出] » ",
                       C_GREEN)).strip().lower()
    except (EOFError, KeyboardInterrupt):
        return
    if ans in ("n", "no", "q", "quit"):
        return
    ext = ".txt" if ans in ("t", "txt") else ".html"
    ts = datetime.now().strftime("%Y%m%d_%H%M%S")
    name = f"netdiag_report_{ts}{ext}"
    err = export_report(name)
    if err:
        print(_c(f"  ✗ {err}", C_RED))
    else:
        print(_c(f"  ✓ 报告已导出: {os.path.abspath(_normalize_report_path(name))}", C_GREEN))


_CHROMIUM_BROWSER_EXES = ("chrome.exe", "msedge.exe", "chromium.exe",
                          "brave.exe", "vivaldi.exe", "opera.exe",
                          "thorium.exe")  # 已知支持 --print-to-pdf 的内核


def _default_browser_exe():
    """读系统默认浏览器 (https 关联 UserChoice) → 解析出 exe 路径 (v1.14.13)。

    仅返回 Chromium 系浏览器路径 (无头 --print-to-pdf 是 Chromium 内核能力,
    Firefox/IE 无法无头出 PDF → 返回 None 走 Ctrl+P 兕底)。任何失败返回 None。
    """
    try:
        import winreg
    except ImportError:
        return None
    try:
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER,
                            r"SOFTWARE\Microsoft\Windows\Shell\Associations"
                            r"\UrlAssociations\https\UserChoice") as k:
            prog_id = winreg.QueryValueEx(k, "ProgId")[0]
        with winreg.OpenKey(winreg.HKEY_CLASSES_ROOT,
                            prog_id + r"\shell\open\command") as k:
            cmd = winreg.QueryValueEx(k, None)[0] or ""
    except OSError:
        return None
    # 取命令行中第一个 .exe 之前的部分 (兼容引号路径/带参形式)
    m = re.search(r"(.+?\.exe)", cmd, re.IGNORECASE)
    if not m:
        return None
    exe = m.group(1).strip('"')
    if os.path.basename(exe).lower() not in _CHROMIUM_BROWSER_EXES:
        return None
    return exe


def _find_pdf_browser():
    """探测可用于无头打印的浏览器 (v1.14.1: Chrome → Edge 探测链)。

    Edge 是 Win10/11 系统必装且同为 Chromium 内核, 无头打印行为与 Chrome
    完全一致 — 探测链覆盖后, PDF 能力实际是"Windows 自带, 零额外安装"。
    找不到返回 None — 调用方静默跳过 PDF, 不阻塞现场流程 (Ctrl+P 兜底)。
    """
    pf = os.environ.get("ProgramFiles", r"C://Program Files")
    pf86 = os.environ.get("ProgramFiles(x86)", r"C://Program Files (x86)")
    lad = os.environ.get("LOCALAPPDATA", "")
    cands = [
        # Chrome 优先 (与开发预览同内核同版本系)
        os.path.join(pf, r"Google\Chrome\Application\chrome.exe"),
        os.path.join(pf86, r"Google\Chrome\Application\chrome.exe"),
        os.path.join(lad, r"Google\Chrome\Application\chrome.exe"),
        # Edge 兜底: Win10/11 系统必装, 默认装在 x86 Program Files
        os.path.join(pf86, r"Microsoft\Edge\Application\msedge.exe"),
        os.path.join(pf, r"Microsoft\Edge\Application\msedge.exe"),
        os.path.join(lad, r"Microsoft\Edge\Application\msedge.exe"),
    ]
    for c in cands:
        if c and os.path.isfile(c):
            return c
    try:
        import winreg
        for exe in ("chrome.exe", "msedge.exe"):
            for root in (winreg.HKEY_LOCAL_MACHINE, winreg.HKEY_CURRENT_USER):
                try:
                    with winreg.OpenKey(root, r"SOFTWARE\Microsoft\Windows"
                                            r"\CurrentVersion\App Paths"
                                            + "\\" + exe) as k:
                        val = winreg.QueryValue(k, None)
                        if val and os.path.isfile(val):
                            return val
                except OSError:
                    continue
    except ImportError:
        pass
    # v1.14.13: 标准路径都没有 → 问系统默认浏览器 (Brave/Vivaldi/Opera 等
    # Chromium 系内核一样支持无头 --print-to-pdf)
    return _default_browser_exe()


_PDF_PROFILE_DIR = None   # 模块级缓存: 复用 profile, 冷启动 45s → ~3s (实测)


def _html_to_pdf(chrome_exe, html_path, pdf_path, timeout=90):
    """无头 Chrome 把 HTML 打印为 A4 PDF (v1.14.0, 现场模式出口)。

    成功返回 None; 失败返回错误文本 (不抛异常 — 现场流程不能因 PDF 中断)。
    profile 复用 %TEMP%\\np_pdf_profile (不与用户正在运行的 Chrome 抢锁);
    flags 禁首跑/组件更新/后台联网 — 每次新建 profile 的冷启动实测 45s,
    复用 + 禁联网后 ~3s。现场流程不能因 PDF 中断, 任何失败只返回错误文本。
    """
    global _PDF_PROFILE_DIR
    from urllib.parse import quote
    if not _PDF_PROFILE_DIR:
        _PDF_PROFILE_DIR = os.path.join(tempfile.gettempdir(), "np_pdf_profile")
        os.makedirs(_PDF_PROFILE_DIR, exist_ok=True)
    url = "file:///" + quote(html_path.replace("\\", "/"), safe="/:")
    cmd = [chrome_exe, "--headless=new", "--disable-gpu", "--no-sandbox",
           "--no-pdf-header-footer", "--no-first-run", "--disable-extensions",
           "--disable-background-networking", "--disable-component-update",
           "--disable-sync", f"--user-data-dir={_PDF_PROFILE_DIR}",
           f"--print-to-pdf={pdf_path}", url]
    try:
        # CREATE_NO_WINDOW: 不闪黑框 (现场模式在 cmd 里, 子进程弹窗很突兀)
        subprocess.run(cmd, capture_output=True, timeout=timeout,
                       creationflags=subprocess.CREATE_NO_WINDOW)
        if os.path.isfile(pdf_path) and os.path.getsize(pdf_path) > 0:
            return None
        return "Chrome 未产出 PDF 文件"
    except subprocess.TimeoutExpired:
        return f"Chrome 打印超时 (>{timeout}s)"
    except OSError as exc:
        return f"调用 Chrome 失败: {exc}"


def _site_report_base(cust, report_dir=None):
    """现场检测报告的文件名前缀: 客户名消毒 + 按路径预算截断。

    v1.15.0 (审查 P1-17): 客户名可能很长 (粘贴整段合同/地址), 直接进文件名
    会超 Windows MAX_PATH(260) → 落盘直接失败, 三份交付物全丢 (现场白跑)。
    按**完整路径预算**截断 (报告目录自身也可能很深), 留 20 字符余量:
    最长后缀是 "_完整版.html" (10) + 时间戳 (15) + "现场检测_" (11)。
    """
    safe = re.sub(r'[\\/:*?"<>|\s]+', "_", str(cust or "")).strip("_") or "客户"
    ts = datetime.now().strftime("%Y%m%d_%H%M%S")
    report_dir = report_dir if report_dir is not None else _report_dir()
    budget = 240 - len(report_dir) - len(os.sep) - len("现场检测_") \
        - len("_") - len(ts) - len("_完整版.html")
    limit = max(4, min(60, budget))     # 60 = 可读性上限; budget = 硬上限
    if len(safe) > limit:
        safe = safe[:limit].rstrip("_")
    return os.path.join(report_dir, f"现场检测_{safe}_{ts}")


def _warn_ignored_mode(kept, dropped):
    """顶层模式互斥提示 (统一口径, 免得各处文案漂移)。

    v1.15.0 (审查 P1-18): --diagnose / --monitor / --site / --capture 是互斥的
    顶层模式, 组合使用时必须**明确告知**被忽略了谁 —— 静默吞掉会让用户以为
    跑了某个模式、实际没跑 (白等一场)。
    """
    print(_c(f"  提示: --{dropped} 与 --{kept} 是互斥的顶层模式, "
             f"本次已忽略 --{dropped}", C_YELLOW))


def run_site_visit(customer=None, install=False, pip_mirror=None):
    """现场检测模式 (v1.13.0): 上门全量诊断 + 机房 6 项勾选 → 一页客户报告。

    流程: 手输(客户名/检测时间/签约带宽) → 全量诊断(all_module_keys(),
    排除 tcpcc NAT 压测; 含 loopback 环回测速 —— 现场本就是带宽验收场景,
    该模块独占串行跑不影响其它模块) → 机房勾选 →
    同一份 report 出 一页客户报告/完整版/.json (+PDF, Chrome/Edge 任一即可)。
    customer: CLI --customer 预填, 空则终端询问 (必填)。
    """
    if not sys.stdout.isatty():
        print(_c("  错误: 现场检测模式需要交互终端 (直接运行 netpulse --site)。", C_RED))
        sys.exit(4)
    # 与交互菜单同口径: 默认启用 Ookla 官方测速 (上海电信节点)
    SPEEDTEST_CONFIG["use_speedtest_net"] = True
    if not SPEEDTEST_CONFIG.get("ookla_server_id"):
        SPEEDTEST_CONFIG["ookla_server_id"] = OOKLA_DEFAULT_SERVER_ID

    bar = "=" * 60
    print(_c(bar, C_BLUE))
    print(_c(f"  {APP_NAME} v{APP_VERSION}    现场检测模式 (客户报告)", C_BOLD))
    print(_c(bar, C_BLUE))
    print(_c("  流程: 填基本信息 → 网络全量诊断 (约 2~3 分钟, 不含压测) → "
             "机房 6 项勾选 → 生成报告文件 (检测到 Chrome 自动含 PDF)",
             C_WHITE))

    # ── 步骤 1: 手输 (报告里仅有的三处) ──
    cust = (customer or "").strip()
    while not cust:
        try:
            cust = input(_c("  客户名称 (必填) » ", C_GREEN)).strip()
        except (EOFError, KeyboardInterrupt):
            print(_c("\n  已取消。", C_YELLOW))
            return
        if not cust:
            print(_c("  客户名称不能为空。", C_YELLOW))
    try:
        raw_t = input(_c(f"  检测时间 (回车 = "
                         f"{datetime.now().strftime('%Y-%m-%d %H:%M')}) » ",
                         C_GREEN)).strip()
        plan = input(_c("  签约带宽 (建议填写, 用于达标判定, 如 500M) » ",
                        C_GREEN)).strip()
    except (EOFError, KeyboardInterrupt):
        print(_c("\n  已取消。", C_YELLOW))
        return
    tested_at = raw_t or datetime.now().strftime("%Y-%m-%d %H:%M")

    # ── 步骤 2: 网络全量诊断 (排除压力级 tcpcc; port/iperf3 无配置自动跳过) ──
    print()
    print(_c("─" * 60, C_BLUE))
    print(_c("  [1/3] 网络全量诊断 (排除 tcpcc NAT 压测; 含 5 秒环回测速, "
             "独占串行不影响其它模块)", C_BOLD))
    keys = [k for k in all_module_keys() if k not in ("port", "iperf3")]
    run_diagnostics(keys, banner=False, parallel=True, install=install,
                    pip_mirror=pip_mirror, print_modules=False)
    if not LAST_RUN or not LAST_RUN.get("results"):
        print(_c("  诊断未产生数据, 已中止 (可重跑或用普通模式排查)。", C_RED))
        return

    # ── 步骤 3: 机房 6 项勾选 + 现场备注 ──
    print()
    print(_c("─" * 60, C_BLUE))
    print(_c("  [2/3] 机房环境检查 (输入选项数字回车; 直接回车 = 跳过该项)", C_BOLD))
    site_check = {}
    for i, it in enumerate(SITE_CHECK_ITEMS, 1):
        opts = "  ".join(f"{j}={o}" for j, o in enumerate(it["options"], 1))
        while True:
            try:
                ans = input(_c(f"  [{i}/{len(SITE_CHECK_ITEMS)}] {it['label']}"
                               f"  {opts} » ", C_GREEN)).strip()
            except (EOFError, KeyboardInterrupt):
                print(_c("\n  机房勾选提前结束, 已选项目保留。", C_YELLOW))
                ans = ""
                break
            if not ans:
                break
            if ans.isdigit() and 1 <= int(ans) <= len(it["options"]):
                site_check[it["key"]] = it["options"][int(ans) - 1]
                break
            print(_c("  无效输入, 请输入选项数字或直接回车跳过。", C_YELLOW))
    try:
        site_note = input(_c("  现场备注 (可空) » ", C_GREEN)).strip()
    except (EOFError, KeyboardInterrupt):
        site_note = ""

    # ── 步骤 4: 同一份 report 出三件套 ──
    print()
    print(_c("─" * 60, C_BLUE))
    print(_c("  [3/3] 生成报告文件...", C_BOLD))
    report = build_report(site_check=site_check,
                          meta_manual={"customer": cust,
                                       "tested_at": tested_at,
                                       "plan": plan},
                          site_note=site_note)
    if not report:
        print(_c("  报告构建失败 (无诊断数据)。", C_RED))
        return
    # v1.15.0 (审查 P1-17): 客户名过长会让文件名超 MAX_PATH → 落盘失败,
    # 三份交付物全丢。消毒 + 路径预算截断见 _site_report_base。
    base = _site_report_base(cust)
    outs = [(base + ".html", "brief_v2", "一页客户报告 (浏览器打开 Ctrl+P 打印交客户)"),
            (base + "_完整版.html", "full", "完整版报告 (带回 / 上传专家会诊)"),
            (base + ".json", None, "原始数据 JSON (后台深入分析)")]
    done = []
    for path, layout, desc in outs:
        err = export_report(path, report=report, layout=layout)
        if err:
            print(_c(f"  ✗ {desc}: {err}", C_RED))
        else:
            done.append((desc, os.path.abspath(_normalize_report_path(path))))

    # ── 步骤 5: PDF (有 Chromium 内核浏览器才无头产出; 否则默认浏览器 Ctrl+P 兜底) ──
    browser = _find_pdf_browser()
    if browser:
        stem = os.path.basename(browser).lower()
        bname = ("Edge" if "msedge" in stem else "Chrome" if "chrome" in stem
                 else os.path.basename(browser).rsplit(".", 1)[0])
        print(_c(f"  → 检测到 {bname}, 生成 PDF...", C_GRAY))
        err = _html_to_pdf(browser, base + ".html", base + ".pdf")
        if err:
            print(_c(f"  ✗ PDF 生成失败: {err} (可打开 HTML 后 Ctrl+P 另存)",
                     C_YELLOW))
        else:
            done.insert(0, ("一页客户报告 PDF (直接打印交客户)",
                            os.path.abspath(base + ".pdf")))
    else:
        # v1.14.13: 机器上没有任何 Chromium 系浏览器 (默认浏览器是 Firefox 等)
        # → 自动用默认浏览器打开 HTML, Ctrl+P 另存 PDF (任何浏览器都支持)
        print(_c("  → 无 Chromium 内核浏览器可无头出 PDF, 用默认浏览器打开 HTML...",
                 C_GRAY))
        try:
            os.startfile(base + ".html")
            print(_c("    在浏览器里 Ctrl+P → 另存为 PDF 即可", C_GRAY))
        except OSError:
            print(_c("    请手动打开 HTML 后 Ctrl+P 另存为 PDF", C_GRAY))

    print()
    print(_c(bar, C_BLUE))
    if not done:
        print(_c("  ✗ 报告文件全部导出失败, 请检查磁盘与目录权限。", C_RED))
        return
    print(_c("  ✓ 现场检测完成", C_GREEN))
    for desc, path in done:
        print(_c(f"  · {desc}\n    {path}", C_WHITE))
    print(_c("  提示: 一页报告 (PDF/HTML) 打印后交客户;", C_GRAY))
    print(_c("        完整版与 .json 随工单带回, 供专家会诊与后台深析。", C_GRAY))

    # v1.14.7: 自动打开报告所在文件夹, 省去手动找文件 (失败静默不影响收尾)
    try:
        os.startfile(os.path.dirname(done[0][1]))
    except Exception:
        pass



def parse_choice(choice):
    """解析交互菜单输入 -> keys 列表; 无效返回 None。
    支持: 数字 (空格分隔多选)、0/all/* (全部, 含压力级 tcpcc)、分类字母 a/b/c、
    模块 key、模块中文名。
    严格模式: 任一 token 非法即整体拒绝。
    """
    choice = (choice or "").strip()
    if choice == "":
        return None
    if choice.lower() in ("0", "all", "*"):
        print(_c("  全量口径: 全部 %d 模块, 含压力级 tcpcc 压测"
                 " (多目标轮转, 约多花 2 分钟)" % len(MODULE_REGISTRY), C_GRAY))
        return full_module_keys()
    return _parse_keys(choice.split(), strict=True)


def _format_error_for_user(exc):
    """把异常转成 (客户语言一句话, 工程师细节) 两段 (PR-C · v1.6.0)。

    仅场景路径 try/except 包装用; CLI 全量输出不受影响。
    """
    name = type(exc).__name__
    msg = str(exc) or name
    detail = f"[{name}] {msg}"
    if isinstance(exc, KeyboardInterrupt):
        return ("已中断本次检测。", detail)
    if isinstance(exc, PermissionError):
        return ("权限不足：无法执行该检测（请以管理员身份重新运行）", detail)
    if isinstance(exc, socket.gaierror):
        return ("DNS 解析失败：无法解析域名（请检查 DNS 设置或联系运营商）", detail)
    if isinstance(exc, (socket.timeout, TimeoutError)):
        return ("网络超时：请求响应太慢（可能是网络拥堵或运营商故障）", detail)
    return ("检测过程中出错（请重试；连续失败请联系技术支持）", detail)


def _known_folder_desktop():
    """SHGetKnownFolderPath(FOLDERID_Desktop) 解析真实桌面路径 (v1.6.1)。

    一次系统调用覆盖 OneDrive 重定向与本地化目录名 (中文 Windows 的
    重定向桌面是 OneDrive\\桌面, 只探测 OneDrive\\Desktop 会漏); 失败
    (非 Windows / 输出重定向 / API 异常) 返回 None, 由调用方走候选探测。
    """
    if os.name != "nt":
        return None
    try:
        from ctypes import wintypes

        class _GUID(ctypes.Structure):
            _fields_ = [("Data1", wintypes.DWORD), ("Data2", wintypes.WORD),
                        ("Data3", wintypes.WORD), ("Data4", ctypes.c_ubyte * 8)]

        # FOLDERID_Desktop {B4BFCC3A-DB2C-424C-B029-FEFE9560C1C8}
        folderid = _GUID(0xB4BFCC3A, 0xDB2C, 0x424C,
                         (ctypes.c_ubyte * 8)(0xB0, 0x29, 0xFE, 0xFE,
                                              0x95, 0x60, 0xC1, 0xC8))
        buf = ctypes.c_wchar_p()
        if ctypes.windll.shell32.SHGetKnownFolderPath(
                ctypes.byref(folderid), 0, None, ctypes.byref(buf)) != 0:
            return None
        path = buf.value
        ctypes.windll.ole32.CoTaskMemFree(buf)
        return path or None
    except Exception:
        return None


def _desktop_netpulse_dir():
    """桌面 NetPulse 目录; 全不可用返回 None (PR-C / v1.6.1 加固)。

    优先 SHGetKnownFolderPath(FOLDERID_Desktop) — 系统直接给出真实桌面
    (含 OneDrive 重定向与中文本地化目录名); 解析失败再按候选目录探测
    (仅当 OneDrive 桌面真实存在才纳入, 避免普通环境误建 OneDrive 目录);
    都不可写则返回 None, 由调用方退化到 reports/ 目录。
    """
    cands = []
    real = _known_folder_desktop()
    if real:
        cands.append(os.path.join(real, "NetPulse"))
    base = os.environ.get("USERPROFILE") or ""
    if base:
        one_desktop = os.path.join(base, "OneDrive", "Desktop")
        if os.path.isdir(one_desktop):
            cands.append(os.path.join(one_desktop, "NetPulse"))
        one_desktop_cn = os.path.join(base, "OneDrive", "桌面")
        if os.path.isdir(one_desktop_cn):
            cands.append(os.path.join(one_desktop_cn, "NetPulse"))
        cands.append(os.path.join(base, "Desktop", "NetPulse"))
        cands.append(os.path.join(base, "桌面", "NetPulse"))
    for d in cands:
        try:
            os.makedirs(d, exist_ok=True)
            if os.access(d, os.W_OK):
                return d
        except Exception:
            continue
    return None


def _export_scene_report(profile, title, report=None):
    """场景完成后保存 HTML 报告到 桌面\\NetPulse\\, 返回 (path, err) (PR-C)。

    report: 预构建报告 dict (v1.6.1 审查 #8), 复用完成屏同一份构建结果。
    不可写时退化 _report_dir() (原 reports/ 逻辑), 与 CLI --export 无关。
    """
    if not LAST_RUN:
        return None, "尚无诊断数据"
    base = _desktop_netpulse_dir()
    if not base:
        base = _report_dir()
    # 文件名含时分秒: 纯日期命名会让同日复测静默覆盖上午的报告 (审查 #5)
    name = f"{datetime.now():%Y-%m-%d_%H%M%S}_{title}.html"
    path = os.path.join(base, name)
    err = export_report(path, rule_filter=profile, report=report)
    if err:
        return path, err
    return path, None


def _pause_menu_or_open(path=None):
    """完成屏暂停 (控制台现代化批次 2): Enter=返回菜单, [H]=打开报告。

    EOF/Ctrl+C 静默返回 (与 _pause_enter 同语义)。打开动作仅在用户显式
    按 [H] 时执行; 失败提示一行, 不中断回菜单。
    """
    msg = "  [Enter] 返回菜单" + (" / [H] 打开报告" if path else "") + " » "
    try:
        ans = input(_c(msg, C_GREEN)).strip().lower()
    except (EOFError, KeyboardInterrupt):
        print()
        return
    if path and ans in ("h", "open"):
        try:
            if sys.platform == "win32":
                os.startfile(path)
            else:
                webbrowser.open("file://" + path)
        except Exception:
            try:
                print(_c(f"  ✗ 无法打开报告: {path}", C_YELLOW))
            except Exception:
                pass


def _health_box_lines(report):
    """完成屏健康分区行 (批次 2): 分数/等级 + 分数条 + 状态分布 + 豁免说明。

    数据与 HTML 报告**严格同源**: score/grade/label 取 report["health"];
    状态分布对 report["summary"] (全口径) 计数 —— 与 HTML 状态分布条同一
    口径, 避免"框内有红但分布条没红"的口径困惑; 豁免名单走 _exempt_names。
    返回纯函数行列表 (可含 ANSI); health 缺失返回 []。
    """
    health = (report or {}).get("health") or {}
    score = health.get("score")
    if score is None:
        return []
    score_i = max(0, min(100, int(score)))
    grade = str(health.get("grade") or "").strip()
    label = str(health.get("label") or "").strip()
    cells = 26
    filled = (cells * score_i) // 100
    g_color = _grade_color(grade)
    head = _c(f"{score_i}", C_BOLD) + _c(" / 100", C_GRAY)
    if grade:
        head += "  " + _c(f"{grade} 级", g_color) + (
            _c(f" · {label}", C_GRAY) if label else "")
    meta = []
    sel = (report or {}).get("selected_modules")
    tot = (report or {}).get("total_modules")
    if isinstance(sel, int) and isinstance(tot, int) and tot:
        meta.append(f"实检 {sel}/{tot} 项")
    dur = _fmt_duration((report or {}).get("duration_ms"))
    if dur:
        meta.append(dur)
    if meta:
        head += "   " + _c(" · ".join(meta), C_GRAY)
    lines = [head,
             _c("█" * filled + "░" * (cells - filled), g_color)
             + _c(f"  {score_i}", C_GRAY)]
    summary = (report or {}).get("summary") or {}
    dist = Counter(summary.values())
    segs = []
    for st in STATUS_BAR_ORDER:
        n = dist.get(st) or 0
        if n:
            mark, color = CLI_STATUS_MARKS[st]
            segs.append(_c(f"{mark} {st} {n}", color))
    if segs:
        lines.append("   ".join(segs))
    _exm = _exempt_names(report)
    if _exm:
        lines.append(_c("评分豁免: " + "、".join(_exm) + " (不计入扣分)",
                        C_GRAY))
    return lines


def _scene_summary(profile, title, diagnosis, report=None):
    """场景完成屏 (批次 2): 健康分区框 + 根因结论 (复用 _print_diagnosis)。

    report: 预构建报告 dict (v1.6.1 审查 #8), 缺省时兜底自建。
    健康分/等级/分布与 HTML 报告同源 (_health_box_lines); 健康分不可用时
    框内如实说明, 不伪装。
    """
    print()
    print(_c(f"  {APP_NAME} › {title} › 检测完成", C_BOLD))
    try:
        if report is None:
            report = build_report(rule_filter=profile)
    except Exception:
        report = report if isinstance(report, dict) else None
    inner = _health_box_lines(report)
    if not inner:
        inner = [_c("本次未能计算健康分 (数据不足或报告构建失败)", C_GRAY)]
    for ln in _draw_box(inner, title="网络健康", border_color=C_BLUE,
                        text_color=C_GRAY):
        print(ln)
    print()
    if diagnosis is not None:
        _print_diagnosis(diagnosis)
    else:
        print(_c("  ⚠ 本次未能完成根因分析。", C_YELLOW))
    print(_c("─" * min(_term_width() - 2, 76), C_GRAY))


def _pause_enter(msg="  按 Enter 返回主菜单..."):
    """菜单路径通用回车暂停; EOF/Ctrl+C 静默返回 (v1.6.1)。"""
    try:
        input(_c(msg, C_GRAY))
    except (EOFError, KeyboardInterrupt):
        print()


def _run_scene_monitor(install=False, pip_mirror=None):
    """[7] 持续盯障: 输入分钟数 (1-1440, 默认 10) → run_monitor_mode。"""
    print(_c("  持续盯障: 持续监测外网连通性, 找偶发掉线/抖动。", C_WHITE))
    try:
        ans = input(_c("  盯障时长（分钟, 1-1440, 默认 10）» ", C_GREEN)).strip()
    except (EOFError, KeyboardInterrupt):
        print()
        return
    minutes = 10
    if ans:
        try:
            minutes = int(ans)
        except ValueError:
            minutes = 10
    minutes = max(1, min(1440, minutes))
    # 抓包取证菜单入口 (v1.9.6): 时长问完问一次, Enter=不开启 (与 CLI 默认一致)。
    # 不可用 (非管理员/无 Npcap) 时函数内部亮原因后直接返回 None, 不出选择题。
    # v1.9.7 PR-3: 传盯障接续参数 — 仅缺管理员权限时可一键提权重启并直接续盯
    capture_mode, capture_mb = _prompt_for_capture(
        # v1.9.10 修复: --monitor 单位是秒 (argparse metavar=SEC), 此前传分钟
        # 使接续会话 60 倍缩水 (10 分钟 → 30s); 补 --capture — 提权本是为
        # 抓包, 不带则重启后只剩统计层
        resume_tail=["--monitor", str(minutes * 60), "--capture"])
    print(_c(f"  开始盯障 {minutes} 分钟（{minutes*60} 秒）... Ctrl+C 可提前结束", C_BOLD))
    try:
        run_monitor_mode(minutes * 60, capture_mode=capture_mode,
                         capture_mb=capture_mb, capture_confirmed=True)
    # (Exception, KeyboardInterrupt): Ctrl+C 是 BaseException, 只捕 Exception
    # 会把原始回溯打到客户屏幕上, _format_error_for_user 的中断文案成死分支 (审查 #4)
    except (Exception, KeyboardInterrupt) as e:
        user_msg, detail = _format_error_for_user(e)
        print(_c(f"  ✗ {user_msg}", C_RED))
        if sys.stdout.isatty():
            print(_c(f"    {detail}", C_GRAY))
    _pause_enter()


def _run_scene(profile, install=False, pip_mirror=None):
    """执行一个场景: 跑模块 → 根因 (规则过滤) → 完成屏 → 报告存桌面。

    PR-A + PR-B + PR-C 集成点。CLI --diagnose 路径不受影响。
    """
    title = SCENE_LABELS.get(profile, profile)
    keys = DIAGNOSE_PROFILES[profile]
    names = [MODULE_MAP[k][0] for k in keys if k in MODULE_MAP]
    print(_c(f"  场景「{title}」: 将检测 {len(keys)} 项 — ", C_BOLD) + "、".join(names))
    print(_c("  预计 1-3 分钟, 请稍候...", C_GRAY))
    try:
        run_diagnostics(keys, banner=False, parallel=True, max_workers=4,
                        install=install, pip_mirror=pip_mirror,
                        print_modules=False)
    # (Exception, KeyboardInterrupt): Ctrl+C 是 BaseException, 只捕 Exception
    # 会把原始回溯打到客户屏幕上, _format_error_for_user 的中断文案成死分支 (审查 #4)
    except (Exception, KeyboardInterrupt) as e:
        user_msg, detail = _format_error_for_user(e)
        print(_c(f"  ✗ {user_msg}", C_RED))
        if sys.stdout.isatty():
            print(_c(f"    {detail}", C_GRAY))
        _pause_enter()
        return
    # 根因分析 (PR-B: 按场景规则集评估, 避免 gaming 报 wifi 弱等无关根因)
    # v1.6.1 (审查 #8): 诊断只评一次, 完成屏/导出报告复用同一份构建结果 —
    # 屏幕与文件必然一致, 也不再重复跑全量规则评估
    diagnosis = None
    report = None
    if LAST_RUN and LAST_RUN.get("results"):
        try:
            diagnosis = _enrich_diagnosis_evidence(
                diagnose(LAST_RUN["results"], rule_filter=profile),
                LAST_RUN["results"], LAST_RUN.get("evidence"))
        except Exception:
            diagnosis = None
        try:
            report = build_report(
                rule_filter=profile,
                diagnosis=diagnosis.to_dict() if diagnosis else None)
        except Exception:
            report = None
    _scene_summary(profile, title, diagnosis, report=report)
    # 报告存桌面 (PR-C)
    path, err = _export_scene_report(profile, title, report=report)
    if err:
        print(_c(f"  ✗ 报告保存失败: {err}", C_RED))
    else:
        print(_c(f"  📄 报告已保存: {path}", C_GREEN))
    # v1.6.1: 停一拍再回菜单 — 否则完成屏 (健康分/根因/报告路径) 瞬间被清掉。
    # 批次 2: 换成 [Enter] 回菜单 / [H] 打开报告 的双选项暂停。
    _pause_menu_or_open(None if err else path)


def _menu_clear():
    """清屏 (v1.6.1): 先确认 VT 可用再写 ANSI 转义, 否则退化 cls/clear。

    原实现先写转义再探返回值 — _clear_screen 只要写入不抛异常就返回
    True, VT 未启用时旧 conhost 会打出字面乱码且子进程回退永不可达
    (审查 #7)。_module_menu 的同款拷贝已收敛为本函数。
    """
    if _cli_enable_vt() and _clear_screen():
        return
    if os.name == "nt":
        try:
            subprocess.run(["cls"], shell=True, timeout=2)
        except Exception:
            pass
    else:
        try:
            subprocess.run(["clear"], timeout=2)
        except Exception:
            pass


def _log_notice_shown():
    """首次告知是否已弹过 (用户知情权的依据: 告知一次即可, 不反复打扰)。"""
    return bool(_load_log_config().get("notice_shown", False))


def _mark_log_notice_shown():
    cfg = _load_log_config()
    cfg["notice_shown"] = True
    cfg["updated_at"] = datetime.now().isoformat()
    _save_log_config(cfg)


def _log_notice_text():
    """首次告知文案 (说明上报什么 / 不含什么 / 怎么关)。"""
    return [
        "  NetPulse 会把程序自身的异常上报到开发者日志服务器, 便于快速修复。",
        "",
        "  上报内容: 异常类型、完整错误栈、发生在哪个模块/线程、操作系统与",
        "            版本、NetPulse 版本。",
        "  不含: 网络诊断结果、公网 IP、MAC、SSID、账号等任何网络数据。",
        "  用户目录名与机器名会被替换为 <user> / <host>。",
        "",
        "  可随时用菜单 [C] 关闭; 关闭后仅写本地日志, 不再联网。",
    ]


def _offer_log_reporting_notice():
    """首次运行告知异常上报并征询同意。返回 True = 保持开启。

    非 TTY (管道/--json/自动化) 静默跳过 —— 不污染机器可读输出。
    告知过一次不再打扰 (告知与同意分离: 告知一次, 之后用 [C] 自行开关)。
    """
    if not (sys.stdin.isatty() and sys.stdout.isatty()):
        return _log_reporting_enabled()
    if _log_notice_shown():
        return _log_reporting_enabled()
    try:
        lines = _log_notice_text()
        # 批次 2: 统一走 _draw_box 闭环框 (宽度自适应)。回归背景: 早期版本
        # 手工排框横线只画到 47 列, 文字行最宽 67 列, 右侧缺口被当成"边框没
        # 包住内容" (tests/test_log_report.py::test_notice_box_encloses_text 锁)。
        print()
        for ln in _draw_box(lines, title="异常自动上报",
                            border_color=C_CYAN, text_color=C_GRAY):
            print(ln)
        ans = input(_c("  是否保持开启上报? ", C_GREEN)
                    + _c("[Y=开启", C_GREEN) + _c(" / ", C_GRAY)
                    + _c("N=关闭", C_RED) + _c("] » ", C_GREEN)).strip().lower()
    except (EOFError, KeyboardInterrupt):
        print()
        return _log_reporting_enabled()
    enabled = ans not in ("n", "no")
    _set_log_reporting_enabled(enabled)
    _mark_log_notice_shown()
    print(_c("  ✓ 异常上报已开启（如需关闭，菜单按 [C]）" if enabled
             else "  ✓ 异常上报已关闭，仅写本地日志", C_GRAY))
    return enabled


def _toggle_log_reporting_menu():
    """菜单 [C]: 切换异常上报开关 / 运行上报自检。"""
    cur = _log_reporting_enabled()
    print(_c(f"  异常自动上报当前状态: {'已开启' if cur else '已关闭'}", C_GRAY))
    try:
        ans = input(_c("  ", C_GREEN) + _c("[Y] 开启", C_GREEN)
                    + _c("  ", C_GRAY) + _c("[N] 关闭", C_RED)
                    + _c("  ", C_GRAY) + _c("[T] 运行自检", C_CYAN)
                    + _c(" » ", C_GREEN)).strip().lower()
    except (EOFError, KeyboardInterrupt):
        print()
        return
    if ans in ("y", "yes"):
        _set_log_reporting_enabled(True)
        print(_c("  ✓ 异常上报已开启", C_GRAY))
    elif ans in ("n", "no"):
        _set_log_reporting_enabled(False)
        print(_c("  ✓ 异常上报已关闭，仅写本地日志", C_GRAY))
    elif ans in ("t", "test", "check"):
        # v1.18.0: 现场自检 —— 证书链/网络不通时, 上报是静默失效的,
        # 没有自检就永远不知道异常根本没送出去。
        _log_report_selfcheck(verbose=True)
    else:
        print(_c("  未做修改。", C_GRAY))


# ── 控制台现代化批次 2 · 首页横幅与卡片菜单 ──

_NET_INFO_CACHE = {"ts": 0.0, "data": None, "pub": None, "pub_started": False}
_NET_INFO_LOCK = threading.Lock()


def _menu_net_info():
    """首页横幅的本机网络信息 (批次 2)。

    本机/网关/DNS 是毫秒级本地查询, 同步取 (30 秒缓存); 公网 IP/归属地是
    秒级联网查询, 丢后台 daemon 线程 —— **不拖菜单首帧**, 结果下次重绘时
    自然出现 ("联网后补齐")。任何一步失败静默, 横幅不因查询失败缺行。
    """
    now = time.time()
    with _NET_INFO_LOCK:
        stale = (now - _NET_INFO_CACHE["ts"] > 30) or _NET_INFO_CACHE["data"] is None
    if stale:
        data = {"ip": None, "gw": None, "dns": None}
        try:
            data["ip"] = get_local_ip() or None
        except Exception:
            pass
        try:
            data["gw"] = get_default_gateway() or None
        except Exception:
            pass
        try:
            _dl = get_dns_servers()
            data["dns"] = (_dl[0] if isinstance(_dl, list) and _dl
                           else str(_dl or "") or None)
        except Exception:
            pass
        with _NET_INFO_LOCK:
            _NET_INFO_CACHE["data"] = data
            _NET_INFO_CACHE["ts"] = now

        def _fetch_pub():
            pub, geo_str, isp = None, "", ""
            try:
                pub = get_public_ip() or None
            except Exception:
                pass
            if pub:
                try:
                    geo = get_ip_geo(pub)
                    if geo:
                        geo_str = " / ".join(
                            b for b in (geo.get("country"), geo.get("region"),
                                        geo.get("city")) if b)
                        isp = geo.get("isp", "") or geo.get("asn", "") or ""
                except Exception:
                    pass
            with _NET_INFO_LOCK:
                _NET_INFO_CACHE["pub"] = (pub, geo_str, isp)

        with _NET_INFO_LOCK:
            first = not _NET_INFO_CACHE["pub_started"]
            _NET_INFO_CACHE["pub_started"] = True
        if first:
            threading.Thread(target=_fetch_pub, daemon=True,
                             name="np-menu-pubip").start()
    with _NET_INFO_LOCK:
        return (_NET_INFO_CACHE["data"] or {"ip": None, "gw": None, "dns": None},
                _NET_INFO_CACHE["pub"])


def _menu_banner_lines(notice=None, subtitle="网络诊断（场景模式）"):
    """首页横幅 (批次 2): 闭环框 (标题嵌框 + 权限/本机网络行) + 公网补行。

    返回已着色的行列表, 调用方自行 print。纯排版函数, 网络数据走 _menu_net_info。
    """
    data, pub = _menu_net_info()
    segs = [_c("权限: " + ("管理员" if _is_admin() else "普通"),
               C_YELLOW if _is_admin() else C_GRAY)]
    for label, keyk in (("本机", "ip"), ("网关", "gw"), ("DNS", "dns")):
        v = data.get(keyk)
        if v:
            segs.append(_c(f"{label} {v}", C_GRAY))
    # 窄终端放不下时从右往左丢网络段 (权限段保底), 不折行破坏框
    room = max(24, _term_width() - len("  ") - 4)
    while len(segs) > 1 and sum(_disp_width(_ANSI_RE.sub("", s)) + 2
                                for s in segs) > room:
        segs.pop()
    lines = ["  ".join(segs)]
    out = _draw_box(lines, title=f"{APP_NAME} v{APP_VERSION} · {subtitle}",
                    border_color=C_CYAN, text_color=C_GRAY)
    if notice:
        out.append(_c("  " + notice, C_YELLOW))
    pub_ip, geo_str, isp = pub or (None, "", "")
    if pub_ip and pub_ip not in ("未知", "Unknown"):
        tail = " · ".join(x for x in (geo_str, isp) if x)
        out.append(_c(f"  公网 {pub_ip}" + (f" · {tail}" if tail else ""),
                      C_GRAY))
    return out


# 场景菜单卡片副行 (批次 2): 一句话讲清场景测什么。
# 文案严格对齐 DIAGNOSE_PROFILES 各场景实际包含的模块, 不新增能力承诺。
SCENE_MENU_DESC = {
    "slow": "测速 + 缓冲膨胀 + TCP 质量 + WiFi + DNS",
    "disconnect": "外网连通 + 网关丢包 + DNS + 环路",
    "web": "DNS + HTTP 体验 + MTU/路由 + TCP 质量",
    "gaming": "延迟抖动 + NAT 类型 + 缓冲膨胀 + MTU",
    "wifi": "WiFi 信号 + 信道干扰 + 网关 + 局域网",
}

# 工具区菜单项 (键, 名称, 副行)
_SCENE_TOOL_ITEMS = (
    ("6", "现场检测", "客户信息 + 机房 6 项 → 一页报告/PDF"),
    ("7", "持续盯障", "定时监测外网, 抓偶发掉线/抖动"),
    ("9", "高级选项", "模块级单测 / 工程师功能"),
    ("A", "管理员模式", "抓包取证、Npcap 安装需要"),
)


def _menu_item_row(key, name, desc, name_w, show_desc=True):
    """场景菜单行 (批次 2 修订): 无底色 —— 键号青/名称亮白/副行灰。

    实机反馈 (2026-11-12): 原方案的 ANSI 100 亮黑底在经典 conhost 配色下
    是一条明显灰带 (设计稿的"暗色卡片"只在 WT 深色主题成立), 与高级菜单的
    素色风格打架 → 去底色, 只保留结构与对齐。行为与键位语义不变。
    """
    row = _c(f" {key} ", C_CYAN) + " " + _c(_pad_disp(name, name_w), C_WHITE)
    if show_desc and desc:
        row += "  " + _c(desc, C_GRAY)
    return row


def _menu_item_lines(show_desc=True):
    """场景菜单行 (批次 2): 「按问题选场景」+「工具与报告」双分区。

    show_desc=False (窄终端) 时收起副行, 只留键号+名称。返回已着色行列表。
    无底色 (实机反馈移除 ANSI 100 铺底, 见 _menu_item_row docstring)。
    """
    scene_rows = [(key, SCENE_LABELS[p], SCENE_MENU_DESC.get(p, ""))
                  for key, p in SCENE_MENU_KEYS.items()]
    all_rows = scene_rows + list(_SCENE_TOOL_ITEMS)
    name_w = max(_disp_width(n) for _, n, _ in all_rows)
    out = [_c("按问题选场景", C_WHITE)]
    out += [_menu_item_row(k, n, d, name_w, show_desc) for k, n, d in scene_rows]
    out.append("")
    out.append(_c("工具与报告", C_WHITE))
    out += [_menu_item_row(k, n, d, name_w, show_desc)
            for k, n, d in _SCENE_TOOL_ITEMS]
    return ["  " + ln for ln in out]


def _scene_menu(install=False, pip_mirror=None):
    """场景层首页 (PR-A · v1.6.0): 中文场景标签 + 数字回车。

    返回 False = 退出程序 ([0] 退出 / [9] 高级页里退出 / Ctrl+C)。
    v1.9.7 PR-3: [A] 一键以管理员身份重启。
    控制台现代化批次 2: 闭环框横幅 (权限/本机网络进框, 公网联网后补行)
    + 双分区菜单 (副行按 DIAGNOSE_PROFILES 校准, 窄终端自动收起)。
    """
    while True:
        _menu_clear()
        notice = _update_notice_line()
        for ln in _menu_banner_lines(notice=notice):
            print(ln)
        print()
        # v1.19.x: 副行在**窄或矮**终端收起 (画布宽高都是冻结的固定值)
        for ln in _menu_item_lines(show_desc=(_term_width() >= 64
                                              and _term_height() >= 26)):
            print(ln)
        print()
        # v1.17.0: 异常上报开关。退出项只出现一次 —— 之前这行自带一个
        # "[0] 退出", 与上一行的退出项重复, 菜单看着像有两个退出口。
        print(_c("    ", C_GRAY) + _c("[C]", C_CYAN)
              + _c(" 异常上报: ", C_GRAY)
              + _c("已开启" if _log_reporting_enabled() else "已关闭", C_GRAY)
              + _c("    ", C_GRAY) + _c("[0]", C_CYAN) + _c(" 退出", C_GRAY))
        print(_c("─" * min(_term_width() - 2, 76), C_GRAY))
        try:
            choice = input(_c("  选择 [0-9AC] » ", C_GREEN)).strip().lower()
        except (EOFError, KeyboardInterrupt):
            print()
            return False
        if choice in ("0", "q", "quit", "exit"):
            return False
        if choice == "c":
            _toggle_log_reporting_menu()
            continue
        if choice == "a":
            # 一键提权重启: 提权成功 → sys.exit(0) (不会走到这里); 失败/取消
            # → 落回菜单继续 (不藏退路)
            # v1.14.14: 原先不传 args_tail → 提权后空参数启动, `--no-scapy`
            # / `--verbose` / `--pip-mirror` 等全部丢失, 与 README「UAC 确认后
            # 接续当前意图」不符 (scapy 与抓包两条路径都透传了, 只有这里漏网)。
            # argv 为空 (双击 exe) 时传空列表, 行为与原先一致。
            _offer_elevation_relaunch(
                list(sys.argv[1:]),
                reason="抓包取证、Npcap 安装等功能需要管理员权限")
            continue
        if choice == "9":
            # 高级页 (原模块清单菜单) 里退出 → 整个程序退出
            if not _module_menu(install=install, pip_mirror=pip_mirror):
                return False
            continue
        if choice == "6":
            run_site_visit(install=install, pip_mirror=pip_mirror)
            continue
        if choice == "7":
            _run_scene_monitor(install=install, pip_mirror=pip_mirror)
            continue
        if choice in SCENE_MENU_KEYS:
            _run_scene(SCENE_MENU_KEYS[choice], install=install,
                       pip_mirror=pip_mirror)
            continue
        print(_c("  无效选择, 请重新输入。", C_YELLOW))
        try:
            input(_c("  按 Enter 继续...", C_GRAY))
        except (EOFError, KeyboardInterrupt):
            return False


def interactive_menu(install=False, pip_mirror=None):
    """交互式场景菜单 (cmd 窗口, v1.6.0)。

    无参数启动 → 场景层 (中文场景标签 + 数字回车);
    [9] 高级选项 = 原模块清单菜单 (工程师用), 行为与 v1.5.x 一致。

    install: 是否允许在交互过程中自动安装缺失依赖
             (与 CLI --install 联动)。
    pip_mirror: 透传给 ensure_scapy。

    并发策略:
      - 选 0 / 选多个模块 -> 默认并发 (跟 CLI `all --parallel` 对齐,
        选全部时绝大多数用户想要快而不是看实时进度)
      - 选单模块 -> 走顺序, 让 TTY 实时进度行 (\\r\\033[K 刷新) 正常显示
      - run_diagnostics 内部 `parallel and len(keys) > 1` 会自动归一化

    测速模块: 交互菜单默认启用 Ookla 官方测速 (上海电信节点 3633),
    无需 --speedtest-net; CLI 模式仍需显式加 --speedtest-net。
    """
    # 交互菜单: 默认启用 Ookla 官方测速 (上海电信节点, 避免自动选点偏海外)
    # CLI 模式不受影响 (CLI 需显式 --speedtest-net)
    SPEEDTEST_CONFIG["use_speedtest_net"] = True
    if not SPEEDTEST_CONFIG.get("ookla_server_id"):
        SPEEDTEST_CONFIG["ookla_server_id"] = OOKLA_DEFAULT_SERVER_ID
    # v1.19.x: 交互会话走**备用屏幕缓冲区** (程序独占整屏, 退出时恢复用户
    # 原屏幕)。菜单本来每屏都要 cls 清屏, 换备用屏幕后不再污染回滚缓冲,
    # 且整屏尺寸固定 → 长内容不会把边框挤歪。
    with _console_fullscreen():
        # v1.17.0: 首次运行告知异常自动上报 (征询同意; 非 TTY 静默跳过)
        try:
            _offer_log_reporting_notice()
        except Exception:
            pass
        if not _scene_menu(install=install, pip_mirror=pip_mirror):
            return


def _module_menu_lines():
    """高级菜单内容行 (2026-11-12 紧凑化): 与场景菜单同风格的分区 + 两列模块行。

    压缩要点: 分区标题 `[字母] 分类 (副题灰)`, 行内两列 `NN 名称` (键号青),
    去掉独立工程师说明行与括号长注释 —— 命令收进脚注一行。
    模块名按显示宽 pad 到全局一致 ("链路速率" 8 宽 vs "LAN 设备扫描" 12 宽,
    不 pad 会让左列右端参差); 用 ASCII 空格 pad (全角空格在 Consolas 下仅
    0.37 倍 ASCII 宽, 不能用作 pad)。历史上 cell 末尾的 " (key)" 段因 cmd +
    Consolas 汉字实宽 1.629 倍导致像素错位而移除, 用户仍可用序号/分类字母选择。
    纯排版函数, 便于测试行数预算 (默认 30 行窗口内放下)。
    """
    all_names = [MODULE_MAP[k][0]
                 for _cat_keys in (kc[1] for kc in MODULE_CATEGORIES)
                 for k in _cat_keys]
    name_max_w = max((_disp_width(n) for n in all_names), default=0)
    out = []
    idx = 0
    for ci, (cat_name, keys, desc) in enumerate(MODULE_CATEGORIES):
        if ci > 0:
            out.append("")
        letter = MODULE_NAME_LETTER.get(cat_name, "")
        tag = _c(f"[{letter}]", C_CYAN) if letter else ""
        out.append(_c(f"  {tag} {cat_name}", C_WHITE)
                   + _c(f"  {desc}", C_GRAY))
        cells = []
        for k in keys:
            idx += 1
            n = MODULE_MAP[k][0]
            padded = n + " " * (name_max_w - _disp_width(n))
            cells.append(_c(str(idx).rjust(2), C_CYAN) + " "
                         + _c(padded, C_WHITE))
        for line in _columnize(cells, columns=2, gap=6):
            out.append("  " + line)
    return out


def _module_menu(install=False, pip_mirror=None):
    """原模块清单菜单 (v1.6.0 起为场景层 [9] 高级选项)。

    行为与 v1.5.x 一致 (模块编号 / 分类 / 0 全部 / m 盯障 / e 导出 / q 退出);
    返回语义 (v1.9.3): r = 返回场景层主菜单 → True; q / Ctrl+C / EOF → False
    (通知场景层结束整个程序)。
    2026-11-12 紧凑化: 排版收敛为 _module_menu_lines (场景菜单同风格),
    命令脚注一行, 默认 30 行命令行窗口整屏放下。
    """
    # v1.15.2 (审查 P1-16): 最近一次诊断的完整数据。run_diagnostics 现在返回
    # run dict, 这里存成局部变量供下游显式取用 (调试包等), 避免再直读全局。
    last_run = None
    while True:
        _menu_clear()
        notice = _update_notice_line()
        for ln in _menu_banner_lines(notice=notice, subtitle="命令行网络诊断"):
            print(ln)
        for ln in _module_menu_lines():
            print(ln)
        print()
        # 命令脚注一行化 (2026-11-12 紧凑化): 旧版 6 行选项 + 快捷行内容重复
        print(_c("    ", C_GRAY) + _c("0", C_CYAN) + _c(" 全部诊断   ", C_GRAY)
              + _c("m", C_CYAN) + _c(" 盯障   ", C_GRAY)
              + _c("e", C_CYAN) + _c(" 导出报告   ", C_GRAY)
              + _c("d", C_CYAN) + _c(" 调试包   ", C_GRAY)
              + _c("r", C_CYAN) + _c(" 返回场景   ", C_GRAY)
              + _c("q", C_CYAN) + _c(" 退出", C_GRAY))
        print(_c("─" * min(_term_width() - 2, 76), C_GRAY))
        try:
            choice = input(_c("  输入 » ", C_GREEN)).strip()
        except (EOFError, KeyboardInterrupt):
            print()
            break
        if choice.lower() in ("q", "quit", "exit"):
            break
        # r / return: 返回场景层主菜单 (v1.9.3)。r 不与分类字母 (a/b/c)、
        # 模块 key 或命令 (m/e) 冲突; 置于 parse_choice 之前, 避免被当模块解析
        if choice.lower() in ("r", "return", "back", "返回", "回场景", "场景"):
            return True
        # m / monitor: 盯障模式 (独立运行模式, 不进模块注册表)
        # 默认 600 秒直接跑, 不再询问时长 (减少输入; Ctrl+C 可提前结束)
        if choice.lower() in ("m", "monitor", "盯障"):
            run_monitor_mode(600)
            try:
                input(_c("  按 Enter 返回菜单...", C_GRAY))
            except (EOFError, KeyboardInterrupt):
                break
            continue
        # e / export: 不跑诊断, 直接导出上次报告 (回车返回菜单后无需重新测试)
        if choice.lower() in ("e", "export", "导出"):
            if not LAST_RUN:
                print(_c("  尚无诊断数据，请先运行一次诊断。", C_YELLOW))
            else:
                prompt_export_report()
            try:
                input(_c("  按 Enter 返回菜单...", C_GRAY))
            except (EOFError, KeyboardInterrupt):
                break
            continue
        # d / debug: 生成脱敏调试包 (v1.9.6, --debug-bundle 的菜单入口)。
        # 上报排障主通道: 无诊断数据时提示先跑 (不像 CLI 那样自动跑全诊断 —
        # 菜单里 30-120 秒的意外等待比一次提示更伤)。
        if choice.lower() in ("d", "debug", "调试包"):
            if not _has_diagnostic_data():
                print(_c("  尚无诊断数据，请先运行一次诊断 (0=全部 或选模块)。", C_YELLOW))
            else:
                print(_c("  → 打包: system.json + diagnostic.json + evidence.json"
                         " + netpulse.log (SSID/MAC/公网IP/主机名 已脱敏)", C_GRAY))
                # v1.15.2 (审查 P1-16): 显式传 run。菜单里 last_run (run_diagnostics
                # 的返回值) 与全局 LAST_RUN 是同一份对象; last_run 为空时回落全局
                # (兼容不经菜单跑诊断的路径)。
                _export_debug_bundle(_report_dir(), last_run if last_run else LAST_RUN)
                print(_c("  → 请将 zip 文件发给后端/厂商支持, 无需手工截图。", C_GRAY))
            try:
                input(_c("  按 Enter 返回菜单...", C_GRAY))
            except (EOFError, KeyboardInterrupt):
                break
            continue
        keys = parse_choice(choice)
        if keys is None:
            print(_c("  无效选择, 请重新输入。", C_YELLOW))
            try:
                input(_c("  按 Enter 继续...", C_GRAY))
            except (EOFError, KeyboardInterrupt):
                break
            continue
        # 端口探测: 单选 port 时才询问目标; 选 0/全部时自动跳过 (避免打断全流程)
        # (用户偏好: 端口探测必须有显式目标, 全量诊断时没目标就跳过不测)
        # "全部"判定: 与 full_module_keys() 对齐 (v1.8.1 起压力级进出于
        # all 口径, len(MODULE_REGISTRY) 常数比较会失效 — 曾导致选 0 被
        # port/web/测速/iperf3 四个单选询问连续打断)
        is_all = (len(keys) == len(full_module_keys())
                  and set(keys) == set(full_module_keys()))
        if "port" in keys and not PORT_PROBE_CONFIG.get("targets"):
            if is_all:
                # 全量诊断: 没目标就跳过端口探测, 不打断流程
                print(_c("  → 端口探测无目标, 自动跳过 (单独选 port 可指定目标)", C_GRAY))
                keys = [k for k in keys if k != "port"]
            elif sys.stdout.isatty():
                prompted = _prompt_for_port_targets()
                if prompted is None:
                    print(_c("  已取消端口探测, 其余模块继续。", C_YELLOW))
                    keys = [k for k in keys if k != "port"]
                    if not keys:
                        try:
                            input(_c("  按 Enter 返回菜单...", C_GRAY))
                        except (EOFError, KeyboardInterrupt):
                            break
                        continue
                else:
                    tgt, proto, cnt = prompted
                    PORT_PROBE_CONFIG["targets"] = tgt
                    PORT_PROBE_CONFIG["proto"] = proto
                    PORT_PROBE_CONFIG["count"] = cnt
            else:
                keys = [k for k in keys if k != "port"]
        # 网页体检: 单选时询问追加目标 (v1.9.6, --web-target 的菜单入口)。
        # 全量诊断默认 3 站照跑, 不打断流程; 已有目标 (CLI 传入/本会话答过) 不再问。
        if ("web" in keys and not WEB_CONFIG.get("targets")
                and not is_all and sys.stdout.isatty()):
            extra = _prompt_for_web_targets()
            if extra:
                WEB_CONFIG["targets"] = extra
        # 测速: 单选时询问换节点 (v1.9.6, --speedtest-node 的菜单入口)。
        # 一次会话只问一次 (_node_prompted 标记); 全量诊断直接默认节点。
        if ("speedtest" in keys and not is_all and sys.stdout.isatty()
                and not SPEEDTEST_CONFIG.get("_node_prompted")):
            SPEEDTEST_CONFIG["_node_prompted"] = True
            _node = _prompt_for_speedtest_node()
            if _node:
                # 写入口径与 CLI --speedtest-node 一致: 始终记 node, 数字 ID
                # 同时切 ookla_server_id (覆盖默认 3633)
                SPEEDTEST_CONFIG["node"] = _node
                if _node.isdigit():
                    SPEEDTEST_CONFIG["ookla_server_id"] = int(_node)
                    print(_c(f"  → Ookla 节点切换为 {_node}", C_GRAY))
                else:
                    print(_c(f"  → 测速上行节点: {_node}", C_GRAY))
        # iperf3 模块: 单选 iperf3 时才询问服务器; 选 0/全部时自动跳过
        # (iperf3 需要用户自备服务器, 全量诊断时没服务器就跳过不测)
        if ("iperf3" in keys and not SPEEDTEST_CONFIG.get("iperf3_server")):
            if is_all:
                print(_c("  → iperf3 无服务器, 自动跳过 (单独选 iperf3 可配置)", C_GRAY))
                keys = [k for k in keys if k != "iperf3"]
            elif sys.stdout.isatty():
                iperf3 = _prompt_for_iperf3()
                if iperf3 is not None:
                    host, port = iperf3
                    SPEEDTEST_CONFIG["iperf3_server"] = host
                    SPEEDTEST_CONFIG["iperf3_port"] = port
                    print(_c(f"  → iperf3 server: {host}:{port}", C_GRAY))
                    Iperf3Tester()._find_iperf3(auto_download=True)
                else:
                    print(_c("  → 未提供 iperf3 服务器, 该模块运行时会提示缺少服务器", C_GRAY))
            else:
                keys = [k for k in keys if k != "iperf3"]
        # iperf3 测速口径 (v1.9.6, --iperf3-udp 的菜单入口): 服务器已具备
        # (CLI 传入或刚答) 且单选时追问一次 TCP/UDP; 一次会话只问一次。
        if ("iperf3" in keys and not is_all and sys.stdout.isatty()
                and SPEEDTEST_CONFIG.get("iperf3_server")
                and not SPEEDTEST_CONFIG.get("_iperf3_mode_prompted")):
            SPEEDTEST_CONFIG["_iperf3_mode_prompted"] = True
            if _prompt_for_iperf3_mode() == "udp":
                SPEEDTEST_CONFIG["iperf3_udp"] = True
                print(_c("  → iperf3 改用 UDP 口径 (抖动/丢包, 1 Mbps 发包率)", C_GRAY))
        # 菜单模式: 多模块默认并发 (与 CLI `all --parallel` 对齐)。
        # run_diagnostics 内部 `parallel and len(keys) > 1` 会自动避免
        # 单模块走并发 (无意义且会浪费线程开销)。
        # print_modules: 多模块跑法终端不逐模块铺开 (2026-11-12 用户拍板),
        # 只给一段汇总框; 单模块仍打印完整结论 (工程师单测就是看指标)。
        last_run = run_diagnostics(keys, banner=False, parallel=True,
                                   max_workers=4,
                                   print_modules=len(keys) == 1)
        if sys.stdout.isatty():
            # 单独跑测速时跳过"生成综合诊断报告"询问: 测速已自动保存独立的
            # 专业测速报告 (HTML+JSON), 再问会产生冗余的 netdiag_report_*
            if keys == ["speedtest"] or keys == ["iperf3"]:
                print(_c(f"  测速报告已自动保存至 reports/ 目录 ({keys[0]}_时间戳.html/.json)。",
                         C_GRAY))
            else:
                prompt_export_report()
        try:
            input(_c("\n  按 Enter 返回菜单...", C_GRAY))
        except (EOFError, KeyboardInterrupt):
            break
    # q / Ctrl+C / EOF → False (退出整个程序); r → True (返回场景层) 已在上面提前 return
    return False


# ══════════════════════════════════════════════════════════════════════════
# 本地 GUI 壳 (v1.21.0): 会话快照 / HTTP 服务 / 浏览器拉起。零第三方依赖。
# 数据流: run_diagnostics(progress_cb=…) → _GuiSession(线程安全快照)
#         → JSON API (页面 1s 轮询)。新代码不直接读写 LAST_RUN (收口规则 2):
#         run dict 一律取自 run_diagnostics 返回值; build_report/export_report
#         等既有函数内部的管线机制照旧沿用。
# 状态色唯一来源 STATUS_COLORS/STATUS_KEY: API 组装载荷下发, 页面 JS 不内嵌色表。
# ══════════════════════════════════════════════════════════════════════════

_GUI_BROWSER_PROC = []   # 浏览器子进程句柄, 防 GC 回收进程对象
_GUI_SHUTDOWN = threading.Event()   # GUI 停机信号 (Task 3 的 HTTP 服务线程消费)

# 区段级集中 import (Task 2 惯例)。http.server 必须在模块导入期可用:
# _GuiHandler 的类基址在 class 语句执行时求值, 不能等到 _start_gui_server 才 import。
import http.server
import hmac
import urllib.parse as urllib_parse

# 顶栏联网状态 (v1.21.0 收尾): 探测线程的数据源 + 互斥锁。ok 三态:
# True=通 / False=不通 / None=未测 (页面显示「检测中」)。
_GUI_NET = {"ok": None, "ts": 0.0}
_GUI_NET_LOCK = threading.Lock()
_GUI_NET_HOSTPORT = ("223.5.5.5", 53)  # 公共 DNS TCP 53, 与盯障默认目标一致


def _gui_conn_check(host=None, port=None, timeout=2.0):
    """单次连通性探测: TCP 建连公共 DNS 53 端口。返回 True/False (异常=False)。"""
    try:
        import socket as _s
        hp = (host, port) if host else _GUI_NET_HOSTPORT
        with _s.create_connection(hp, timeout=timeout):
            return True
    except OSError:
        return False


def _gui_net_watch(shutdown_evt=None):
    """每 30 秒探测一次, 结果写 _GUI_NET (顶栏圆点数据源)。启动即先测一次。"""
    while not (shutdown_evt is not None and shutdown_evt.is_set()):
        ok = _gui_conn_check()
        with _GUI_NET_LOCK:
            _GUI_NET["ok"] = ok
            _GUI_NET["ts"] = time.time()
        if shutdown_evt is not None:
            shutdown_evt.wait(30.0)
        else:
            time.sleep(30.0)


def _GUI_RESET_FOR_TEST():
    """测试隔离: 清 GUI 区段模块级状态。Task 4/6 在此追加 handler 清理项。"""
    global _GUI_RESUME_PATH
    _GUI_SHUTDOWN.clear()
    _GuiHandler.session = None
    _GuiHandler.token = None
    _GuiHandler.shutdown_evt = None
    _GuiHandler.monitor = None   # v1.22.0: 盯障 GUI 会话 (_GUI_ACT_LOCK 无状态不清)
    del _GUI_BROWSER_PROC[:]   # Task 6: 浏览器子进程句柄 (防测试间泄漏)
    with _GUI_NET_LOCK:        # 顶栏联网状态探测数据源 (v1.21.0 收尾)
        _GUI_NET["ok"] = None
        _GUI_NET["ts"] = 0.0
    # v1.24.0: 续跑点路径改到临时目录 —— 测试绝不碰开发机真实的
    # %LOCALAPPDATA%\NetPulse\resume.json (本机留过续跑点就会让
    # /api/scenarios 的载荷带上它, 测试结果随机器状态漂)。
    _GUI_RESUME_PATH = os.path.join(tempfile.gettempdir(),
                                    "netpulse_test_resume.json")
    try:
        if os.path.exists(_GUI_RESUME_PATH):
            os.remove(_GUI_RESUME_PATH)
    except Exception:
        pass


def _gui_verdict(report):
    """GUI 报告页结论条数据 (终审 F4): 只透传不自算。

    score/grade/label 取 report["health"] 既有字段 (与客户版报告 Hero 同源);
    summary 对 report["summary"] (全口径 {模块: 状态}) 按状态中文计数 ——
    与终端 _health_box_lines / HTML 状态分布条同一口径。health 缺失 → None。
    """
    health = (report or {}).get("health") or {}
    if not health:
        return None
    counts = {}
    for st in ((report or {}).get("summary") or {}).values():
        counts[st] = counts.get(st, 0) + 1
    return {"score": health.get("score"), "grade": health.get("grade"),
            "label": health.get("label"), "summary": counts}


def _GUI_LABELS(profile, keys=None):
    """场景/全量诊断的中文标题 (主页卡与导出文件名共用)。

    v1.23.0: keys 组合模式 (profile 空 + keys 非空) → 「模块组合 (N 项)」。
    """
    if keys and not profile:
        return "模块组合 (%d 项)" % len(keys)
    if profile == "full":
        return "完整诊断"
    if profile == "site":
        # 终审 #5: site 不在 SCENE_LABELS, 原先回落成英文 profile id "site"
        # (现场检测流程里导出的文件名带着英文), 与页面卡片文案「现场检测」同词
        return "现场检测"
    return SCENE_LABELS.get(profile, str(profile))


def _gui_validate_keys(keys):
    """v1.23.0 keys 组合白名单校验 (服务端, F4 红线: 防绕过):
    非空、均为 MODULE_REGISTRY 已知 key、去重保序。
    返回 (clean_keys, None) 或 (None, err)。"""
    if not isinstance(keys, list) or not keys:
        return None, "keys 必须为非空数组"
    clean = []
    for k in keys:
        if not isinstance(k, str) or k not in MODULE_MAP:
            return None, "未知模块: %s" % (k,)
        if k not in clean:
            clean.append(k)
    return clean, None


def _gui_profile_keys(profile):
    """profile id → 本轮模块集; 未知场景 → None。

    v1.23.0 终审修复波抽出: start() 与 /api/run 注入段共用同一解析,
    防两处口径漂移。full=full_module_keys() (含 port/iperf3, 注入段
    对其同样生效); site 走 start_site 专属流程不在此列。
    """
    if profile == "full":
        return full_module_keys()
    if profile in DIAGNOSE_PROFILES:
        return list(DIAGNOSE_PROFILES[profile])
    return None


def _gui_apply_run_config(d, keys):
    """v1.23.0 (终审修复波) /api/run 每轮配置注入: 注入状态完全由本轮
    请求决定 (profile 形态与 keys 形态统一 — 场景卡请求不带字段, 面板
    上轮注入不跨轮残留, spec F2/S3.1「留空 = 诚实降级」)。

    仅当对应模块在本轮模块集 (keys) 里才消费对应字段:
      port_targets      → PORT_PROBE_CONFIG["targets"]: 缺失/留空 →
                          重置 [] (诚实「未提供目标」); 显式 → 逗号分隔
                          逐段 _parse_target 校验 (brief 写"正则", 按仓内
                          先例修正为复用终端同源解析器 — 附带 IPv6/范围
                          越界/倒序校验), 非法 → err 400
      iperf3_server     → SPEEDTEST_CONFIG["iperf3_server"/"iperf3_port"]:
                          缺失/留空 → 重置 server=None (「未检测」);
                          显式 → _parse_iperf3_server 校验拆分 (非法 →
                          err 400, CLI sys.exit(4) 同口径), 写入键与
                          CLI 一致
      use_speedtest_net → SPEEDTEST_CONFIG["use_speedtest_net"]: 缺失 →
                          无条件重置 False (v1.21 起 GUI 场景/全量默认即
                          False, 面板显式开才 True, True 不跨轮残留);
                          显式 → 必须为真布尔才消费 (仅 speedtest 在
                          keys), 非布尔 (如字符串 "false") 按缺失处理走
                          重置 — 防 bool("false")==True 静默误开
    校验全部通过才落盘 (不做部分写入, 重置项与写入项同批生效)。
    返回 None 或 err 字符串。
    """
    keyset = set(keys)
    writes = []
    if "port" in keyset:
        raw = str(d.get("port_targets") or "").strip()
        if not raw:
            writes.append((PORT_PROBE_CONFIG, "targets", []))
        else:
            specs = []
            for seg in raw.replace("，", ",").split(","):
                seg = seg.strip()
                if not seg:
                    continue
                if _parse_target(seg) is None:
                    return "端口目标格式非法: %s" % seg
                specs.append(seg)
            writes.append((PORT_PROBE_CONFIG, "targets", specs))
    if "iperf3" in keyset:
        raw = str(d.get("iperf3_server") or "").strip()
        if not raw:
            writes.append((SPEEDTEST_CONFIG, "iperf3_server", None))
        else:
            parsed = _parse_iperf3_server(raw)
            if parsed is None:
                return "iperf3 服务器地址非法: %s" % raw
            writes.append((SPEEDTEST_CONFIG, "iperf3_server", parsed[0]))
            writes.append((SPEEDTEST_CONFIG, "iperf3_port", parsed[1]))
    if "use_speedtest_net" not in d:
        writes.append((SPEEDTEST_CONFIG, "use_speedtest_net", False))
    elif isinstance(d.get("use_speedtest_net"), bool):
        if "speedtest" in keyset:
            writes.append((SPEEDTEST_CONFIG, "use_speedtest_net",
                           d["use_speedtest_net"]))
    else:
        # 非布尔 (如字符串 "false") → 按缺失处理走重置 (bool() 陷阱)
        writes.append((SPEEDTEST_CONFIG, "use_speedtest_net", False))
    for cfg, key, val in writes:
        cfg[key] = val
    return None


# ────────────────────────────────────────────────────────────────────────────
# GUI 续跑点 (v1.24.0): 诊断中途停止后, 把「已经测完的项目」落盘 ——
# 关窗、退出程序都不丢; 下次打开 NetPulse 提示「上次没跑完, 接着跑?」。
#
# 位置: %LOCALAPPDATA%\NetPulse\resume.json (与 log_report.json 同目录约定)。
# 只保留**一个**未完成轮次 (设计如此, 见 spec 非范围) —— 新一轮停止时覆盖。
# 写失败绝不打断当轮流程 (只是没法续跑, 报告照出)。
# ────────────────────────────────────────────────────────────────────────────

_GUI_RESUME_FILE = "resume.json"
_GUI_RESUME_MAX_AGE = 7 * 24 * 3600      # 续跑点最多留 7 天 (过期自动清理)
_GUI_RESUME_PATH = None                 # 测试隔离用 (见 _GUI_RESET_FOR_TEST)


def _gui_resume_path():
    """续跑点路径: %LOCALAPPDATA%\\NetPulse\\resume.json (测试可覆盖)"""
    if _GUI_RESUME_PATH:
        return _GUI_RESUME_PATH
    base = os.environ.get("LOCALAPPDATA") or tempfile.gettempdir()
    return os.path.join(base, "NetPulse", _GUI_RESUME_FILE)


def _gui_resume_clean(data):
    """校验并清洗续跑点内容。返回清洗后的 dict, 结构非法返回 None。

    清洗规则: completed 里某个模块的 result 不是 dict (坏数据) → **剔除该
    模块**, 续跑时当它没测完、重跑一遍 —— 绝不把坏数据带进报告。
    """
    if not isinstance(data, dict):
        return None
    keys = data.get("keys")
    if not isinstance(keys, list) or not keys:
        return None
    done = data.get("completed")
    if not isinstance(done, dict):
        return None
    clean = {}
    for k, item in done.items():
        if not isinstance(item, dict):
            continue
        res = item.get("result")
        if not isinstance(res, dict):
            continue                      # 坏数据 → 重跑该模块
        clean[k] = {"status": item.get("status"),
                    "result": res}
    out = dict(data)
    out["completed"] = clean
    return out


def _gui_resume_save(payload):
    """把续跑点原子写入磁盘。返回 (True, None) 或 (False, 错误文案)。

    原子写: 先写同目录临时文件再 os.replace —— 进程被杀/断电不会留半截文件
    (半截 JSON 读回来是「损坏」, 白白丢掉已测完的成果)。
    """
    if not isinstance(payload, dict) or not payload:
        return False, "续跑点内容为空"
    path = _gui_resume_path()
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
    except Exception as e:
        return False, "续跑点目录不可写（%s）" % e
    tmp = path + ".tmp"
    try:
        with open(tmp, "w", encoding="utf-8") as f:
            # default=str: 模块结果里可能有非 JSON 原生类型 (dataclass 等),
            # 落盘时退化成字符串; 读回只用于续跑合并, 不影响当轮报告。
            json.dump(payload, f, ensure_ascii=False, default=str)
        os.replace(tmp, path)
        return True, None
    except Exception as e:
        try:
            if os.path.exists(tmp):
                os.remove(tmp)
        except Exception:
            pass
        return False, "续跑点保存失败（%s）" % e


def _gui_resume_load():
    """读续跑点。返回 (payload, None) 或 (None, 说明文案)。

    - 文件不存在 → (None, None)   —— 没有续跑点, 不是错误
    - 文件损坏 / 结构非法 → (None, 提示文案) —— 当作没有续跑点, 不崩溃
    - 超过 7 天 → 删文件, (None, None)
    - 点里的项目**全测完了** → 删文件, (None, 说明文案) —— 没有可续的
      (spec F4「全都测完的轮次不写点」; 说明文案给「接着跑」入口用,
      让用户知道为什么续不了, 而不是看见一个死按钮)
    """
    path = _gui_resume_path()
    try:
        if not os.path.exists(path):
            return None, None
        if (time.time() - os.path.getmtime(path)) > _GUI_RESUME_MAX_AGE:
            try:
                os.remove(path)
            except Exception:
                pass
            return None, None
        with open(path, encoding="utf-8") as f:
            data = json.load(f)
    except Exception:
        return None, "续跑点读取失败, 已忽略"
    clean = _gui_resume_clean(data)
    if clean is None:
        return None, "续跑点内容无效, 已忽略"
    # v1.24.0 复核: 「全测完」的点没有可续的 —— 当作没有 (spec F4「全都测完
    # 的轮次不写点」)。顺手清掉这个垃圾文件, 免得主页横幅写成「上次诊断没跑完
    # · 实检 N/N 项」自相矛盾 (verify S4.5)。
    keys = clean.get("keys") or []
    done = clean.get("completed") or {}
    if keys and all(k in done for k in keys):
        # 删前复核: 读文件与删文件之间可能恰好有并发写入 (os.replace 是原子
        # 替换) —— 删的必须还是这个「全测完」的点, 免得把刚写好的新点删了。
        try:
            with open(path, encoding="utf-8") as f:
                again = _gui_resume_clean(json.load(f))
            akeys = (again or {}).get("keys") or []
            adone = (again or {}).get("completed") or {}
            if akeys and all(k in adone for k in akeys):
                os.remove(path)
        except Exception:
            pass
        return None, "上次的诊断已经全测完了，没有要接着跑的项目"
    return clean, None


def _gui_resume_discard():
    """删掉续跑点 (用户选「重新开始」/ 续跑跑完后调用)。返回是否删掉了。"""
    path = _gui_resume_path()
    try:
        if os.path.exists(path):
            os.remove(path)
            return True
    except Exception:
        pass
    return False


def _gui_resume_summary(point):
    """续跑点的展示摘要 (主页横幅用): 场景名 / 已完成项数 / 请求项数 / 时间。

    point 为 None → 返回 None (没有可续的轮次, 页面不显示横幅)。
    """
    if not isinstance(point, dict):
        return None
    keys = point.get("keys") or []
    done = point.get("completed") or {}
    ts = point.get("saved_at_ts") or 0
    try:
        ts = float(ts)
    except (TypeError, ValueError):
        ts = 0
    when = ""
    if ts > 0:
        try:
            when = datetime.fromtimestamp(ts).strftime("%m-%d %H:%M")
        except Exception:
            when = ""
    return {
        "profile": point.get("profile"),
        "label": point.get("label") or "",
        "done": len(done),
        "total": len(keys),
        "keys": list(keys),
        "when": when,
    }


def _gui_merge_runs(resume_ctx, new_run):
    """续跑合并: 上次已完成的项目 + 本轮新跑的项目 → 一份完整 run dict。

    - keys 取原始请求全集 (报告据此给没测的项留「未检测」占位);
    - results / status 取并集 (本轮新跑的覆盖同名 key);
    - evidence 走既有 _extract_evidence_map (过渡键 _evidence 在这里摘出);
    - duration_ms 为两段之和 (诚实反映总耗时)。
    """
    saved = (resume_ctx or {}).get("completed") or {}
    saved_results = {}
    saved_status = {}
    for k, item in saved.items():
        if not isinstance(item, dict):
            continue
        res = item.get("result")
        if isinstance(res, dict):
            saved_results[k] = res
            saved_status[k] = item.get("status")
    new_results = dict((new_run or {}).get("results") or {})
    new_status = dict((new_run or {}).get("status") or {})
    results = dict(saved_results)
    results.update(new_results)
    status = dict(saved_status)
    status.update(new_status)
    keys = list((resume_ctx or {}).get("keys") or [])
    if not keys:
        keys = list((new_run or {}).get("keys") or [])
    clean, evidence = _extract_evidence_map(results)
    merged = dict(new_run or {})
    merged["status"] = status
    merged["results"] = clean
    merged["evidence"] = evidence
    merged["keys"] = keys
    merged["duration_ms"] = (int((resume_ctx or {}).get("duration_ms") or 0)
                             + int((new_run or {}).get("duration_ms") or 0))
    merged["total_modules"] = int((new_run or {}).get("total_modules")
                                   or len(MODULE_MAP))
    return merged


def _gui_resume_note(resume_ctx):
    """续跑轮次的报告备注 (写进 report["note"], 空串不渲染)。

    复用上次的结果 = 数据来自两个时间点 —— 报告里必须写出来, 不隐瞒。
    """
    if not resume_ctx:
        return ""
    done = len((resume_ctx.get("completed") or {}))
    if not done:
        return ""
    when = ""
    ts = resume_ctx.get("saved_at_ts") or 0
    try:
        ts = float(ts)
    except (TypeError, ValueError):
        ts = 0
    if ts > 0:
        try:
            when = datetime.fromtimestamp(ts).strftime("%m-%d %H:%M")
        except Exception:
            when = ""
    if when:
        return ("本轮为续跑: 其中 %d 项的数据来自上一次运行 (%s)" % (done, when))
    return "本轮为续跑: 其中 %d 项的数据来自上一次运行" % done


class _GuiSession:
    """单轮诊断的线程安全状态快照 (GUI 进度通道唯一读写点)。

    phase: idle → running → done / error;  现场检测另有 site_ready
    (诊断完等机房勾选)。本类不读全局 LAST_RUN: run dict 来自
    run_diagnostics 返回值。

    v1.24.0 增补两个 phase: stopping (已请求停止, 等当前模块收尾) 与
    cancelled (已停止, 部分报告已出)。停止是**软取消** —— 不再启动新模块,
    手头那项跑完就收工 (模块内部没有中止开关, 硬杀会留下下载残留、污染
    后续测速)。两者都算「在跑」, 互斥不放宽。
    """

    def __init__(self):
        self._lock = threading.RLock()
        self._phase = "idle"
        self._profile = None
        self._keys = []
        self._module_status = {}
        self._running = set()
        self._started_at = None
        self._error = None
        self._report = None
        self._verdict = None
        self._run = None
        self._files = []
        self._site = None
        self._thread = None
        # ── v1.24.0 取消 / 续跑 ──
        self._cancel_evt = None       # 本轮取消闸 (threading.Event)
        self._stop_requested = False  # 用户点过「停止」
        self._partial = {}            # key -> {"status", "result"} 已完成项目
        self._resume_ctx = None       # 续跑上下文 (复用的结果 + 上次时间)
        self._label_suffix = ""       # 续跑轮次的标题后缀 「（续跑）」
        self._note = ""               # 报告级备注 (续跑说明)
        # v1.24.0: 续跑点落盘失败的提示文案 (spec 风险表: 落盘失败要提示,
        # 但不影响当轮报告与导出)。空串 = 没失败。
        self._resume_error = ""
        # 磁盘上是否真有可续的续跑点 (落盘成功 = True)。用来判「继续跑」入口
        # 给不给 —— 一项都没测完就停时没有点, 给个假入口点了只会报错。
        self._resume_saved = False

    # -- 进度回调 (诊断线程调用, 见 run_diagnostics progress_cb 契约) --
    def on_progress(self, ev):
        with self._lock:
            if ev.get("event") == "start":
                self._running.add(ev["key"])
            elif ev.get("event") == "done":
                self._running.discard(ev["key"])
                self._module_status[ev["key"]] = ev.get("status")
                # v1.24.0: 累积已完成项目的结果 —— 关窗落盘与续跑点都要用
                # (整轮结束时才有 run dict, 关窗那一刻拿不到)。
                res = ev.get("result")
                if isinstance(res, dict):
                    self._partial[ev["key"]] = {"status": ev.get("status"),
                                                "result": res}

    # -- 快照 (HTTP 线程调用; 返回可 JSON 化的 dict) --
    def snapshot(self):
        with self._lock:
            done = sum(1 for v in self._module_status.values() if v)
            remaining = len(self._keys) - done
            reused = len((self._resume_ctx or {}).get("completed") or {})
            return {
                "phase": self._phase,
                "profile": self._profile,
                # v1.23.0: keys 组合模式 (profile=None) label 由 keys 推导
                "label": (_GUI_LABELS(self._profile, self._keys)
                          if (self._profile or self._keys) else "") + self._label_suffix,
                "total": len(self._keys),
                "done": done,
                "running": sorted(self._running),
                "module_status": dict(self._module_status),
                "elapsed_ms": (int((time.time() - self._started_at) * 1000)
                               if self._started_at else 0),
                "error": self._error,
                "has_report": self._report is not None,
                # 终审 F2: 报告页结论条数据 (score/grade/label + 全口径计数),
                # _run_diag / finalize_site 在报告构建成功处透传, 见 _gui_verdict
                "verdict": self._verdict,
                "files": list(self._files),
                "site": dict(self._site) if self._site else None,
                # ── v1.24.0 取消 / 续跑 ──
                "can_stop": self._phase in ("running", "stopping"),
                "stop_requested": self._stop_requested,
                "cancelled": self._phase == "cancelled",
                "remaining": max(0, remaining),
                "reused": reused,
                # 能不能接着跑 —— 五个条件缺一不可 (终审审查 #3/#4):
                #   ① 本轮是「已停止」; ② 不是现场检测 (spec F6 不支持续跑);
                #   ③ 续跑点确实落盘成功 (失败/没东西可存 → 不能续);
                #   ④ 还有没测的项 (全测完了 → 「继续跑剩下的 0 项」是死入口);
                #   ⑤ 没落盘失败。
                "can_resume": (self._phase == "cancelled"
                               and self._profile != "site"
                               and not self._resume_error
                               and remaining > 0
                               and self._resume_saved),
                "resume_error": self._resume_error,
                "note": self._note,
            }

    def is_running(self):
        with self._lock:
            # stopping 也算在跑 —— 收尾期间互斥不能放开 (spec F1)
            return self._phase in ("running", "stopping")

    def report_html(self):
        """内嵌报告页 (客户版) 的完整 HTML; 无报告返回 None。"""
        with self._lock:
            if not self._report:
                return None
            report = self._report
        return render_report_html_customer(report)

    # -- 诊断编排 (与终端 _run_scene 同一管线) --
    def _begin(self, profile, keys, resume_ctx=None):
        # v1.22.0: 查忙 + 置 running 全程持 _GUI_ACT_LOCK — 三类活动
        # (诊断/现场检测/盯障) 的跨类型互斥铁律, 锁外查锁内置位就会
        # 双查双过。self._lock 是 RLock, _gui_net_busy 回查自身可重入。
        with _GUI_ACT_LOCK, self._lock:
            if self._phase in ("running", "stopping"):
                # v1.24.0: stopping 也要拒 —— 收尾期间不能开新一轮
                return False, "已有诊断在进行中"
            if _gui_net_busy():          # v1.22.0: 跨类型互斥 (盯障等)
                return False, _GUI_BUSY_MSG
            self._phase = "running"
            self._profile = profile
            self._keys = list(keys)
            self._module_status = {k: None for k in keys}
            self._running = set()
            self._started_at = time.time()
            self._error = None
            self._report = None
            self._verdict = None
            self._run = None
            self._files = []
            # ── v1.24.0: 本轮取消闸 / 续跑上下文 ──
            self._cancel_evt = threading.Event()
            self._stop_requested = False
            self._partial = {}
            self._resume_ctx = resume_ctx
            self._resume_error = ""
            self._resume_saved = False
            self._label_suffix = "（续跑）" if resume_ctx else ""
            if resume_ctx:
                # 续跑: 上次已测完的项目先把状态铺上 (网格里显示原状态色),
                # 本轮只跑剩下的那些。
                for k, item in (resume_ctx.get("completed") or {}).items():
                    if k in self._module_status:
                        self._module_status[k] = item.get("status")
        return True, None

    # -- 停止 (v1.24.0) --
    def stop(self):
        """请求停止本轮诊断 (幂等)。

        软取消: 不再启动新模块, 手头那项跑完就收尾 (模块内部无中止开关,
        硬杀会留下载残留、污染后续测速)。返回 True = 已受理。
        """
        with self._lock:
            if self._phase != "running":
                return False
            self._stop_requested = True
            self._phase = "stopping"
            evt = self._cancel_evt
        if evt is not None:
            evt.set()
        return True

    def start(self, profile=None, keys=None, install=True, pip_mirror=None):
        """启动场景诊断或完整诊断。full=full_module_keys() (含 tcpcc 压测)。

        v1.23.0 keys 形态: keys 优先于 profile; 白名单校验 (非空、⊆
        MODULE_REGISTRY 全集、去重保序) 失败返回 (False, err)。组合走
        既有 run_diagnostics 管线, label=「模块组合 (N 项)」; rule_filter
        天然为 None (组合不在 DIAGNOSE_PROFILES → 全规则评估)。
        """
        if keys is not None:
            keys, err = _gui_validate_keys(keys)
            if err:
                return False, err
            profile = None
        else:
            keys = _gui_profile_keys(profile)
            if keys is None:
                return False, "未知场景: %s" % profile
        ok, err = self._begin(profile, keys)
        if not ok:
            return False, err
        self._thread = threading.Thread(target=self._run_diag,
                                        args=(keys, install, pip_mirror),
                                        daemon=True, name="np-gui-diag")
        self._thread.start()
        return True, None

    def _run_diag(self, keys, install, pip_mirror, resume_ctx=None):
        try:
            run = run_diagnostics(keys, banner=False, parallel=True,
                                  max_workers=4, install=install,
                                  pip_mirror=pip_mirror, print_modules=False,
                                  progress_cb=self.on_progress,
                                  cancel_evt=self._cancel_evt)
            results = run.get("results") or {}
            with self._lock:
                stopped = self._stop_requested
            if not results:
                if stopped:
                    # 一项都没测完就停了 → 没有报告可出, 但已测完的(0 项)也
                    # 没有可留的。诚实报错, 不假装完成。
                    with self._lock:
                        self._phase = "cancelled"
                        self._error = "已停止, 还没测出任何结果"
                    return
                raise RuntimeError("诊断未产生数据")
            # 续跑: 上次已完成的项目 + 本轮新跑的项目 → 合并成一份完整数据
            if resume_ctx:
                run = _gui_merge_runs(resume_ctx, run)
                results = run.get("results") or {}
            # 决议 (Task 2 审查): module_status 以最终 run dict 为准 ——
            # done 事件里的 status 是 _normalize_module_statuses 归一化前的
            # 原值, 事件只负责过程进度; 最终状态以 run["status"] 为准
            # (加锁, 先于 phase 翻转)。
            # v1.24.0: 改成**合并**而非整体替换 —— 提前停止时未启动的模块要
            # 留在网格里 (显示为空心「未测」), 续跑时上次的已完成项也要留下。
            with self._lock:
                merged_status = {k: self._module_status.get(k)
                                 for k in self._keys}
                merged_status.update(run.get("status") or {})
                self._module_status = merged_status
            profile = self._profile
            rf = profile if profile in DIAGNOSE_PROFILES else None
            diagnosis = _enrich_diagnosis_evidence(
                diagnose(results, rule_filter=rf), results, run.get("evidence"))
            note = _gui_resume_note(resume_ctx)
            report = build_report(
                rule_filter=rf,
                diagnosis=diagnosis.to_dict() if diagnosis else None,
                run=run,
                note=note)
            with self._lock:
                self._run = run
                self._report = report
                self._verdict = _gui_verdict(report) if report else None
                self._note = note
                self._phase = ("cancelled" if stopped else "done") if report else "error"
                if not report:
                    self._error = "报告构建失败"
            if stopped:
                # 提前结束 → 把已测完的项目落盘 (关窗、退出都不丢, 见 spec F4)
                # v1.24.0 终审: 全部请求的模块都跑完了 (停止请求刚好落在最后
                # 一个模块之后) → **没有可续的**, 别写续跑点。否则主页横幅会写
                # 「上次诊断没跑完 · 实测 24/24 项」自相矛盾, 点「接着跑」也只会
                # 报「没有可接着跑的诊断」。
                ran = sum(1 for k in self._keys if self._module_status.get(k))
                if ran >= len(self._keys) and self._keys:
                    # v1.24.0 复核: 续跑轮次 → 来源点也全测完了 → 删掉 (没有可续
                    # 的了); 普通新一轮 → 磁盘上的旧点**保留** (spec F4「普通新
                    # 一轮跑完不删旧点」—— 删了等于把上一轮已测完的成果抹掉;
                    # 与关窗落盘那条路径保持一致, 别让同一情形两种结果)。
                    if resume_ctx:
                        _gui_resume_discard()
                else:
                    err = self._save_resume_point(run, resume_ctx)
                    with self._lock:
                        # 落盘失败要提示 (spec 风险表), 但**不影响**当轮报告与
                        # 导出 —— 报告已经建好, 这里只补一句说明。
                        self._resume_error = err or ""
            elif resume_ctx:
                # 续跑轮次正常跑完 → 清掉续跑点 (主页别再提示「上次没跑完」)。
                # 普通新轮次**不删**旧点 (spec 风险表: 开始新一轮不立即删除旧点,
                # 新一轮停止时才覆盖) —— 删了等于把上一轮已测完的成果抹掉。
                _gui_resume_discard()
        except Exception as e:
            with self._lock:
                self._phase = "error"
                self._error = "%s: %s" % (type(e).__name__, e)

    # -- 续跑 (v1.24.0) --
    def start_resume(self, install=True, pip_mirror=None):
        """从落盘的续跑点继续: 只跑没测过的模块, 测过的复用上次结果。

        返回 (ok, err)。没有续跑点 → (False, 提示文案)。
        """
        point, err = _gui_resume_load()
        if not point:
            return False, err or "没有可接着跑的诊断"
        keys = list(point.get("keys") or [])
        completed = point.get("completed") or {}
        remaining = [k for k in keys if k not in completed]
        profile = point.get("profile")
        if profile not in DIAGNOSE_PROFILES and profile != "full":
            profile = None
        if not remaining:
            # 全都测过了 (停止请求刚好落在最后一个模块之后, 或磁盘上的点已经
            # 跑完) → **不跑空轮次**: 空轮次会「诊断未产生数据」, 还会把这一
            # 轮已经出的报告弄丢 (_begin 会清 _report)。明确告诉用户「没得
            # 跑」, 别把人送进一个空进度页 (v1.24.0 复核)。
            with self._lock:
                has_report = self._report is not None
                self._phase = "done" if has_report else "idle"
                if not has_report:
                    self._error = "这一轮的项目已经全测完了, 不用接着跑"
            return False, "上次的诊断已经全测完了，没有要接着跑的项目"
        ok, err = self._begin(profile, keys, resume_ctx=point)
        if not ok:
            return False, err
        self._thread = threading.Thread(
            target=self._run_diag,
            args=(remaining, install, pip_mirror, point),
            daemon=True, name="np-gui-resume")
        self._thread.start()
        return True, None

    # -- 续跑点落盘 (v1.24.0) --
    def _save_resume_point(self, run, resume_ctx=None):
        """把本轮已测完的项目写进续跑点 (停止后 / 关窗时调用)。

        续跑轮次要把「上次已存的」与「这轮新测的」合并存 —— 否则第二次停止
        会把第一次的成果丢掉。返回错误文案 (None = 成功或没必要存)。
        """
        with self._lock:
            partial = dict(self._partial)
            profile = self._profile
            all_keys = list(self._keys)
        completed = {}
        prev = (resume_ctx or {}).get("completed") or {}
        for k, item in prev.items():
            if isinstance(item, dict) and isinstance(item.get("result"), dict):
                completed[k] = {"status": item.get("status"),
                                "result": item.get("result")}
        if not partial:
            # 这一轮没测出新的东西 → 不覆盖磁盘上的点 (上一轮的成果留着),
            # 但「能不能接着跑」取决于磁盘上是否真有可续的点 (上一轮留的点
            # 仍然可以接着跑 —— 终审审查 #4)。
            with self._lock:
                self._resume_saved = os.path.exists(_gui_resume_path())
            return None
        results = {k: v["result"] for k, v in partial.items()
                   if isinstance(v.get("result"), dict)}
        statuses = {k: v.get("status") for k, v in partial.items()}
        # 状态归一 (与报告层同一口径: 「未配置」类算「未检测」)
        statuses = _normalize_module_statuses(statuses, results)
        for k, res in results.items():
            completed[k] = {"status": statuses.get(k), "result": res}
        payload = {
            "schema": 1,
            "saved_at": datetime.now().isoformat(timespec="seconds"),
            "saved_at_ts": time.time(),
            "profile": profile,
            "label": _GUI_LABELS(profile, all_keys),
            "keys": all_keys,
            "completed": completed,
            "duration_ms": int((run or {}).get("duration_ms") or 0),
            "total_modules": int((run or {}).get("total_modules")
                                 or len(MODULE_MAP)),
        }
        ok, err = _gui_resume_save(payload)
        with self._lock:
            self._resume_saved = bool(ok)
        return None if ok else err

    def save_resume_point_now(self):
        """把当前已测完的项目落盘 (关窗时调用)。

        在跑的那一项算「没测完」—— 下次续跑时重跑它。诊断没在跑、或还没测出
        任何结果 → 不写 (没有可留的东西)。返回错误文案 (None = 成功)。
        """
        with self._lock:
            if self._phase not in ("running", "stopping"):
                return None
            if not self._partial:
                return None
            # v1.24.0 复核: 最后一个模块刚测完、报告还没建好时关窗 → 这一轮
            # 其实全测完了, 没有可续的 → 不写点 (spec F4「全都测完的轮次不写
            # 点」)。写了的话磁盘上会留下「全测完」的点, 主页横幅就变成
            # 「上次诊断没跑完 · 实检 N/N 项」自相矛盾 (verify S4.5)。
            ran = sum(1 for k in self._keys if self._module_status.get(k))
            all_done = bool(self._keys) and ran >= len(self._keys)
            resume_ctx = self._resume_ctx
            # 已耗时也写进续跑点 (终审审查 #12): 不然续跑合并后的总耗时
            # 少算这一段, 报告里「检测耗时」会偏小。
            elapsed = int((time.time() - self._started_at) * 1000) \
                if self._started_at else 0
        if all_done:
            # 续跑轮次: 来源点也全测完了 → 一并清掉 (没有可续的了);
            # 普通新一轮: 磁盘上的旧点**保留** (spec F4「普通新一轮跑完不删旧
            # 点」—— 删了等于把上一轮已测完的成果抹掉)。
            if resume_ctx:
                _gui_resume_discard()
            return None
        err = self._save_resume_point({"duration_ms": elapsed}, resume_ctx)
        with self._lock:
            self._resume_error = err or ""
        return err

    # -- 现场检测 (与终端 run_site_visit :23538 同口径) --
    def start_site(self, customer, tested_at=None, plan="",
                   install=True, pip_mirror=None):
        cust = str(customer or "").strip()
        if not cust:
            return False, "客户名称必填"
        keys = [k for k in all_module_keys() if k not in ("port", "iperf3")]
        ok, err = self._begin("site", keys)
        if not ok:
            return False, err
        with self._lock:
            ta = str(tested_at or "").strip()
            if not ta:
                # 决议: 页面 datetime-local 可能为空, 空值默认当前时间
                # (终端口径: 回车 = 默认当前)
                ta = datetime.now().strftime("%Y-%m-%d %H:%M")
            self._site = {"customer": cust,
                          "tested_at": ta,
                          "plan": str(plan or "").strip()}
        self._thread = threading.Thread(target=self._run_diag_site,
                                        args=(keys, install, pip_mirror),
                                        daemon=True, name="np-gui-site")
        self._thread.start()
        return True, None

    def _run_diag_site(self, keys, install, pip_mirror):
        try:
            run = run_diagnostics(keys, banner=False, parallel=True,
                                  max_workers=4, install=install,
                                  pip_mirror=pip_mirror, print_modules=False,
                                  progress_cb=self.on_progress,
                                  cancel_evt=self._cancel_evt)
            with self._lock:
                stopped = self._stop_requested
            if not (run.get("results") or {}):
                if stopped:
                    # v1.24.0: 停得太早 (一项都没测完) → 不是「诊断失败」,
                    # 是「用户叫停了」。诚实说清现场流程不支持续跑, 别把
                    # RuntimeError 抛给用户看 (同 _run_diag 的处理口径)。
                    with self._lock:
                        self._phase = "cancelled"
                        self._error = ("现场检测已停止, 现场流程不支持续跑, "
                                       "请重新检测")
                    return
                raise RuntimeError("诊断未产生数据")
            # 决议 (Task 2 审查, 同 _run_diag): module_status 以最终 run dict
            # 为准整体同步 — done 事件带归一化前原值 (site 集含 loopback,
            # 环回未跑时事件是「错误」, run["status"] 里才是「未检测」),
            # 事件只负责过程进度; 最终状态以 run["status"] 为准
            # (加锁, 先于 phase 翻转)。
            # v1.24.0: 合并而非替换 (提前停止时未启动的模块留在网格里)。
            with self._lock:
                merged_status = {k: self._module_status.get(k)
                                 for k in self._keys}
                merged_status.update(run.get("status") or {})
                self._module_status = merged_status
                self._run = run
                if stopped:
                    # v1.24.0 (spec F6): 现场检测可停止, 但**不支持续跑** ——
                    # 现场结论要一次跑完才成立。诚实说明, 不假装能接着跑。
                    self._phase = "cancelled"
                    self._error = "现场检测已停止, 现场流程不支持续跑, 请重新检测"
                else:
                    self._phase = "site_ready"     # 等机房勾选 (页面切核对步)
            if stopped:
                # spec F6: 停止后照样出部分报告 (可导出) —— 现场流程不比普通
                # 诊断差这一口。已经测出来的东西不该白扔, 报告里写明提前结束。
                try:
                    site_results = run.get("results") or {}
                    diagnosis = _enrich_diagnosis_evidence(
                        diagnose(site_results, rule_filter=None), site_results,
                        run.get("evidence"))
                    report = build_report(
                        diagnosis=diagnosis.to_dict() if diagnosis else None,
                        meta_manual=dict(self._site or {}) or None,
                        run=run,
                        note="现场检测已停止, 本轮提前结束 (只测了一部分)")
                    with self._lock:
                        self._report = report
                        self._verdict = (_gui_verdict(report)
                                         if report else None)
                except Exception:
                    # 部分报告出不来也不影响「已停止」这个事实 (页面照实说)
                    pass
        except Exception as e:
            with self._lock:
                self._phase = "error"
                self._error = "%s: %s" % (type(e).__name__, e)

    def finalize_site(self, checks, note=""):
        """机房勾选提交 → build_report(显式传参, 守收口规则) → 四件套。"""
        with self._lock:
            run, site = self._run, self._site
            ready = (self._phase == "site_ready")
        if not ready or not run:
            return False, "诊断未完成, 无法生成报告"
        report = build_report(
            site_check=dict(checks or {}),      # 白名单在 build_report 内
                                                # (_normalize_site_check)
            meta_manual={"customer": site["customer"],
                         "tested_at": site.get("tested_at") or "",
                         "plan": site.get("plan") or ""},
            site_note=str(note or "").strip())
        if not report:
            return False, "报告构建失败"
        base = _site_report_base(site["customer"])
        outs = [(base + ".html", "brief_v2"),
                (base + "_完整版.html", "full"),
                (base + ".json", None)]
        files, err_first = [], None
        for path, layout in outs:
            err = export_report(path, report=report, layout=layout)
            if err:
                err_first = err_first or err
            else:
                files.append(path)
        chrome = _find_pdf_browser()
        if chrome:
            err = _html_to_pdf(chrome, base + ".html", base + ".pdf")
            if err:
                err_first = err_first or ("PDF: " + err)
            else:
                files.insert(0, base + ".pdf")
        with self._lock:
            self._report = report
            self._files = files
            self._verdict = _gui_verdict(report)
            # 审查 I2: 一件都没成时回 site_ready — 勾选数据与诊断结果都在,
            # 用户可直接重试「生成报告」, 不被迫重跑 2-3 分钟诊断。
            self._phase = "done" if files else "site_ready"
        if files:
            return True, err_first        # err_first 非空 = 部分失败, 前端提示
        return False, err_first

    # -- 导出 (与终端 _export_scene_report 同目录同名规则) --
    def export(self, kind):
        with self._lock:
            report, profile, keys = self._report, self._profile, self._keys
            suffix = self._label_suffix
        if not report:
            return None, "尚无报告可导出"
        base_dir = _desktop_netpulse_dir() or _report_dir()
        # v1.23.0: keys 组合模式 → 标题「模块组合 (N 项)」 (文件名同源)
        # v1.24.0: 续跑轮次标题带「（续跑）」 (文件名同源 —— 报告里混了
        # 上一次的数据, 文件名要看得出来)
        title = _GUI_LABELS(profile, keys) + suffix
        ts = datetime.now().strftime("%Y-%m-%d_%H%M%S")
        if kind == "pdf":
            chrome = _find_pdf_browser()
            if not chrome:
                return None, "未检测到 Chrome/Edge, 无法自动出 PDF (可打开 HTML 后 Ctrl+P)"
            # PDF 走无头打印, 打印源需要一份落盘 HTML (仅此类型附带);
            # html/json 按扩展名直出, 互不搭车 (终审 #7)
            html_path = os.path.join(base_dir, "%s_%s.html" % (ts, title))
            err = export_report(html_path, report=report)
            if err:
                return None, err
            pdf_path = html_path[:-5] + ".pdf"
            err = _html_to_pdf(chrome, html_path, pdf_path)
            return (None, err) if err else (pdf_path, None)
        # 终审 #7: json 不再先落一份 HTML (原实现多产用户没要的文件) —
        # export_report 本身按扩展名路由, .json 直接出原始数据
        ext = ".html" if kind == "html" else ".json" if kind == "json" else None
        if not ext:
            return None, "未知导出类型: %s" % kind
        path = os.path.join(base_dir, "%s_%s%s" % (ts, title, ext))
        err = export_report(path, report=report)
        return (None, err) if err else (path, None)


# ────────────────────────────────────────────────────────────────────────────
# GUI 盯障会话 (v1.22.0): MonitorSession 只读复用, 终端管线零修改
# (收口规则: run_monitor_mode / MonitorSession 不动)。
# 互斥铁律: 诊断/现场检测/盯障三类活动的 start 路径必须在 _GUI_ACT_LOCK 内
# 完成「查忙 + 置 running」—— 锁外查、锁内置位时, 两个入口能同时过闸。
# ────────────────────────────────────────────────────────────────────────────

_GUI_ACT_LOCK = threading.Lock()

# v1.22.0 终审修复波: 跨类型忙拒绝的统一文案 (可识别标记)。/api/site/start
# 路由据此把「预检通过但 _begin 原子复查拒绝」的竞态窗口忙拒映射成 409
# (而非被统一错误通道映射成 400, 与真实输入错误不可区分)。
_GUI_BUSY_MSG = "已有网络活动在进行中"


def _gui_net_busy():
    """任一网络活动 (诊断/现场检测/盯障) 进行中。

    调用方自身的单类判重由各 start 入口先行 (running 状态先查先拒),
    这里只补「其他类型」; _GuiSession._lock 是 RLock, _begin 持锁回查
    自身 is_running 可重入, 不会死锁。
    """
    h = _GuiHandler
    s = h.session
    m = h.monitor
    if s is not None and s.is_running():
        return True
    if m is not None and m.is_running():
        return True
    return False


class _GuiMonitor:
    """盯障 GUI 会话: MonitorSession 只读复用 + 节流快照 + 编排线程。

    phase: idle → running → done / error
    编排 (daemon 线程): 等 duration 或停止事件 (1s 粒度) → session.stop()
    → build_result(early_terminated=停止请求) → save_monitor_report
    (返回 None = 落盘失败 → phase=error)。与终端 run_monitor_mode 主循环
    同序; 快照/曲线/事件预览是只读通道, 重算一律节流 (计数器随
    progress_payload["counters"] 可观测)。
    """

    MIN_DURATION_S = 30             # 时长钳位下限 (同 run_monitor_mode)
    MAX_DURATION_S = 86400          # 时长钳位上限 24h (同 run_monitor_mode)
    CURVE_WINDOW_S = 600            # 曲线/事件预览窗口 (最近 10 分钟)
    CURVE_MAX_POINTS = 200          # 每流降采样上限
    PROGRESS_MIN_INTERVAL_S = 2.0   # progress_payload 重算最小间隔
    CURVE_MIN_INTERVAL_S = 5.0      # curve_payload 重算最小间隔
    EVENT_MIN_INTERVAL_S = 5.0      # 事件预览重算最小间隔 (与曲线同档)

    def __init__(self):
        self._lock = threading.RLock()
        self._phase = "idle"
        self._duration = 0            # 钳位后的有效时长
        self._ext_target = None
        self._load = False
        self._started_at = None
        self._ended_at = None
        self._stop_requested = False
        self._early = False
        self._error = None
        self._paths = None            # {"html": ..., "json": ...}
        self._outcome = None          # v1.22.0: done 态结论块 (报告页数据源)
        self._session = None          # MonitorSession (复用, 零修改)
        self._stop_evt = threading.Event()
        self._thread = None
        # 节流时间戳 + 缓存 + 可观测计数器 (progress_payload["counters"] 下发)
        self._ts_prog = 0.0
        self._ts_curve = 0.0
        self._ts_evt = 0.0
        self._prog_cache = None
        self._curve_cache = None
        self._evt_cache = None
        self._counters = {"polls": 0, "progress_computes": 0,
                          "curve_computes": 0, "event_computes": 0}

    # -- 生命周期 --
    def start(self, duration_s, ext_target=None, load=False):
        """启动盯障。返回 (ok, err|None, effective_s)。

        全程持 _GUI_ACT_LOCK: 查忙 + 置 running 原子 (跨类型互斥铁律)。
        时长钳位 [30, 86400] (与终端同界); None 默认 600, 非法值报错,
        0 走下限 30。session.start() 按 truthiness 判 (同 run_monitor_mode),
        失败回滚 phase 并补一次 stop() 清孤儿 ping 进程。提交窗口内
        (置 running 到 _session 落定之间) 到达的 stop 不丢 —— 编排线程
        首个 wait 立即返回, 按提前结束收尾。
        """
        with _GUI_ACT_LOCK:
            if self.is_running():
                return False, "已有盯障在进行中", None
            if _gui_net_busy():
                return False, _GUI_BUSY_MSG, None
            try:
                effective = 600 if duration_s is None else int(duration_s)
                effective = max(self.MIN_DURATION_S,
                                min(self.MAX_DURATION_S, effective))
            except (TypeError, ValueError, OverflowError):
                # v1.22.0 (审查 Minor ③): int(∞) 抛 OverflowError, 与
                # 类型/取值错误同按「时长不合法」拒, 不炸穿调用方
                return False, "盯障时长不合法", None
            with self._lock:
                # v1.22.0 (审查 Minor ①): 窗口起点先清上一轮残留
                # (_stop_requested 编排完成后不清零, 不在这里清, 下一轮
                # 会被残留标志秒停); 此刻起到提交之间到达的 stop 由提交
                # 块甄别保留。
                self._stop_requested = False
                self._stop_evt.clear()
                self._phase = "running"     # 先置位 (互斥原子性), 失败回滚
            try:
                session = MonitorSession(effective, ext_target or None,
                                         load_url=(MonitorSession.MONITOR_LOAD_URL
                                                   if load else None))
                started = session.start()   # truthiness, 同 run_monitor_mode
            except Exception as e:
                # 构造/启动崩溃也要回滚: phase 卡死在 running 会永久挡住
                # 后续盯障 (编排线程尚不存在, 无人收尾翻态)
                with self._lock:
                    self._phase = "idle"
                return False, "盯障启动失败: %s: %s" % (type(e).__name__, e), None
            if not started:
                with self._lock:
                    self._phase = "idle"    # 回滚
                try:
                    session.stop()          # 孤儿 ping 清理 (同 run_monitor_mode)
                except Exception:
                    pass
                return False, "外网 ping 启动失败, 无法开始盯障", None
            with self._lock:
                pending_stop = self._stop_requested   # Minor ①: 窗口内到达?
                self._duration = effective
                self._ext_target = ext_target or None
                self._load = bool(load)
                self._started_at = time.time()
                self._ended_at = None
                self._early = False
                self._error = None
                self._paths = None
                self._session = session
                if not pending_stop:
                    # 常规开轮: 清残留; 若窗口内有 stop 到达则保留标志与
                    # 事件 —— 编排线程首个 wait 立即返回, 按用户提前结束
                    # 收尾, 不会把停止请求抹掉后跑满全程 (Minor ①)。
                    self._stop_requested = False
                    self._stop_evt.clear()
                self._ts_prog = self._ts_curve = self._ts_evt = 0.0
                self._prog_cache = self._curve_cache = self._evt_cache = None
                thread = threading.Thread(target=self._orchestrate,
                                          daemon=True, name="np-gui-monitor")
                self._thread = thread
            try:
                thread.start()
            except Exception as e:
                # v1.22.0 (审查 Minor ②): 编排线程起不来 (线程耗尽
                # RuntimeError 等) 也必须回滚 —— 否则 phase 永久卡
                # running 挡死后续盯障; 采集已在跑, 补 stop 清孤儿 ping
                # (与构造/启动失败同款)。
                with self._lock:
                    self._phase = "idle"
                try:
                    session.stop()
                except Exception:
                    pass
                return False, "盯障启动失败: %s: %s" % (type(e).__name__, e), None
            return True, None, effective

    def stop(self):
        """提前结束 (幂等): 置停止事件 + 直接停采集 — 编排线程 ≤1s 内
        感知收尾 (MonitorSession.stop 自身幂等)。非 running 忽略。"""
        with self._lock:
            if self._phase != "running":
                return
            self._stop_requested = True
            self._stop_evt.set()
            session = self._session
        if session is not None:
            try:
                session.stop()
            except Exception:
                pass

    def is_running(self):
        with self._lock:
            return self._phase == "running"

    # -- 编排 --
    def _orchestrate(self):
        """编排线程: 等 duration 或停止事件 (1s 粒度) → 收尾落盘。

        与终端 run_monitor_mode 收尾同序: stop → build_result →
        save_monitor_report; 落盘失败 (None) 或任何异常 → phase=error,
        error 文本进 snapshot 供前端展示。
        """
        try:
            with self._lock:
                session, planned = self._session, self._duration
            stop_evt = self._stop_evt
            waited = 0.0
            while waited < planned and not stop_evt.wait(1.0):
                waited += 1.0
            with self._lock:
                early = self._stop_requested
                self._early = early
            session.stop()
            res = session.build_result(early_terminated=early)
            paths = save_monitor_report(res)
            with self._lock:
                self._ended_at = time.time()
                if paths:
                    self._paths = {"html": paths[0], "json": paths[1]}
                    # v1.22.0 (Task 3): 结论三件套只在此暂存, 经
                    # progress_payload 在 done 态下发 (报告页结论条数据源;
                    # running 期不下发, 前端不得提前渲染结论)
                    self._outcome = {
                        "verdict": res.get("verdict"),
                        "conclusion": res.get("conclusion_text"),
                        "advice": res.get("advice")}
                    self._phase = "done"
                else:
                    self._phase = "error"
                    self._error = "盯障报告落盘失败"
        except Exception as e:
            with self._lock:
                self._ended_at = time.time()
                self._phase = "error"
                self._error = "%s: %s" % (type(e).__name__, e)

    # -- 只读快照 (HTTP 线程; 每次都便宜, 重算型载荷走独立节流通道) --
    def _elapsed_s(self):
        """已进行秒数 (完成/出错后冻结在结束时刻)。持有 _lock 调用。"""
        if not self._started_at:
            return 0
        return int((self._ended_at or time.time()) - self._started_at)

    def snapshot(self):
        """轮询快照: 只读字段, 无重算。键形与 _GuiSession.snapshot 对齐
        (site 恒 None; 无 verdict — 报告页数据走 /api/monitor/report 内嵌)。"""
        with self._lock:
            return {
                "phase": self._phase,
                "effective_s": self._duration,
                "elapsed_s": self._elapsed_s(),
                "stop_requested": self._stop_requested,
                "early": self._early,
                "has_report": self._paths is not None,
                "report_paths": dict(self._paths) if self._paths else None,
                "site": None,
                "error": self._error,
            }

    # -- 重算型载荷 (节流通道) --
    def progress_payload(self):
        """进度载荷 (页面 1s 轮询): ≥2s 节流重算; counters 每次都取现值
        (载荷主体命中缓存复用, 节流效果仍可观测)。"""
        with self._lock:
            self._counters["polls"] += 1
            now = time.time()
            if self._prog_cache is None \
                    or now - self._ts_prog >= self.PROGRESS_MIN_INTERVAL_S:
                self._ts_prog = now
                self._counters["progress_computes"] += 1
                self._prog_cache = self._compute_progress(now)
            out = dict(self._prog_cache)
            out["counters"] = dict(self._counters)
            return out

    def _compute_progress(self, now):
        """进度载荷重算 (持有 _lock): 10s 窗口连通计数 (与 progress_line
        同窗) + 全程丢包率 + 事件预览 (独立 ≥5s 节流)。session 缺席
        (未启动) 返回空壳。v1.22.0 附 targets/error 元信息; done 态附
        报告页结论块 (verdict/conclusion/advice/early/files)。"""
        payload = {
            "phase": self._phase,
            "elapsed_s": self._elapsed_s(),
            "duration_s": self._duration,
            "connect": {"gw": {"ok": 0, "loss10": 0},
                        "ext": {"ok": 0, "loss10": 0},
                        "dns_ok": None, "tcp_ok": None},
            "loss_pct": {"gw": None, "ext": None},
            "events_preview": {k: 0 for k in ("outage", "dns_fail",
                                              "jitter_burst", "latency_spike")},
            "load": self._load,
            "targets": {"gw": None,
                        "ext": self._ext_target or "223.5.5.5"},
            "error": self._error,
        }
        session = self._session
        if session is None:
            return payload
        # 网关 IP 由 MonitorSession.start 解析 (同模块私有态只读, 供实时页
        # 「网关 x.x.x.x · 外网 x.x.x.x」元信息行)。isinstance 守卫: 真实
        # 会话是 str|None; 测试替身 (Mock) 的动态属性不是 str → 下发 None,
        # 不污染 JSON 载荷。
        gw_ip = getattr(session, "_gw_ip", None)
        payload["targets"]["gw"] = gw_ip if isinstance(gw_ip, str) else None
        snap = session.snapshot()
        win0 = now - 10.0
        for key in ("gw", "ext"):
            stream = [s for s in snap["%s_stream" % key] if s[1] >= win0]
            payload["connect"][key] = {
                "ok": sum(1 for s in stream if s[0] == "ok"),
                "loss10": sum(1 for s in stream if s[0] == "loss")}
        payload["loss_pct"]["gw"] = self._loss_pct(snap["gw_stream"])
        payload["loss_pct"]["ext"] = self._loss_pct(snap["ext_stream"])
        if snap["dns"]:                    # 末样本判连通 (与 progress_line 同口径)
            payload["connect"]["dns_ok"] = snap["dns"][-1][1] is not None
        if snap["tcp"]:
            payload["connect"]["tcp_ok"] = snap["tcp"][-1][1] is not None
        payload["events_preview"] = self._compute_events(now, snap)
        if self._phase == "done" and self._outcome is not None:
            # v1.22.0 (Task 3): done 态结论块 — verdict 三件套 + 提前终止
            # 标 + 三件套文件名 (csv/json/html 同名同 stamp, 由 html 推导)
            payload["verdict"] = self._outcome.get("verdict")
            payload["conclusion"] = self._outcome.get("conclusion")
            payload["advice"] = self._outcome.get("advice")
            payload["early"] = self._early
            stem = os.path.splitext(os.path.basename(
                (self._paths or {}).get("html") or ""))[0]
            if stem:
                payload["files"] = [stem + ".csv", stem + ".json",
                                    stem + ".html"]
        return payload

    @staticmethod
    def _loss_pct(stream):
        """全程丢包率 (会话口径); 无样本返回 None (前端显示 —)。"""
        n = len(stream)
        if not n:
            return None
        return round(sum(1 for s in stream if s[0] == "loss") / n * 100, 1)

    def _compute_events(self, now, snap):
        """事件预览重算 (持有 _lock, ≥5s 节流): 流条目过滤到最近
        CURVE_WINDOW_S 喂 _detect_monitor_events (与落盘判定同一实现),
        按 type 计数; 异常吞掉置空 (预览失败不拖垮轮询, 全历史精确判定
        只在结束时 build_result 跑)。"""
        if self._evt_cache is not None \
                and now - self._ts_evt < self.EVENT_MIN_INTERVAL_S:
            return self._evt_cache
        self._ts_evt = now
        self._counters["event_computes"] += 1
        win0 = now - self.CURVE_WINDOW_S
        win_snap = {
            "gw_stream": [s for s in snap["gw_stream"] if s[1] >= win0],
            "ext_stream": [s for s in snap["ext_stream"] if s[1] >= win0],
            "tcp": [s for s in snap["tcp"] if s[0] >= win0],
            "dns": [s for s in snap["dns"] if s[0] >= win0],
        }
        counts = {k: 0 for k in ("outage", "dns_fail", "jitter_burst",
                                 "latency_spike")}
        try:
            for ev in _detect_monitor_events(win_snap, win0, now):
                t = ev.get("type")
                if t in counts:
                    counts[t] += 1
        except Exception:
            pass                    # 预览是辅助信息: 失败置空, 不逐级上报
        self._evt_cache = counts
        return counts

    def curve_payload(self):
        """延迟曲线载荷: ≥5s 节流; 窗口 600s; 每流 ≤200 点; 丢包点保留
        (ms=None, 前端画红点)。"""
        with self._lock:
            now = time.time()
            if self._curve_cache is None \
                    or now - self._ts_curve >= self.CURVE_MIN_INTERVAL_S:
                self._ts_curve = now
                self._counters["curve_computes"] += 1
                self._curve_cache = self._compute_curve(now)
            # v1.22.0 (审查 Minor ④): 返回副本 —— 消费方对载荷的改写
            # (append/换值) 不得污染节流缓存
            cache = self._curve_cache
            return {"window_s": cache["window_s"],
                    "gw": [list(pt) for pt in cache["gw"]],
                    "ext": [list(pt) for pt in cache["ext"]]}

    def _compute_curve(self, now):
        """曲线重算 (持有 _lock): 窗口过滤 + 桶降采样。"""
        out = {"window_s": self.CURVE_WINDOW_S, "gw": [], "ext": []}
        if self._session is None:
            return out
        snap = self._session.snapshot()
        win0 = now - self.CURVE_WINDOW_S
        for key in ("gw", "ext"):
            pts = [(s[1], s[2]) for s in snap["%s_stream" % key]
                   if s[1] >= win0]      # (t, ms); loss 本身 ms=None
            out[key] = self._downsample(pts, win0)
        return out

    def _downsample(self, pts, win0):
        """桶降采样 ≤CURVE_MAX_POINTS: 含丢包的桶保留首个丢包点
        (均值会抹平丢包信号), 纯 ok 桶取 ms 均值。"""
        n = len(pts)
        if n <= self.CURVE_MAX_POINTS:
            return [[round(t - win0, 1), v] for t, v in pts]
        bucket = -(-n // self.CURVE_MAX_POINTS)          # ceil 整除
        out = []
        for i in range(0, n, bucket):
            chunk = pts[i:i + bucket]
            loss = next((p for p in chunk if p[1] is None), None)
            if loss is not None:
                out.append([round(loss[0] - win0, 1), None])
            else:
                avg = sum(v for _, v in chunk) / len(chunk)
                out.append([round(chunk[0][0] - win0, 1), round(avg, 1)])
        return out

    # -- 报告 --
    def report_html(self):
        """内嵌报告页 (/api/monitor/report): 读落盘 HTML 的 bytes;
        无报告或文件不可读返回 None。"""
        with self._lock:
            paths = self._paths
        if not paths:
            return None
        try:
            with open(paths["html"], "rb") as f:
                return f.read()
        except OSError:
            return None


