def _gui_meta():
    """/api/scenarios 载荷 (状态色唯一来源 STATUS_COLORS; 文案同源终端菜单)。"""
    import socket as _s
    module_desc = {}
    try:
        for key, (name, _cls) in MODULE_MAP.items():
            module_desc[key] = name
    except Exception:
        pass
    return {
        "version": APP_VERSION,
        "hostname": _s.gethostname(),
        "full_count": len(full_module_keys()),
        "scenarios": (
            # id = profile id (页面 JS startRun(s.id) 直接 POST /api/run {profile});
            # SCENE_MENU_KEYS 的数字键只是终端菜单键位, 不下发 (brief 笔误修正)
            [{"id": p, "label": SCENE_LABELS[p],
              "desc": SCENE_MENU_DESC.get(p, ""),
              "modules": len(DIAGNOSE_PROFILES[p])}
             for k, p in SCENE_MENU_KEYS.items()]
            + [{"id": "site", "label": "现场检测",
                "desc": "客户信息 + 机房 6 项 → 一页报告/PDF", "modules": 0}]
            + [{"id": "monitor", "label": "持续盯障",
                "desc": "定时监测外网, 抓偶发掉线/抖动", "modules": 0}]
        ),
        "module_desc": module_desc,
        # v1.23.0: 模块勾选面板目录 (F4 红线: 数据唯一来源 MODULE_CATEGORIES
        # /MODULE_MAP, 页面不内嵌清单); cat 字母同源 MODULE_CATEGORY_LETTERS
        "module_catalog": [
            {"key": k, "name": MODULE_MAP[k][0],
             "cat": MODULE_CATEGORY_LETTERS[ci]}
            for ci, (_cname, ckeys, _cdesc) in enumerate(MODULE_CATEGORIES)
            for k in ckeys
        ],
        # v1.23.0 Task 2: 面板组头分类名+副题 ({"a":{"name","desc"}}),
        # 数据同源 MODULE_CATEGORIES 第 1/3 元组 —— Task 1 只发了目录三元组,
        # 组头文案此前无处可取, 页面不内嵌清单 (F4 红线同口径)
        "module_cats": {
            MODULE_CATEGORY_LETTERS[ci]: {"name": cname, "desc": cdesc}
            for ci, (cname, _ckeys, cdesc) in enumerate(MODULE_CATEGORIES)
        },
        "status_colors": {st: STATUS_COLORS[sk]
                          for st, sk in STATUS_KEY.items()},
        # 终审 F4: 报告页结论条等级徽章色, 同一载荷下发 (页面 JS 不内嵌色表)
        "grade_colors": dict(GRADE_COLORS),
        # v1.24.0: 主页续跑横幅数据 —— 有没有「上次没跑完」的轮次。
        # 点开页面读一次续跑点; 文件不存在/损坏都当没有 (不报错、不打断主页)。
        "resume": _gui_resume_summary(_gui_resume_load()[0]),
        "site_items": [{"key": it["key"], "cat": it["cat"],
                        "label": it["label"], "options": list(it["options"])}
                       for it in SITE_CHECK_ITEMS],
    }


class _GuiHandler(http.server.BaseHTTPRequestHandler):
    """GUI 请求处理器。session/token/shutdown_evt 由 _start_gui_server 注入。"""

    server_version = "NetPulseGUI/" + APP_VERSION
    session = None
    token = None
    shutdown_evt = None
    monitor = None    # v1.22.0: _GuiMonitor 实例 (_run_gui 注入, Task 2 路由消费)

    def log_message(self, fmt, *args):     # GUI 模式终端不刷 HTTP 日志
        pass

    # -- 鉴权与应答工具 --
    def _authorized(self):
        q = urllib_parse.urlparse(self.path)
        tok = (urllib_parse.parse_qs(q.query).get("t") or [None])[0]
        if not tok:
            tok = self.headers.get("X-NetPulse-Token")
        if not (isinstance(tok, str) and isinstance(self.token, str)):
            return False
        # I1 (审查): compare_digest 的 str 路径遇非 ASCII 字符抛 TypeError,
        # 被 do_GET/do_POST 外层 except 兜成 500 并泄漏内部报错文本。
        # 统一 encode 成 bytes 比较, 任何输入 (latin-1 header / %FF 查询串)
        # 都落回 403; tok 可能含不可编码的代理字符, 用 replace 兜底 ——
        # 不影响"相等才放行"语义 (真 token 是纯 ASCII urlsafe, 不会被替位)。
        return hmac.compare_digest(tok.encode("utf-8", "replace"),
                                   self.token.encode("utf-8"))

    def _send(self, code, body, ctype="application/json; charset=utf-8"):
        data = body if isinstance(body, bytes) else \
            json.dumps(body, ensure_ascii=False).encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", ctype)
        self.send_header("Content-Length", str(len(data)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        try:
            self.wfile.write(data)
        except Exception:
            pass

    def _reject(self):
        # v1.24.0: 先把请求体读掉再回 403 —— 不读就关连接, 客户端会收到
        # RST (Windows: WinError 10053 连接被中止), 表现为「请求失败」而不是
        # 「403 无权限」, 排查时分不清是权限问题还是网络问题。
        # 上限 64KB: 免得被超大 Content-Length 撑内存。
        try:
            n = int(self.headers.get("Content-Length") or 0)
            if 0 < n <= 65536:
                self.rfile.read(n)
        except Exception:
            pass
        self._send(403, {"error": "forbidden"})

    def _body(self):
        n = int(self.headers.get("Content-Length") or 0)
        raw = self.rfile.read(n) if n else b""
        if not raw:
            return {}
        try:
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return None

    def _path(self):
        return urllib_parse.urlparse(self.path).path

    # -- 路由 --
    def do_GET(self):
        try:
            if not self._authorized():
                return self._reject()
            p = self._path()
            if p in ("/", "/index.html"):
                # 用预渲染常量 (Task 3 注: 避免每请求重建), 内容与 _gui_page() 一致
                return self._send(200, _GUI_PAGE_HTML.encode("utf-8"),
                                  "text/html; charset=utf-8")
            if p == "/api/scenarios":
                return self._send(200, _gui_meta())
            if p == "/api/progress":
                return self._send(200, self.session.snapshot())
            if p == "/api/netstatus":
                # 顶栏联网状态数据源 (探测线程写, 锁内读)
                with _GUI_NET_LOCK:
                    ok = _GUI_NET["ok"]
                return self._send(200, {"ok": ok})
            if p == "/api/report":
                html = self.session.report_html()
                if not html:
                    return self._send(404, {"error": "尚无报告"})
                return self._send(200, html.encode("utf-8"),
                                  "text/html; charset=utf-8")
            if p == "/api/monitor/progress":
                # v1.22.0: 盯障实时页轮询通道 (服务端 ≥2s 节流, 载荷含 counters)
                return self._send(200, self.monitor.progress_payload())
            if p == "/api/monitor/curve":
                # 延迟双曲线 (服务端 ≥5s 节流, 窗口 600s, 丢包点 ms=None)
                return self._send(200, self.monitor.curve_payload())
            if p == "/api/monitor/report":
                # 盯障报告内嵌 (编排落盘后可读); report_html 已返回 bytes
                html = self.monitor.report_html()
                if not html:
                    return self._send(404, {"error": "尚无报告"})
                return self._send(200, html, "text/html; charset=utf-8")
            return self._send(404, {"error": "not found"})
        except Exception as e:
            try:
                return self._send(500, {"error": str(e)})
            except Exception:
                pass

    def do_POST(self):
        try:
            if not self._authorized():
                return self._reject()
            p, data = self._path(), self._body()
            if data is None:
                return self._send(400, {"error": "bad json"})
            if p == "/api/run":
                # v1.23.0 双形态: {profile} / {keys:[...]}, 二选一同现 400。
                # keys 路径: 服务端白名单校验 (非法 → 400) + 每轮配置注入;
                # profile 路径同样走注入段 (字段缺失按重置默认 — 场景卡
                # 请求不带字段, 面板上轮注入不跨轮残留, v1.23.0 终审修复
                # 波); 未知场景不碰配置仍由 start() 回 400。忙 409 分诊
                # 沿用, 原子闸仍在 _begin (_GUI_ACT_LOCK 内查忙+置位)。
                d = data or {}
                req_keys = d.get("keys")
                req_profile = d.get("profile")
                if req_keys is not None and req_profile is not None:
                    return self._send(400, {"ok": False,
                                            "err": "keys 与 profile 只能二选一"})
                if self.session.is_running():
                    return self._send(409, {"ok": False, "reason": "running"})
                if self.monitor is not None and self.monitor.is_running():
                    # v1.22.0: 盯障进行中, 诊断入口同样 409 (互斥第二道
                    # 防线在 _begin: _GUI_ACT_LOCK 内原子复查)
                    return self._send(409, {"ok": False, "reason": "busy"})
                if req_keys is not None:
                    keys, err = _gui_validate_keys(req_keys)
                    if err:
                        return self._send(400, {"ok": False, "err": err})
                    # 注入先于 start: 诊断线程起跑即读 CONFIG, 不能竞速
                    err = _gui_apply_run_config(d, keys)
                    if err:
                        return self._send(400, {"ok": False, "err": err})
                    ok, err = self.session.start(keys=keys)
                else:
                    profile = str(req_profile or "")
                    keys = _gui_profile_keys(profile)
                    if keys is not None:
                        err = _gui_apply_run_config(d, keys)
                        if err:
                            return self._send(400, {"ok": False, "err": err})
                    ok, err = self.session.start(profile)
                return self._send(200 if ok else 400,
                                  {"ok": ok, "err": err})
            if p == "/api/run/stop":
                # v1.24.0: 请求停止本轮诊断 (软取消 —— 不再启动新模块, 手头
                # 那项跑完就收尾)。幂等口径: 在跑/已在收尾 → 200; 没在跑 → 400。
                snap = self.session.snapshot()
                if not snap.get("can_stop"):
                    return self._send(400,
                                      {"ok": False, "err": "当前没有进行中的诊断"})
                if snap.get("stop_requested"):
                    return self._send(200, {"ok": True})   # 已在收尾, 幂等
                ok = self.session.stop()
                return self._send(200 if ok else 400,
                                  {"ok": ok,
                                   "err": None if ok else "停止失败"})
            if p == "/api/run/resume":
                # v1.24.0: 从落盘的续跑点接着跑 (只跑没测过的那几项)。
                ok, err = self.session.start_resume()
                return self._send(200 if ok else 400, {"ok": ok, "err": err})
            if p == "/api/resume/discard":
                # v1.24.0: 丢弃续跑点 (主页横幅的「重新开始」)
                _gui_resume_discard()
                return self._send(200, {"ok": True})
            if p == "/api/export":
                kind = str((data or {}).get("kind") or "")
                path, err = self.session.export(kind)
                return self._send(200 if path else 400,
                                  {"path": path, "err": err})
            if p == "/api/open-folder":
                try:
                    os.startfile(_desktop_netpulse_dir() or _report_dir())
                    return self._send(200, {"ok": True})
                except Exception as e:
                    return self._send(400, {"ok": False, "err": str(e)})
            if p == "/api/shutdown":
                # v1.22.0 (Task 3): 盯障 running 纳入拦截口径 — 非 force
                # 409 (防丢当轮报告/孤儿 ping); force 放行, 放行前尽力
                # monitor.stop()。诊断 running 的既有口径不变。
                force = bool((data or {}).get("force"))
                mon_busy = (self.monitor is not None
                            and self.monitor.is_running())
                if ((not self.session.is_running() and not mon_busy)
                        or force):
                    if force and mon_busy:
                        try:
                            self.monitor.stop()
                        except Exception:
                            pass
                    # v1.24.0: 诊断在跑时关窗 → 先把已测完的项目落盘
                    # (在跑的那项算没测完, 下次重跑), 别让成果白费。
                    try:
                        self.session.save_resume_point_now()
                    except Exception:
                        pass
                    self.shutdown_evt.set()
                    return self._send(200, {"ok": True})
                return self._send(409, {"ok": False, "reason": "running"})
            if p == "/api/site/start":
                d = data or {}
                # v1.22.0 终审 #2: 忙类拒绝 409 (原被统一映射 400, 前端
                # 无法与输入错误区分); 真实输入错误 (客户名空) 维持 400。
                # 判据一: 路由先查 _gui_net_busy 分诊; 判据二: 预检与
                # _begin 原子复查之间被抢跑时, 按忙错误标记兜底识别。
                if _gui_net_busy():
                    return self._send(409, {"ok": False, "reason": "busy"})
                ok, err = self.session.start_site(
                    d.get("customer"), tested_at=d.get("tested_at"),
                    plan=d.get("plan"))
                if not ok and err == _GUI_BUSY_MSG:
                    return self._send(409, {"ok": False, "reason": "busy"})
                return self._send(200 if ok else 400, {"ok": ok, "err": err})
            if p == "/api/site/finish":
                d = data or {}
                ok, err = self.session.finalize_site(
                    d.get("checks") or {}, note=d.get("note") or "")
                return self._send(200 if ok else 400, {"ok": ok, "err": err})
            if p == "/api/monitor/start":
                # v1.22.0: 忙检放 _GUI_ACT_LOCK 内, 只做 409/400 状态码
                # 分诊; 真正的「查忙+置位」原子闸在 monitor.start() 内
                # (自持同锁复查 — 锁不可重入, 路由层不能持锁调它)。
                # minutes×60 秒 (与终端菜单同语义), 缺省 600s = 10 分钟。
                d = data or {}
                try:
                    minutes = d.get("minutes")
                    duration_s = 600 if minutes is None else int(minutes) * 60
                except (TypeError, ValueError, OverflowError):
                    return self._send(400,
                                      {"ok": False, "err": "盯障时长不合法"})
                with _GUI_ACT_LOCK:
                    busy = _gui_net_busy()
                if busy:
                    return self._send(409, {"ok": False, "reason": "busy"})
                ok, err, eff = self.monitor.start(
                    duration_s, ext_target=d.get("target") or None,
                    load=bool(d.get("load")))
                if ok:
                    return self._send(200, {"ok": True, "effective_s": eff})
                if _gui_net_busy():
                    # 查忙与 start 之间被其他活动抢跑: start 的原子复查
                    # 已拒 → 按忙回 409 而非 400
                    return self._send(409, {"ok": False, "reason": "busy"})
                return self._send(400, {"ok": False, "err": err})
            if p == "/api/monitor/stop":
                # 幂等口径: running (含已请求停止、编排收尾中) → 200;
                # 已结束/未开始 → 400。_GuiMonitor.stop 自身幂等。
                if not self.monitor.is_running():
                    return self._send(400,
                                      {"ok": False, "err": "当前没有进行中的盯障"})
                self.monitor.stop()
                return self._send(200, {"ok": True})
            return self._send(404, {"error": "not found"})
        except Exception as e:
            try:
                return self._send(500, {"error": str(e)})
            except Exception:
                pass


def _start_gui_server(session=None, shutdown_evt=None, monitor=None):
    """起本地 GUI 服务: 仅绑 127.0.0.1 随机端口, 返回 (server, port, token)。

    monitor 缺省自建 (v1.22.0): 与 session 同款注入 _GuiHandler 类属性,
    /api/monitor/* 路由由此可达。
    """
    import secrets
    session = session if session is not None else _GuiSession()
    shutdown_evt = shutdown_evt if shutdown_evt is not None else threading.Event()
    monitor = monitor if monitor is not None else _GuiMonitor()
    token = secrets.token_urlsafe(24)
    srv = http.server.ThreadingHTTPServer(("127.0.0.1", 0), _GuiHandler)
    srv.daemon_threads = True
    _GuiHandler.session = session
    _GuiHandler.token = token
    _GuiHandler.shutdown_evt = shutdown_evt
    _GuiHandler.monitor = monitor
    threading.Thread(target=srv.serve_forever, kwargs={"poll_interval": 0.2},
                     daemon=True, name="np-gui-http").start()
    return srv, srv.server_address[1], token


def _gui_console_process_count():
    """当前控制台挂着的进程数 (双击 exe = 1; 从终端启动 = ≥2)。非 Windows 返回 0。"""
    if sys.platform != "win32":
        return 0
    try:
        import ctypes
        arr = (ctypes.c_ulong * 1)()
        n = ctypes.windll.kernel32.GetConsoleProcessList(arr, 1)
        return int(n or 0)
    except Exception:
        return 0


def _console_is_exclusive():
    """控制台是否被本进程独占 (只有独占才允许隐藏宿主窗口, 不藏用户终端)。"""
    return _gui_console_process_count() == 1


def _console_hide():
    if not _console_is_exclusive():
        return
    try:
        import ctypes
        hwnd = ctypes.windll.kernel32.GetConsoleWindow()
        if hwnd:
            ctypes.windll.user32.ShowWindow(hwnd, 0)   # SW_HIDE
    except Exception:
        pass


def _gui_launch_browser(url):
    """三级降级拉起界面: Chromium --app → 默认浏览器 → "none" (终端打印 URL)。"""
    browser = None
    try:
        browser = _find_pdf_browser()
    except Exception:
        browser = None
    if browser:
        try:
            proc = subprocess.Popen([browser, "--app=" + url,
                                     "--window-size=1280,860"])
            _GUI_BROWSER_PROC.append(proc)      # 保留句柄防 GC
            return "app"
        except OSError:
            pass
    try:
        if webbrowser.open(url):
            return "tab"
    except Exception:
        pass
    return "none"


def _run_gui(install=True, pip_mirror=None, shutdown_evt=None):
    """GUI 主入口 (v1.21.0): 起服务 → 拉起窗口 → 等退出事件。

    install 默认 True: GUI 无人值守, 依赖预检 (scapy/Npcap) 不能弹 input()
    问询 —— 会话卡死在隐藏控制台里没人能答。
    """
    session = _GuiSession()
    monitor = _GuiMonitor()     # v1.22.0: 盯障会话随 GUI 生命周期创建
    shutdown_evt = shutdown_evt if shutdown_evt is not None else threading.Event()
    try:
        srv, port, token = _start_gui_server(session, shutdown_evt, monitor)
    except OSError as e:
        print(_c("  ✗ 图形界面服务启动失败 (%s)。" % e, C_RED))
        return
    # 顶栏联网状态探测线程 (v1.21.0 收尾): 随退出事件自然停止
    threading.Thread(target=_gui_net_watch, args=(shutdown_evt,),
                     daemon=True, name="np-gui-net").start()
    url = "http://127.0.0.1:%d/?t=%s" % (port, token)
    how = _gui_launch_browser(url)
    if how == "none":
        print(_c("  未检测到可用浏览器。请在任意浏览器打开以下地址使用图形界面:",
                 C_YELLOW))
        print(_c("  " + url, C_WHITE))
        print(_c("  (完成诊断后可关闭本窗口; Ctrl+C 退出)", C_GRAY))
    else:
        _console_hide()      # app/tab 成功 → 双击场景隐藏宿主黑框
    try:
        while not shutdown_evt.is_set():
            shutdown_evt.wait(1.0)
    except KeyboardInterrupt:
        pass
    finally:
        try:
            monitor.stop()      # v1.22.0: 先停盯障 (清孤儿 ping -t) 再关服务
        except Exception:
            pass
        try:
            srv.shutdown()
            srv.server_close()
        except Exception:
            pass


def _gui_wanted(args, is_tty):
    """无顶层模式时是否进 GUI (纯函数, 便于测试)。

    --gui 显式进; --cli 显式不进; --json 不进 (stdout 必须是纯 JSON 的
    契约, v1.15.0); 其余看是否交互终端 —— 非 TTY (管道/计划任务) 维持
    旧菜单路径, 行为不变。
    """
    if getattr(args, "cli", False):
        return False
    if getattr(args, "json", False):
        return False
    return bool(getattr(args, "gui", False)) or bool(is_tty)


def main():
    parser = argparse.ArgumentParser(
        prog="netpulse.py",
        description=f"{APP_NAME} v{APP_VERSION} — Windows 网络诊断工具 (命令行)")
    parser.add_argument("modules", nargs="*",
                        help="要运行的模块 key 或序号 (默认进入交互菜单); 用 --list 查看")
    parser.add_argument("--list", action="store_true",
                        help="列出所有可用诊断模块后退出")
    parser.add_argument("--json", action="store_true",
                        help="以 JSON 格式输出每个模块的完整结果")
    parser.add_argument("--verbose", action="store_true",
                        help="完整输出, 不截断长字段")
    parser.add_argument("--no-color", action="store_true",
                        help="禁用彩色输出 (兼容老旧终端)")
    parser.add_argument("--no-update-check", action="store_true",
                        help="跳过启动时的自动检查更新 (v1.12.0; 检查本身"
                             "为后台静默, 失败无感知)")
    parser.add_argument("--log-report", choices=["on", "off", "check"],
                        default=None,
                        help="异常自动上报开关 (v1.17.0): on=开启, off=关闭。"
                             "默认开启, 首次运行弹窗征询; 交互菜单按 [C] 随时切换。"
                             "off 等价于设 NETPULSE_LOG_REPORT=0。"
                             "check=自检 (v1.18.0): 现场验证本机能否成功上报, "
                             "不跑诊断")
    parser.add_argument("--diagnose", metavar="PROFILE",
                        choices=sorted(list(DIAGNOSE_PROFILES.keys())),
                        help="按场景 Profile 诊断 (阶段 C · v1.3.0 引入). "
                             "可选: slow / disconnect / web / gaming / wifi. "
                             "诊断完成后输出根因分析 (置信度 + 建议). "
                             "也支持子命令形式: netpulse diagnose <profile>. "
                             "例: netpulse.py --diagnose slow")
    parser.add_argument("--json-schema", action="store_true",
                        help="输出当前 JSON Schema 版本号与结构路径 (阶段 D · v1.4.0 引入). "
                             "供 AI Agent / RMM / 飞书 bot introspect 用, "
                             "无需跑诊断即可查询 schema_version 与字段定义文件位置.")
    parser.add_argument("--debug-bundle", metavar="DIR",
                        help="生成调试包 (阶段 D · v1.4.0 引入). "
                             "zip 含 system.json + diagnostic.json + evidence.json + netpulse.log, "
                             "默认脱敏 (SSID / MAC / 公网 IP / hostname). "
                             "用于上报 bug 或远端排障. 例: --debug-bundle ./out")
    parser.add_argument("--install", action="store_true",
                        help="自动安装缺失依赖 (scapy/Npcap), 无需交互确认")
    parser.add_argument("--install-npcap", action="store_true",
                        help="仅安装 Npcap 抓包驱动后进入菜单 (v1.9.7 PR-3; "
                             "自提权重启的落点 — 需管理员权限, 普通权限下仅提示)")
    parser.add_argument("--no-scapy", action="store_true",
                        help="禁用 scapy 二层抓包 (部分机器 Npcap 不稳定会崩溃), "
                             "DHCP 检测降级为仅读取当前 DHCP 服务器")
    parser.add_argument("--port-target", action="append", metavar="HOST:PORT",
                        help="端口探测目标, 格式 host:port (如 223.5.5.5:53) 或 "
                             "host:port1-port2 范围 (如 10.0.0.1:1-1024) 或 "
                             "host:port,port (如 8.8.8.8:80,443,8000-8100); "
                             "可多次指定或用逗号分隔, 例: --port-target 223.5.5.5:53,10.0.0.1:1-1024")
    parser.add_argument("--port-proto", choices=["tcp", "udp", "both"], default="tcp",
                        help="端口探测协议 (默认 tcp); both = TCP 与 UDP 均测")
    parser.add_argument("--port-count", type=int, default=2, metavar="N",
                        help="每个目标采样次数 (默认 2; 越大越可靠但越慢, 1=快速, 10=高可靠)")
    parser.add_argument("--port-force", action="store_true",
                        help="强制执行端口探测, 即使目标数超过 1000 上限 "
                             "(默认拦下, 避免无意探测风暴/DoS)")
    parser.add_argument("--port-timeout", type=float, default=60.0, metavar="SEC",
                        help="端口探测总时长上限 (秒, 默认 60, 设 0 = 不限)。"
                             "超过则跳过剩余 spec, 报告里 timed_out_specs 字段列出")
    parser.add_argument("--port-concurrency", type=int, default=8, metavar="N",
                        help="端口探测内部并发度 (默认 8, 1=串行, 上限 64)。"
                             "并发下 60s 内能扫 20-50 个端口, 串行只扫 4-5 个")
    parser.add_argument("--export", metavar="FILE",
                        help="诊断后将报告导出到文件 (支持 .html / .json); "
                             "多个目标用逗号分隔可一次导出多种格式, 例: report.html,report.json")
    parser.add_argument("--parallel", action="store_true",
                        help="多模块并发执行 (典型场景: `all` 时速度提升 2-3x; "
                             "输出经线程锁同步, 详细结果仍按 keys 顺序排列)")
    parser.add_argument("--max-workers", type=int, default=4, metavar="N",
                        help="并行模式下的最大并发数 (--parallel 时生效, 默认 4)")
    parser.add_argument("--pip-mirror", metavar="URL",
                        help="pip 镜像 URL, 显式覆盖自动选源。"
                             "例: --pip-mirror https://pypi.tuna.tsinghua.edu.cn/simple")
    parser.add_argument("--iperf3-server", metavar="HOST[:PORT]",
                        help="iperf3 服务器地址: 提供后 iperf3 模块测到该服务器的上下行吞吐"
                             "(iperf3.exe 缺失时会交互式询问自动下载)。这是独立模块, "
                             "与互联网宽带测速 (speedtest) 分开, 测的是链路吞吐而非宽带。"
                             "例: 192.168.1.10 或 192.168.1.10:5201")
    parser.add_argument("--iperf3-duration", type=int, default=10, metavar="SEC",
                        help="iperf3 单方向测速时长 (秒, 默认 10)")
    parser.add_argument("--iperf3-udp", action="store_true",
                        help="iperf3 改用 UDP 模式测抖动/丢包 (1 Mbps 发包率, 语音/游戏"
                             "质量口径): 抖动 >30ms 或丢包 >1%% 给出告警; 默认 TCP 测吞吐")
    parser.add_argument("--speedtest-net", action="store_true",
                        help="启用 Ookla Speedtest 官方测速 (CLI 默认关闭; "
                             "交互菜单默认启用, 上海电信节点 3633)。"
                             "用 --speedtest-node <ID> 可指定其他服务器")
    parser.add_argument("--speedtest-node", metavar="ID|HOST:PORT",
                        help="指定测速服务器 (可选): 数字 ID = Ookla 服务器 ID "
                             "(覆盖默认 3633 上海电信, 如 5396 北京联通); "
                             "host:port = 国内上行节点 (如 112.25.80.50:8080); "
                             "默认自动选择国内运营商节点")
    parser.add_argument("--nattype-server", action="append", metavar="HOST[:PORT]",
                        help="NAT 类型检测的 STUN 服务器 (可选, 可指定两次提供两台, "
                             "缺省端口 3478); 默认用内置国内服务器自动回退")
    parser.add_argument("--web-target", action="append", metavar="URL",
                        help="网页体检追加目标 (可选, 追加到默认 3 个国内大站后, "
                             "总数上限 8), 例: --web-target https://example.com")
    parser.add_argument("--tcpcc-target", metavar="HOST:PORT",
                        help="TCP 并发测试的自定义目标 (可选, 如自建服务器/内网设备); "
                             "默认自动预检公网 anycast DNS 的 TCP 53 端点, 通过的"
                             "全部入池轮转压测 (防单 IP 被限流/拉黑)")
    parser.add_argument("--tcpcc-max", type=int, default=4000, metavar="N",
                        help="TCP 并发阶梯上限 (默认 4000, 硬上限 8000)。高上限会短时"
                             "建立大量连接, 勿短时间重复运行; 并行模式下建议单跑本模块")
    parser.add_argument("--loopback-scope", choices=["access", "unknown"],
                        default="unknown",
                        help="环回测速的对端类型声明: access = 确认默认网关在运营商"
                             "接入侧 (可与签约带宽对照判达标), unknown = 类型未知"
                             "(家用路由器等, 只报数不判达标)。默认 unknown —— "
                             "自动判定 (PPPoE 拨号会话) 失败时不猜。")
    parser.add_argument("--loopback-duration", type=int, default=5, metavar="SEC",
                        help="环回测速采样时长 (秒, 默认 5, 范围 3-30)")
    parser.add_argument("--monitor", metavar="SEC", type=int, nargs="?", const=600,
                        help="盯障模式: 持续监测 SEC 秒找偶发掉线, 结束生成 CSV/HTML/JSON "
                             "报告 (不带值 = 600 秒; 范围 30-86400; Ctrl+C 提前结束同样"
                             "生成报告); 与其他模块互斥, 指定时忽略 modules 与 --export")
    parser.add_argument("--monitor-target", metavar="HOST",
                        help="盯障外网 ping 目标 (默认 223.5.5.5, 同时对该目标 TCP 53 "
                             "建连; 可用域名)")
    parser.add_argument("--monitor-load", action="store_true",
                        help="盯障期间生成 15s 主动下载负载 (制造 full-size 包让 TCP "
                             "重传统计有分母; 流式读即丢弃, 不落盘)")
    parser.add_argument("--load-url", metavar="URL",
                        help="主动负载的下载地址 (默认微信安装包 CDN 大文件, "
                             "配合 --monitor-load 使用)")
    parser.add_argument("--site", action="store_true",
                        help="现场检测模式 (v1.13.0): 上门全量诊断(排除压测) + "
                             "机房 6 项逐项勾选 + 现场备注, 自动生成 一页客户报告/"
                             "完整版/JSON, 检测到 Chrome/Edge 自动加出 "
                             "PDF; 需交互终端, 与其他模块互斥")
    parser.add_argument("--customer", metavar="NAME",
                        help="现场检测模式的客户名称预填 (配合 --site; 不填则终端询问)")
    parser.add_argument("--gui", action="store_true",
                        help="进入图形界面窗口 (v1.21.0); 无参数启动且为交互终端时"
                             "已是默认, 本参数用于显式指定")
    parser.add_argument("--cli", action="store_true",
                        help="跳过图形界面, 直接进入传统终端菜单 (v1.21.0)")
    parser.add_argument("--capture", nargs="?", const="slice",
                        choices=["slice", "full"], default=None, metavar="MODE",
                        help="盯障期间抓包取证 (需 Npcap + 管理员; 默认关闭): "
                             "slice=事件触发落盘前后 30s 切片, full=全程落一个 "
                             f"pcap。仅保留包头 + HTTPS({'/'.join(str(p) for p in CAPTURE_PAYLOAD_PORTS)}) "
                             f"每流首 {CAPTURE_FIRST_PKTS} 包 {CAPTURE_PAYLOAD_KEEP}B 加密握手 (提 "
                             f"SNI), 明文 HTTP({'/'.join(str(p) for p in CAPTURE_WEB_PORTS if p not in CAPTURE_PAYLOAD_PORTS)}) "
                             "不存应用内容 (账号/密码/Cookie 不落盘); 配合 --monitor 使用")
    parser.add_argument("--capture-mb", type=int, default=CAPTURE_DEFAULT_MB,
                        metavar="N",
                        help=f"抓包缓冲上限 MB (默认 {CAPTURE_DEFAULT_MB}, 最小 8); "
                             "超限挤掉最旧包并如实报告; 配合 --capture 使用")
    args = parser.parse_args()

    if args.gui and args.cli:
        print(_c("  错误: --gui 与 --cli 不能同时使用", C_RED))
        sys.exit(4)

    # v1.15.0 (审查 P2): 抓包切片的保留期清理在**每次运行**都做, 不只在下次
    # 抓包时做 —— 旧版只在 _PcapCaptureSession.start() 里调, 于是「下次运行
    # NetPulse 时自动清理」的承诺 (弹窗 / 盯障报告两处文案都这么写) 实际是
    # 「下次再抓包时才清理」: 用户半年不抓包, 旧的 pcap 就一直躺在磁盘上
    # (pcap 是要交给运营商的附件, 留着有隐私面)。
    try:
        _cleanup_old_captures()
    except Exception:
        pass

    # `netpulse diagnose <profile>` 子命令形式 (与 README/CHANGELOG 文档口径
    # 一致): 等价转写为 --diagnose <profile>, 剩余 token 仍按模块名处理
    if args.modules and args.modules[0] == "diagnose":
        profiles = "/".join(sorted(DIAGNOSE_PROFILES.keys()))
        if args.diagnose:
            print(_c("  错误: 'diagnose' 子命令与 --diagnose 不能同时使用", C_RED))
            sys.exit(4)
        if len(args.modules) < 2:
            print(_c(f"  用法: netpulse diagnose <profile>  (可选: {profiles})", C_RED))
            sys.exit(4)
        profile = args.modules[1]
        if profile not in DIAGNOSE_PROFILES:
            print(_c(f"  错误: 未知 profile '{profile}'  (可选: {profiles})", C_RED))
            sys.exit(4)
        args.diagnose = profile
        args.modules = args.modules[2:]

    # 禁用 scapy 二层抓包 (避免 Npcap 不稳定导致段错误)
    if args.no_scapy:
        global FORCE_NO_SCAPY, SCAPY_AVAILABLE
        FORCE_NO_SCAPY = True
        SCAPY_AVAILABLE = False
    # v1.9.7 PR-2: scapy 后台预加载 — argparse 只耗毫秒, 解析完即开线程,
    # 菜单渲染完时基本已加载完。必须放在 --no-scapy 置位之后: 此前在 main()
    # 入口启动时 FORCE_NO_SCAPY 还是 False, --no-scapy 下线程照常导 scapy,
    # 完成后把刚写的 SCAPY_AVAILABLE=False 覆盖回 True (v1.9.10 修复;
    # _load_scapy 里的 FORCE_NO_SCAPY 兜底是第二道防线)。
    _start_scapy_preload()

    # v1.12.0: 启动时后台检查更新 (daemon 线程, 失败静默)。
    # v1.14.6: force=True 每次启动真检查 (24h 频控曾让检查"看起来没生效")。
    # v1.14.8: 仅交互终端启动 (notice 只在菜单显示, CLI/--json 不该花流量);
    # 首帧前 join(2s) 等结果 — 否则线程总输给首次菜单渲染, 新版提示永远
    # "下一屏才出现"; 缓存预填让上次已发现的新版首帧立即可见。
    # NP_UPDATE_DEBUG=1 看 stderr 结果。离线最坏多等 2s (可接受)。
    if getattr(args, "no_update_check", False):
        pass
    elif sys.stdout.isatty():
        _prime_update_state_from_cache()
        _start_update_check(force=True).join(2.0)

    # v1.17.0: 异常上报开关 (CLI 显式指定优先于配置文件; 自动化场景用)。
    # 置位后同时跳过首次告知弹窗 —— 用户已用参数表过态, 不再打扰。
    _log_opt = getattr(args, "log_report", None)
    if _log_opt == "check":
        # v1.18.0: 自检 —— 不跑诊断, 只回答「这台机器能不能成功上报」。
        # 退出码 6 = 自检未通过 (与 0~5 的既有含义不冲突)。
        sys.exit(_log_report_selfcheck_cmd())
    if _log_opt in ("on", "off"):
        _set_log_reporting_enabled(_log_opt == "on")
        _mark_log_notice_shown()

    # 端口探测参数 -> 全局配置 (run_diagnostics 读取)
    # 注意: args.port_target 已经是 argparse action="append" 后的 list,
    # 每个元素是一个完整 spec (允许内部用逗号分隔多端口 / 用 - 范围)。
    # 多 host 必须用多个 --port-target, 例: --port-target a:80 --port-target b:80
    if args.port_target:
        targets = [p.strip() for p in args.port_target if p and p.strip()]
        PORT_PROBE_CONFIG["targets"] = targets or []
    PORT_PROBE_CONFIG["proto"] = args.port_proto
    PORT_PROBE_CONFIG["count"] = max(1, int(args.port_count))
    PORT_PROBE_CONFIG["force"] = bool(getattr(args, "port_force", False))
    PORT_PROBE_CONFIG["max_total_time"] = max(0.0, float(getattr(args, "port_timeout", 60.0)))
    PORT_PROBE_CONFIG["max_concurrency"] = max(1, min(64, int(getattr(args, "port_concurrency", 8))))

    # 测速参数 -> 全局配置 (runner -> SpeedTester.detect 读取)
    if args.iperf3_server:
        # v1.15.0 (审查 P1-7): 服务器地址进命令行, 必须先过合法性校验
        parsed_iperf3 = _parse_iperf3_server(args.iperf3_server)
        if parsed_iperf3 is None:
            print(_c(f"  错误: --iperf3-server 地址非法: {args.iperf3_server!r}", C_RED))
            print(_c("  只接受 IP 地址或主机名, 形如 1.2.3.4 / host.example.com / "
                     "host:5201 / [2400::1]:5201", C_GRAY))
            sys.exit(4)   # D2: 参数错
        SPEEDTEST_CONFIG["iperf3_server"], SPEEDTEST_CONFIG["iperf3_port"] = parsed_iperf3
    SPEEDTEST_CONFIG["use_speedtest_net"] = bool(args.speedtest_net)
    SPEEDTEST_CONFIG["node"] = getattr(args, "speedtest_node", None) or None
    # --speedtest-node 传数字 ID 时, 同时设为 Ookla 服务器 ID (覆盖默认 3633)
    sn = getattr(args, "speedtest_node", None)
    if sn and str(sn).strip().isdigit():
        SPEEDTEST_CONFIG["ookla_server_id"] = int(str(sn).strip())
    SPEEDTEST_CONFIG["iperf3_duration"] = max(1, int(getattr(args, "iperf3_duration", 10)))
    SPEEDTEST_CONFIG["iperf3_udp"] = bool(getattr(args, "iperf3_udp", False))

    # NAT 类型参数 -> 全局配置 (runner -> NATTypeTester.detect 读取)
    NATTYPE_CONFIG["servers"] = [s.strip() for s in (args.nattype_server or [])
                                 if s and s.strip()]

    # 网页体检参数 -> 全局配置 (runner -> WebPageTester.detect 读取)
    WEB_CONFIG["targets"] = [u.strip() for u in (args.web_target or [])
                             if u and u.strip()]

    # TCP 并发参数 -> 全局配置 (runner -> TCPConcurrencyTester.detect 读取)
    TCPCC_CONFIG["max"] = max(50, min(8000, int(getattr(args, "tcpcc_max", 4000) or 4000)))
    TCPCC_CONFIG["target"] = (getattr(args, "tcpcc_target", None) or "").strip() or None

    # 环回测速参数 -> 全局配置 (runner -> probe_loopback_v2 读取)
    _lb_scope = (getattr(args, "loopback_scope", None) or "unknown").strip().lower()
    LOOPBACK_CONFIG["scope"] = _lb_scope if _lb_scope in LOOPBACK_SCOPES else "unknown"
    LOOPBACK_CONFIG["duration"] = max(
        LOOPBACK_MIN_DURATION,
        min(LOOPBACK_MAX_DURATION,
            int(getattr(args, "loopback_duration", LOOPBACK_DEFAULT_DURATION) or 0)))

    if args.list:
        _print_module_list()
        return
    # 阶段 D · v1.4.0: --json-schema 输出当前 JSON Schema 版本号 (无需跑诊断)
    if args.json_schema:
        schema_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                   "schema")
        print(json.dumps({
            "schema_version": SCHEMA_VERSION,
            "schema_dir": schema_dir if os.path.isdir(schema_dir)
                          else f"(未生成 — 见 schema/{SCHEMA_FILENAME})",
            "app": APP_NAME,
            "version": APP_VERSION,
        }, ensure_ascii=False, indent=2))
        return
    # 阶段 D · v1.4.0: --debug-bundle 生成调试包 (脱敏的诊断快照)
    if args.debug_bundle:
        _export_debug_bundle(args.debug_bundle)
        return
    # v1.9.7 PR-3: --install-npcap 自提权重启的落点 — 装完不退出,
    # 直接进菜单 (提权窗口保持可用, 用户接着做需要管理员的事)
    if args.install_npcap:
        _run_install_npcap_entry()
        # 不 return: 继续走到底部的交互菜单
    # 按场景 Profile 诊断 (阶段 C · v1.3.0 引入): 跑 profile 模块后追加根因分析
    if args.diagnose:
        # v1.14.14: 同上 — --site 与 --diagnose 也是互斥顶层模式, 不再静默吞掉。
        if args.site:
            _warn_ignored_mode("diagnose", "site")
        # v1.15.0 (审查 P1-18): --monitor 与 --diagnose 同样是互斥顶层模式。
        # diagnose 分支在 monitor 分支**之前** return, 旧版连提示都没有 ——
        # 用户下了 "netpulse --diagnose gaming --monitor 300" 以为在盯障,
        # 实际只跑了一次场景诊断就退出, 白等一场。
        if args.monitor:
            _warn_ignored_mode("diagnose", "monitor")
        profile = args.diagnose
        keys = DIAGNOSE_PROFILES[profile]
        # v1.21.0: --json 时本分支的人读输出 (banner/分隔线/根因) 改道 stderr,
        # stdout 只留 run_diagnostics 的纯 JSON —— 与其 as_json 机制同一契约。
        # 非法/异常路径不受影响; 非 --json 输出逐字节不变。
        _json_err = sys.stderr if args.json else sys.stdout
        print(_c(f"  按场景诊断: {profile} "
                 f"(模块: {', '.join(keys)})", C_BOLD), file=_json_err)
        # v1.19.x: 跑诊断时占用备用屏幕 (固定宽高), 退出后结论写回正常屏幕
        _run_diagnostics_on_screen(
            keys, verbose=args.verbose, as_json=args.json,
            no_color=args.no_color, install=args.install,
            parallel=args.parallel, max_workers=args.max_workers,
            pip_mirror=args.pip_mirror)
        # 根因分析 (基于 run_diagnostics 写入的 LAST_RUN["results"])
        # v1.6.0 (PR-B): 按场景规则集评估, 避免 gaming 报 wifi 弱等无关根因
        if LAST_RUN and LAST_RUN.get("results"):
            diagnosis = diagnose(LAST_RUN["results"], rule_filter=profile)
            _saved_out = sys.stdout
            if args.json:
                sys.stdout = sys.stderr
            try:
                print(_c("─" * 60, C_BLUE))
                _print_diagnosis(diagnosis)
            finally:
                sys.stdout = _saved_out
        # 与 modules 路径同权: --export / --json-schema 等后续动作不再被吞
        # v1.6.1: 导出与屏幕同一规则集, 报告不再夹带过滤掉的根因
        if args.export:
            _export_reports(args.export, rule_filter=profile)
        _exit_with_status()
        return
    # 盯障模式: 独立顶层运行模式 (与模块诊断互斥)
    if args.capture and not args.monitor:
        # --capture 是 --monitor 的**子选项** (不是顶层模式), 措辞与下面的
        # 顶层模式互斥提示不同, 不共用 _warn_ignored_mode。
        print(_c("  提示: --capture 仅在 --monitor 盯障模式下生效, 本次已忽略", C_YELLOW))
    if args.monitor:
        # v1.14.14: --site / --monitor 是两个独立顶层模式, 互斥。原先 --site
        # 排在 --monitor 之后, 组合使用时被静默吞掉 (用户以为跑了现场检测,
        # 实际跑的是盯障) —— 与 --capture 的忽略提示保持一致, 明确告知。
        if args.site:
            _warn_ignored_mode("monitor", "site")
        # v1.7.0 (PR-F0): 主动负载 opt-in — --monitor-load 用默认 CDN 大文件,
        # --load-url 可覆盖地址; 两者都没给则不制造流量
        if args.monitor_load or args.load_url:
            load_url = args.load_url or MonitorSession.MONITOR_LOAD_URL
        else:
            load_url = None
        run_monitor_mode(args.monitor, ext_target=args.monitor_target,
                         load_url=load_url, capture_mode=args.capture,
                         capture_mb=args.capture_mb)
        return
    # 现场检测模式 (v1.13.0): 独立顶层运行模式 (需交互终端, 与模块互斥)
    if args.site:
        run_site_visit(customer=args.customer, install=args.install,
                       pip_mirror=args.pip_mirror)
        return
    if args.modules:
        # v1.15.0 (审查 P2): all / 0 / * 三者同义 (--list 收尾行就是这么写的),
        # 旧版只特判恰好 ["all"], 输 0 或 * 走 _parse_keys 报「未知模块」。
        is_all_only = (len(args.modules) == 1
                       and str(args.modules[0]).strip().lower() in ("all", "0", "*"))
        if is_all_only:
            keys = full_module_keys()
            if not args.json:      # JSON 输出不掺人读文本
                print(_c("  全量口径: 全部模块, 含压力级 tcpcc 压测 "
                         "(多目标轮转; debug-bundle 自动全诊断仍排除压力级)",
                         C_GRAY))
        else:
            keys = parse_module_names(args.modules)
        if not keys:
            print("可用模块: " + ", ".join(k for k, _, _ in MODULE_REGISTRY))
            sys.exit(4)  # D2: 参数错 (模块名无效)
        # 端口探测: 不管是 all 还是单选 port, 跑之前都要求用户输入目标
        # (用户偏好: 端口探测必须有显式目标, 不再有隐式默认)
        if "port" in keys and not PORT_PROBE_CONFIG.get("targets"):
            if sys.stdout.isatty():
                prompted = _prompt_for_port_targets()
                if prompted is None:
                    print(_c("  已取消端口探测。", C_YELLOW))
                    return
                tgt, proto, cnt = prompted
                PORT_PROBE_CONFIG["targets"] = tgt
                PORT_PROBE_CONFIG["proto"] = proto
                PORT_PROBE_CONFIG["count"] = cnt
            else:
                print(_c("  错误: 端口探测必须指定目标。", C_RED))
                print(_c("  用法: netpulse.py port --port-target HOST:PORT [...]", C_GRAY))
                print(_c("  例:   netpulse.py port --port-target 192.168.1.1:443,8.8.8.8:53", C_GRAY))
                print(_c("       或: netpulse.py all --port-target 8.8.8.8:53", C_GRAY))
                sys.exit(4)  # D2: 参数错 (缺少 --port-target)
        # v1.19.x: 跑诊断时占用备用屏幕 (固定宽高), 退出后结论写回正常屏幕
        _run_diagnostics_on_screen(
            keys, verbose=args.verbose, as_json=args.json,
            no_color=args.no_color, install=args.install,
            parallel=args.parallel, max_workers=args.max_workers,
            pip_mirror=args.pip_mirror)
        if args.export:
            _export_reports(args.export)
        _exit_with_status()
        return
    # 无参数/显式 --gui → 图形界面 (v1.21.0); --cli 或非 TTY → 传统菜单。
    if _gui_wanted(args, sys.stdout.isatty() if sys.stdout else False):
        # 终审 #4: pip 镜像透传 (与其他分支同口径), 否则 GUI 内装依赖固定走自动选源
        _run_gui(install=True, pip_mirror=args.pip_mirror)
        return
    interactive_menu(install=args.install, pip_mirror=args.pip_mirror)


def _write_error_log(level, exc, tb_text=None):
    """把事件的完整 traceback 追加写到报告目录, 供现场回传排查。

    返回日志路径; 写不进去返回 None (不能因为写日志失败而二次崩溃)。
    """
    try:
        base = os.path.dirname(_report_dir())      # <程序目录>/reports
        path = os.path.join(base, "netpulse_error.log")
        if tb_text is None:
            tb_text = "".join(traceback.format_exception(
                type(exc), exc, exc.__traceback__))
        with open(path, "a", encoding="utf-8") as f:
            f.write("\n===== %s [%s] %s =====\n" % (
                datetime.now().isoformat(), str(level).upper(),
                type(exc).__name__))
            f.write(tb_text)
        return path
    except Exception:
        return None


# ── 远程日志上报 (v1.17.0) ─────────────────────────────────────
# 现场问题闭环: 程序跑在客户机器上, 出问题只有本机日志, 厂商拿不到 -> 只能等
# 用户截图/回传, 复现率极低 (v1.16.1 的提权重启崩溃就是这样才暴露出来的)。
# 这里把**软件自身的问题**推送到统一日志服务器, 让优化闭环不依赖用户配合。
#
# 上报范围 (已确认): 只报软件自身问题 —— 崩溃 / 模块异常 / 后台线程静默死亡 /
# 内部降级。**不含任何客户网络诊断数据** (不碰公网 IP / MAC / SSID / 丢包率 /
# 延迟 / 诊断结论 / 客户名)。
#
# 设计取舍:
#  - 渠道: 统一日志服务 (POST JSON)。客户机上零配置 —— 端点与 token 内置在
#    exe 里; 换服务器用环境变量覆盖, 不用重新打包。
#  - 凭据: 内置固定 token (逆向可得, 因此服务端**必须**限流 + 字段白名单;
#    该 token 只能写日志, 不能读写其它数据)。
#  - 开关: 默认开启, 但首次运行弹窗告知并可关闭 (客户知情权)。
#    开关状态存 %LOCALAPPDATA%\NetPulse\log_report.json。
#  - 内容: 异常类型 + traceback + 系统版本 + NetPulse 版本 + 模块/线程上下文。
#  - 隐私: traceback 里可能带用户路径 / 机器名 / SSID, 上报前统一脱敏。
#  - 绝不阻塞主流程: 上报失败只写本地日志, 不影响退出码与用户操作。

# 日志服务端端点 (POST JSON)。换服务器: 设环境变量 NETPULSE_LOG_URL 即可。
LOG_SERVER_URL = "https://router.silentcrow.top:9800/v1/logs"
# 内置写入 token。**这是公开写权限** (exe 可逆向) —— 服务端必须限流 + 字段
# 白名单。它只能写日志, 不能读库/改配置, 故泄露影响可控。
LOG_SERVER_TOKEN = "app-tk_87a4d0bc31508c1f0b10dd8eb116f165"
# 端点 / token 覆盖环境变量 (换服务器不必重新打包)
LOG_URL_ENV = "NETPULSE_LOG_URL"
LOG_TOKEN_ENV = "NETPULSE_LOG_TOKEN"
# 源码运行放行开关 (v1.18.2): 上报通道是给**客户机上的 exe** 用的 ——
# 开发机/测试机跑出来的栈只会往厂商通道灌噪音, 还带着本机目录结构。
# 2026-11-03 就被自家回归测试灌了两条 `RuntimeError: boom` 到线上日志。
# 非打包运行默认**不自动上报** (本地日志照写); 要联调设本变量=1 放行。
LOG_ALLOW_SOURCE_ENV = "NETPULSE_LOG_ALLOW_SOURCE"
LOG_TIMEOUT_S = 10
# 协议允许的 type 取值 (缺省 info)
LOG_LEVELS = ("critical", "error", "warn", "info", "debug")
LOG_MAX_STACK_CHARS = 12000
LOG_MAX_MESSAGE_CHARS = 2000
# 同一处同一异常最多上报几次 (防崩溃循环 / 盯障模式刷屏)
LOG_MAX_REPORTS_PER_KEY = 3
# 单轮诊断最多上报几条模块异常 (客户网络全断时 23 个模块会集体失败)
LOG_RUN_BUDGET = 5
# 本轮已上报条数计数器 (run_diagnostics 开头重置)
_LOG_RUN_STATE = {"sent": 0}
# 本地日志限频计数器 {指纹: 次数}。盯障模式 24h 循环里同一处失败会重复上万次,
# 不限频就把 netpulse_error.log 撑爆 (进程内有效, 每次启动重新计数)。
_LOG_LOCAL_SEEN = {}

# 服务端证书说明 (v1.18.0)
# 服务端用的是 **Let's Encrypt 公用 CA 签发**的证书
# (CN=router.silentcrow.top, Issuer=CN=YE1 O=Let's Encrypt, 链到 ISRG Root X1,
#  有效期 90 天)。客户端**走系统信任链验证**, 不内置任何证书。
#
# ⚠ **不要 pin Let's Encrypt 证书**: LE 证书 90 天轮换, 内置进 exe 等于给
# 所有客户端埋 90 天后的定时炸弹 —— 换证后全部客户端证书校验失败, 上报静默
# 失效, 且现场毫无察觉。
#
# 需要固定信任某张证书时, pin 的必须是**长期有效的自签 CA** (BasicConstraints
# CA=True + SAN 含访问域名), 且服务端换证时要同步更新客户端。
# 客户端侧只保留一句代码即可:
#     ctx.load_verify_locations(cadata=LOG_PINNED_CERT_PEM)
# 但 v1.18.0 起**不启用** (服务端已是公用 CA) —— tests/test_log_report.py
# 有断言守着, 防止有人把 LE 证书填进去。


def _log_ssl_context():
    """日志上报用的 SSL 上下文: **系统信任链**, 校验全程开启。

    `check_hostname` 与 `CERT_REQUIRED` 都保持开启 —— 关闭等于「加密但不认证」,
    中间人可读全部栈信息。
    """
    return ssl.create_default_context()


def _log_config_path():
    """上报配置路径: %LOCALAPPDATA%\\NetPulse\\log_report.json"""
    base = os.environ.get("LOCALAPPDATA") or tempfile.gettempdir()
    return os.path.join(base, "NetPulse", "log_report.json")


def _load_log_config():
    """读上报配置。返回 dict (损坏时返回默认, 不抛异常)。"""
    try:
        with open(_log_config_path(), encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, dict) else {}
    except Exception:
        return {}


def _save_log_config(cfg):
    """写上报配置 (失败静默 —— 上报开关存不住不该影响程序运行)。"""
    try:
        path = _log_config_path()
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            json.dump(cfg, f, ensure_ascii=False, indent=2)
        return True
    except Exception:
        return False


def _log_reporting_enabled():
    """上报是否启用。默认 True (首次运行由菜单弹窗告知并征询)。"""
    if os.environ.get("NETPULSE_LOG_REPORT") == "0":
        return False
    cfg = _load_log_config()
    return bool(cfg.get("enabled", True))


def _report_allowed_from_source():
    """当前进程是否允许自动上报到日志服务器。

    打包后的 exe (客户机) → 允许。
    源码运行 (开发机 / 回归测试) → 默认**不允许**: 那些栈对现场诊断没有价值,
    只会污染厂商的错误通道, 还把本机目录结构一并送出去。真要联调可设
    ``NETPULSE_LOG_ALLOW_SOURCE=1`` 放行。

    注意: 只管**自动**上报 (崩溃 / 模块异常 / 线程异常)。
    ``--log-report check`` 自检是用户显式发起的, 走另一条路, 不受此限制。
    """
    if getattr(sys, "frozen", False):
        return True
    return os.environ.get(LOG_ALLOW_SOURCE_ENV) == "1"


def _set_log_reporting_enabled(enabled):
    """设置上报开关并落盘。返回是否写入成功。"""
    cfg = _load_log_config()
    cfg["enabled"] = bool(enabled)
    cfg["updated_at"] = datetime.now().isoformat()
    return _save_log_config(cfg)


def _log_reported_counts():
    """已上报次数表 {异常指纹: 次数} (用于限流)。"""
    cfg = _load_log_config()
    counts = cfg.get("reported")
    return counts if isinstance(counts, dict) else {}


def _log_bump_reported(key):
    """记录某异常指纹已上报 N 次 (超限不再上报, 仍照常落盘)。"""
    cfg = _load_log_config()
    counts = cfg.get("reported")
    if not isinstance(counts, dict):
        counts = {}
    counts[key] = int(counts.get(key, 0)) + 1
    cfg["reported"] = counts
    _save_log_config(cfg)


def _log_os_string():
    """上报用的终端标识: 系统版本串 (不含 hostname 等任何身份信息)。"""
    try:
        system = platform.system() or ""
    except Exception:
        system = ""
    try:
        version = platform.version() or ""
    except Exception:
        version = ""
    try:
        machine = (platform.machine() or "").lower()
    except Exception:
        machine = ""
    if machine in ("amd64", "x86_64"):
        machine = "x64"
    elif machine in ("i386", "i686", "x86"):
        machine = "x86"
    parts = [p for p in (system, version, machine) if p]
    return " ".join(parts) or "unknown"


def _log_now_iso():
    """客户端时间戳: ISO8601 毫秒 + 本机时区偏移 (服务端存库归一化为 UTC)。

    **必须客户端带 ts** —— 崩溃发生时刻与接收时刻可能相差很久 (机器离线 /
    限流丢弃 / 重试), 排查时需要真实发生时间, 不能用服务端接收时刻。
    """
    try:
        return datetime.now().astimezone().isoformat(timespec="milliseconds")
    except Exception:
        return datetime.now().isoformat()


def _log_sanitize_text(text):
    """对上报文本做隐私脱敏。

    traceback 里最常见的隐私是**用户路径** (C:\\Users\\张三\\...)、**机器名**、
    **SSID** 与**公网 IP**。用户目录/机器名走精确替换, SSID 走正则 (尽力而为,
    不保证 100%), 公网 IP 与 MAC 复用调试包既有的值级打码口径。
    内网 IP **保留** —— 定位现场问题必需。
    """
    if not text:
        return ""
    text = str(text)
    # 用户目录 -> <user> (含中文/英文用户名)
    try:
        userprofile = os.environ.get("USERPROFILE", "")
        if userprofile:
            text = text.replace(userprofile, "<user>")
        home = os.path.expanduser("~")
        if home and home not in ("~",):
            text = text.replace(home, "<user>")
    except Exception:
        pass
    # 机器名 -> <host> (长度 <4 不替换 —— 短机器名会把正文误伤成一片)
    try:
        hostname = socket.gethostname()
        if hostname and len(hostname) >= 4:
            text = re.sub(re.escape(hostname), "<host>", text,
                          flags=re.IGNORECASE)
    except Exception:
        pass
    # SSID -> *** (尽力而为: 只覆盖 "SSID: xxx" 这类带标签的写法)
    try:
        text = re.sub(r"(SSID\s*[:：=]\s*)\S+", r"\1***", text,
                      flags=re.IGNORECASE)
        text = re.sub(r"(无线网络名称\s*[:：=]\s*)\S+", r"\1***", text)
    except Exception:
        pass
    # 公网 IP / IPv6 / MAC -> 复用调试包既有的值级打码
    try:
        text = _mask_mac_text(_redact_text_value(text))
    except Exception:
        pass
    return text


def _log_fingerprint(scope, exc):
    """异常指纹: 版本 + 作用域 + 异常类型 + 出错位置 (去掉行号, 跨版本稳定)。

    用于限流去重 —— 同一处同一异常类型只报 N 次, 防崩溃循环/盯障模式刷屏。
    **带版本号**: 计数跨版本累计会让「修好了的老问题」永远不再上报,
    每个版本各自重新计 3 次才能看出「这问题还在复发」。
    """
    try:
        tb = traceback.extract_tb(exc.__traceback__)
        loc = ""
        if tb:
            last = tb[-1]
            loc = "%s:%s" % (os.path.basename(last.filename), last.name)
        return "v%s|%s@%s@%s" % (APP_VERSION, scope, type(exc).__name__, loc)
    except Exception:
        try:
            return "v%s|%s@%s" % (APP_VERSION, scope, type(exc).__name__)
        except Exception:
            return scope or "unknown"


def _log_message(scope, exc, detail=None):
    """组装 message: v<版本> [<作用域>] <异常类型>: <细节>。

    协议没有独立的 metadata 字段, 上下文 (版本/模块/线程) 只能编码进 message。
    固定前缀便于服务端机器解析。
    """
    try:
        kind = type(exc).__name__
    except Exception:
        kind = "Exception"
    text = ""
    try:
        text = str(exc).strip().replace("\r", " ").replace("\n", " ")
    except Exception:
        text = ""
    if len(text) > 300:
        text = text[:300] + "..."
    head = "v%s [%s] %s" % (APP_VERSION, scope or "未知", kind)
    if detail:
        return "%s: %s" % (head, str(detail))
    if text:
        return "%s: %s" % (head, text)
    return head


def _log_payload(level, message, stack=None, ts=None):
    """构造上报负载 —— 严格用协议约定的字段 (app/type/message/stack/ts/os)。

    服务端实测约束 (2026-11-02): `message` 不能为空 (400), `type` 必须是
    critical|error|warn|info|debug (400), `ts` 必须是 RFC3339 (400)。
    这里全部在客户端侧先兜住 —— 一次非法请求不会浪费服务端配额。
    """
    if level not in LOG_LEVELS:
        level = "error"
    message = _log_sanitize_text(message)[:LOG_MAX_MESSAGE_CHARS].strip()
    if not message:
        # message 为空服务端直接 400 —— 兜底成一条占位摘要, 不丢这次事件。
        message = "v%s [未知] %s" % (APP_VERSION, level)
    payload = {
        "app": "netpulse",
        "type": level,
        "message": message,
    }
    if stack:
        payload["stack"] = _log_sanitize_text(stack)[:LOG_MAX_STACK_CHARS]
    payload["ts"] = ts or _log_now_iso()
    payload["os"] = _log_os_string()
    return payload


def _log_endpoint():
    """上报端点 URL (环境变量优先, 便于换服务器不改 exe)。"""
    return (os.environ.get(LOG_URL_ENV) or LOG_SERVER_URL).strip()


def _log_token():
    """上报 token (环境变量优先)。"""
    return (os.environ.get(LOG_TOKEN_ENV) or LOG_SERVER_TOKEN).strip()


def _post_log(payload, timeout=LOG_TIMEOUT_S):
    """把负载 POST 到日志服务端。返回 (ok, msg)。

    鉴权用内置 token (X-Token 头)。token 是公开写权限, 服务端必须限流 ——
    这是客户端无法弥补的, 由服务端负责。

    服务端错误约定 (实测): 4xx + `{"ok": false, "error": "..."}`。
    `error` 是中文可读原因 (如 "第 1 条: message 不能为空"), **必须透传** ——
    压成 "HTTP Error 400" 等于把排查线索全丢了。
    """
    url = _log_endpoint()
    if not url:
        return False, "未配置上报端点"
    token = _log_token()
    if not token:
        return False, "未配置 X-Token"
    body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
    try:
        with _urlopen_with_proxy(
            url, timeout=timeout, ua="NetPulse/%s" % APP_VERSION,
            data=body, method="POST",
            headers={
                "Content-Type": "application/json; charset=utf-8",
                "X-Token": token,
                "X-NetPulse-Version": str(APP_VERSION),
            },
            context=_log_ssl_context(),
        ) as resp:
            raw = resp.read().decode("utf-8", "ignore")
            status = getattr(resp, "status", None) or getattr(resp, "code", 0)
        try:
            status = int(status)
        except Exception:
            status = 0
        if status >= 400:
            return False, "服务端拒绝 HTTP %s: %s" % (status, raw[:200])
        try:
            data = json.loads(raw)
        except Exception:
            data = {}
        if isinstance(data, dict) and data.get("ok") is False:
            return False, "服务端拒绝: %s" % (data.get("error") or "未知原因")
        return True, str(data.get("id") or data.get("message")
                         or raw[:120] or "已接收")
    except Exception as e:
        # HTTPError: 服务端 4xx/5xx。解析响应体里的 error 字段透传可读原因。
        detail = ""
        try:
            raw = e.read().decode("utf-8", "ignore")
            data = json.loads(raw)
            if isinstance(data, dict):
                detail = str(data.get("error") or "")
            elif raw:
                detail = raw[:200]
        except Exception:
            pass
        code = getattr(e, "code", None)
        if detail:
            return False, "服务端拒绝%s: %s" % (
                (" HTTP %s" % code) if code else "", detail)
        # 证书校验失败: 服务端可能换了证书 —— 给出可行动的原因, 别只丢栈
        raw_err = str(e)
        if ("CERTIFICATE_VERIFY_FAILED" in raw_err
                or "certificate verify failed" in raw_err.lower()
                or "self-signed certificate" in raw_err.lower()):
            return False, ("TLS 证书校验失败（服务端证书可能已更换，"
                           "需同步更新客户端内置的 pin 证书）: %s" % raw_err)
        return False, "上报失败: %s: %s" % (type(e).__name__, e)


def _emit_runtime_event(level, exc, scope, detail=None, tb_text=None):
    """统一上报出口: 写本地日志 + (按开关)推送到日志服务器。返回 (ok, msg)。

    **绝不影响主流程**: 内部吞掉一切异常, 返回 (False, 原因)。
    关闭上报 / 超过限流 -> 只落盘不上报。

    本地日志与远端上报**分别限频**: 盯障模式 24h 循环里同一处失败会重复上万次,
    两边都不限频就是「本地日志撑爆 + 服务端被刷屏」双输。
    """
    try:
        if tb_text is None:
            tb_text = "".join(traceback.format_exception(
                type(exc), exc, exc.__traceback__))
    except Exception:
        tb_text = ""
    try:
        key = _log_fingerprint(scope, exc)
    except Exception:
        key = scope or "unknown"
    # 本地日志限频 (进程内)
    seen = _LOG_LOCAL_SEEN.get(key, 0)
    if seen < LOG_MAX_REPORTS_PER_KEY:
        try:
            _write_error_log(level, exc, tb_text)
        except Exception:
            pass
        _LOG_LOCAL_SEEN[key] = seen + 1
    try:
        if not _log_reporting_enabled():
            return False, "上报已关闭"
        # v1.18.2: 源码运行 (开发机 / 回归测试) 不自动上报 —— 上报通道是给
        # 客户机上的 exe 用的。本地日志照写 (上面已写), 只是不往线上推。
        if not _report_allowed_from_source():
            return False, "源码运行不自动上报 (设 %s=1 放行)" % LOG_ALLOW_SOURCE_ENV
        if _log_reported_counts().get(key, 0) >= LOG_MAX_REPORTS_PER_KEY:
            return False, "同类异常上报次数已达上限, 仅落盘"
        payload = _log_payload(level, _log_message(scope, exc, detail),
                               stack=tb_text)
        ok, msg = _post_log(payload)
        if ok:
            _log_bump_reported(key)
        return ok, msg
    except Exception as e:
        return False, "上报异常: %s" % type(e).__name__


def _emit_thread_failure(exc, scope, detail=None):
    """后台线程里的异常 —— 写本地日志 + 异步推送 (不打断线程自身流程)。

    用于「静默死亡」改造: 这些点原本 `except Exception: pass`, 客户机表现为
    「没报错但也没结果」—— 报告呈现「0 丢包」之类的假象, 用户与厂商都看不出来。
    """
    try:
        tb_text = "".join(traceback.format_exception(
            type(exc), exc, exc.__traceback__))
    except Exception:
        tb_text = ""
    try:
        _emit_runtime_event_async("error", exc, scope, detail=detail,
                                  tb_text=tb_text)
    except Exception:
        pass


def _emit_runtime_event_async(level, exc, scope, detail=None, tb_text=None,
                              wait=0.0, announce=False):
    """异步上报 —— 后台线程发起, 主流程最多等 wait 秒。

    wait=0: 完全不等 (fire-and-forget), 适合诊断过程中的模块异常 ——
            绝不能让上报拖住用户正在跑的检测。
    wait>0: 限时等待 (崩溃路径用), 网络不通时不能拖住用户退出。
    """
    result = {}

    def _worker():
        try:
            result["ok"], result["msg"] = _emit_runtime_event(
                level, exc, scope, detail=detail, tb_text=tb_text)
        except Exception as e:
            result["ok"], result["msg"] = False, "上报异常: %s" % e

    t = threading.Thread(target=_worker, name="log-report", daemon=True)
    t.start()
    if wait:
        t.join(timeout=wait)   # 限时等待; 线程是 daemon, 进程退出即终止
    if announce:
        if result.get("ok"):
            try:
                print(_c("    ✓ 已自动上报 (%s)" % result.get("msg"), C_GRAY))
            except Exception:
                pass
        else:
            msg = result.get("msg") or "未完成"
            try:
                print(_c("    (自动上报未完成: %s; 本地日志已保留)" % msg,
                         C_GRAY))
            except Exception:
                pass
    return bool(result.get("ok"))


def _emit_probe_failure(key, exc, tb_text=None, detail=None):
    """模块/探针异常上报 —— 受单轮预算约束。

    客户网络全断时 23 个模块会集体失败, 不设预算就是 23 条齐飞; 超预算的
    只写本地日志。
    """
    try:
        if _LOG_RUN_STATE.get("sent", 0) >= LOG_RUN_BUDGET:
            try:
                _write_error_log("error", exc, tb_text)
            except Exception:
                pass
            return False
        _LOG_RUN_STATE["sent"] = _LOG_RUN_STATE.get("sent", 0) + 1
        _emit_runtime_event_async("error", exc, "模块:%s" % key,
                                   detail=detail, tb_text=tb_text)
        return True
    except Exception:
        return False


def _exc_meta(scope, exc):
    """异常元数据 (留在模块结果里, **不含栈**)。

    栈只在推送那一刻用 —— 不进 LAST_RUN、不进客户交付物 (隐私)。
    但异常类型必须留下来: 旧路径只留 str(e), 报告层根本分不清是
    TimeoutError 还是 PermissionError。
    """
    try:
        etype = type(exc).__name__
    except Exception:
        etype = "Exception"
    try:
        msg = str(exc)
    except Exception:
        msg = ""
    return {
        "type": etype,
        "message": _log_sanitize_text(msg)[:300],
        "scope": scope,
    }


def _rdn_flat(items):
    """把 ssl.getpeercert() 的 subject/issuer 结构拍平成一行可读文本。

    结构: `((('commonName', 'x'), ('organizationName', 'y')),)` ——
    外层每项是一个 RDN 组, 组内是若干 (key, value) 对。
    """
    out = []
    try:
        for rdn in (items or ()):
            pairs = (rdn if (isinstance(rdn, (list, tuple)) and rdn
                             and isinstance(rdn[0], (list, tuple)))
                     else (rdn,))
            for pair in pairs:
                try:
                    k, v = pair
                    out.append("%s=%s" % (k, v))
                except Exception:
                    out.append(str(pair))
    except Exception:
        return ""
    return " / ".join(out)


def _log_tls_probe(hostname, port):
    """TLS 握手 + 证书链校验 —— **不发任何请求**。

    返回信息行 list; 抛异常表示握手/校验失败 (调用方转成可读原因)。
    独立成函数是为了可测: 单元测试 mock 它, 不必伪造 socket 内部接口。
    """
    lines = []
    ctx = _log_ssl_context()
    with socket.create_connection((hostname, port),
                                  timeout=LOG_TIMEOUT_S) as sock:
        with ctx.wrap_socket(sock, server_hostname=hostname) as ssock:
            lines.append("TLS      : %s / %s" % (ssock.version(),
                                                 ssock.cipher()[0]))
            cert = ssock.getpeercert() or {}
            try:
                subj = _rdn_flat(cert.get("subject"))
                issuer = _rdn_flat(cert.get("issuer"))
                if subj:
                    lines.append("证书     : %s" % subj)
                if issuer:
                    lines.append("签发者   : %s" % issuer)
                if cert.get("notAfter"):
                    lines.append("有效期至 : %s" % cert.get("notAfter"))
            except Exception:
                pass
    return lines


def _log_report_selfcheck(verbose=True):
    """异常上报自检 —— 现场一条命令拿到「这台机器能不能成功上报」的结论。

    **为什么需要**: 上报是**后台静默**的。证书校验失败 / 根证书库陈旧
    (Win7 等停止更新根证书的机器) / 企业代理 MITM 重签证书 —— 这三种情况
    都会让上报悄悄失效: 厂商收不到任何东西, 却以为「客户机器没崩」。
    自检把「不知道」变成「明确结论」。

    三步: ① 配置与开关状态 ② TLS 握手 + 证书链校验 ③ 实发一条测试日志。

    返回 (ok, 输出行 list)。ok=False 表示**上报链路不可用**。
    """
    lines = []
    ok_all = True

    # ① 配置与开关
    url = _log_endpoint()
    token = _log_token()
    enabled = _log_reporting_enabled()
    lines.append("端点     : %s" % url)
    lines.append("token    : %s" % ("已配置 (%s…)" % token[:12]
                                  if token else "未配置 —— 无法上报"))
    lines.append("上报开关 : %s" % ("开启" if enabled
                                    else "关闭（只写本地日志，不联网）"))
    if not token:
        ok_all = False
        lines.append("  ✗ 未配置 token")

    # ② TLS 握手 + 证书链校验 (不发请求)
    tls_ok = False
    host = url.split("//", 1)[-1].split("/", 1)[0]
    hostname, _, port_s = host.partition(":")
    try:
        port = int(port_s) if port_s else (443 if url.startswith("https") else 80)
    except Exception:
        port = 443
    try:
        lines.extend(_log_tls_probe(hostname, port))
        tls_ok = True
    except ssl.SSLCertVerificationError as e:
        ok_all = False
        lines.append("  ✗ 证书校验失败: %s" % e)
        lines.append("    → 本机根证书库可能陈旧, 或服务端证书有问题")
    except Exception as e:
        ok_all = False
        lines.append("  ✗ 连接失败: %s: %s" % (type(e).__name__, e))

    # ③ 实发一条测试日志 (开关关闭时跳过 —— 不违背用户的关闭意图)
    if tls_ok:
        if enabled:
            payload = _log_payload(
                "info", "v%s [自检] 上报链路连通性测试 (非故障)" % APP_VERSION)
            ok, msg = _post_log(payload)
            lines.append("实发测试 : %s" % ("成功 (%s)" % msg.strip()
                                            if ok else "失败 —— %s" % msg))
            if not ok:
                ok_all = False
        else:
            lines.append("实发测试 : 已跳过（上报开关关闭）")

    lines.append("")
    lines.append("结论: %s" % ("上报链路可用" if ok_all
                               else "**上报链路不可用** —— 异常将只写本地日志"))
    if verbose:
        try:
            for line in lines:
                print(_c("  " + line, C_GRAY))
        except Exception:
            pass
    return ok_all, lines


def _log_report_selfcheck_cmd():
    """CLI `--log-report check` 的入口。返回进程退出码。"""
    print(_c("  异常上报自检", C_CYAN))
    print(_c("  " + "-" * 54, C_GRAY))
    try:
        ok, _lines = _log_report_selfcheck(verbose=True)
    except Exception as e:
        print(_c("  ✗ 自检异常: %s: %s" % (type(e).__name__, e), C_RED))
        return 6
    if ok:
        print(_c("  ✓ 自检通过", C_GREEN))
        return 0
    print(_c("  ✗ 自检未通过 (退出码 6)", C_RED))
    return 6


def _install_thread_excepthook():
    """v1.17.0: 捕获后台线程的未捕获异常并上报。

    动机: 顶层 except 只兜住主线程。NetPulse 有多个 daemon 后台线程
    (scapy 预加载 / 盯障 / 测速 / 更新检查), 线程里的未捕获异常默认只打到
    stderr 就消失 —— 客户机上表现为「没报错但也没结果」, 厂商完全看不到。
    这里装 threading.excepthook, 把这类异常一并纳入上报。

    注意: 只上报, 不改变原异常传播语义 (不吞异常, 不影响线程退出)。
    """
    def _hook(args):
        try:
            exc = args.exc_value
            if exc is None:
                return
            tb_text = "".join(traceback.format_exception(
                type(exc), exc, exc.__traceback__))
            try:
                _write_error_log("error", exc, tb_text)
            except Exception:
                pass
            try:
                _emit_runtime_event_async(
                    "error", exc,
                    "线程:%s" % (args.thread.name if args.thread else "未知"),
                    tb_text=tb_text)
            except Exception:
                pass
        except Exception:
            pass

    try:
        threading.excepthook = _hook
        return True
    except Exception:
        return False


def _cli_entry():
    """main() 的外层保护: 未预期异常不再抛裸 traceback。

    v1.15.0 (审查 P2): 现场崩了就白跑一趟 —— 诊断跑了 2 分钟, 报告还没落盘,
    装维只看到一屏 Python 栈, 既看不懂也不知道该重跑还是换环境。
    这里兜住未预期异常: 打印一行可读原因 + 退出码 3 (与 compute_exit_code 的
    「工具执行失败」同码), 并把完整 traceback 写到 reports/netpulse_error.log。

    不改动的: SystemExit (argparse 的退出码 2/4 等) 原样抛出;
    KeyboardInterrupt 单独处理 (Ctrl+C 不是错误, 退出码 130)。
    """
    # v1.17.0: 装后台线程异常钩子 (主线程以外的崩溃也要能上报)
    try:
        _install_thread_excepthook()
    except Exception:
        pass
    try:
        main()
    except KeyboardInterrupt:
        try:
            print(_c("\n  已取消 (Ctrl+C)。", C_YELLOW))
        except Exception:
            pass
        sys.exit(130)
    except SystemExit:
        raise
    except Exception as exc:
        name = type(exc).__name__
        try:
            print(_c(f"\n  ✗ 发生未预期错误 ({name}): {exc}", C_RED))
        except Exception:
            pass
        log_path = _write_error_log("critical", exc)
        if log_path:
            try:
                print(_c(f"    完整错误信息已写入: {log_path}", C_GRAY))
                print(_c("    可连同该文件一起回传, 便于排查。", C_GRAY))
            except Exception:
                pass
        else:
            try:
                print(_c("    (错误日志写入失败, 请改用 --verbose 重跑一次)", C_GRAY))
            except Exception:
                pass
        # v1.17.0: 自动上报到日志服务器 (脱敏后)。
        # 异步上报 + 短超时 —— 网络慢/不通时不能拖住用户退出。
        try:
            _emit_runtime_event_async("critical", exc, "崩溃",
                                      wait=LOG_TIMEOUT_S + 5, announce=True)
        except Exception:
            pass
        sys.exit(3)     # 3 = 工具执行失败 (与 compute_exit_code 口径一致)


if __name__ == "__main__":
    _cli_entry()
